source:
"use client";

// P4 · 每日委托
//
// 页面任务：让「知穗主动来找你」这件事**可配置、可预期、可追溯**。
//   · 可配置 —— 右侧表单常驻（不弹窗、不遮挡列表），左宽右窄
//   · 可预期 —— 每条都写清「什么时候触发」和「下次什么时候」
//   · 可追溯 —— 执行历史按 trigger 区分定时 / 手动，排查「今天为什么没收到」看这一列
//
// 关键设计点：**「预览」不投递**。
// 后端给的是 `POST /{id}/run?dry_run=true`（只生成、不改 next_run_at），
// 这正好是产品方向文档要的「系统先跑一遍，人再确认」—— 先看到内容，再决定投不投。
import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import PageShell from "@/components/console/PageShell";
import CornIcon from "@/components/CornIcon";
import { Callout, Field, NotReady, Seg, SkeletonLines, Switch, ToastHost } from "@/components/console/ui";
import { api } from "@/lib/api";
import { useAuth } from "@/lib/hooks/useAuth";
import { DEMO_DELEGATES, DEMO_RUNS } from "@/lib/consoleDemo";
import { errProbe, toProbe, type ProbeState } from "@/lib/probe";
import { fmtDuration, fmtNum, fmtRemaining, fmtWhen } from "@/lib/time";
import { useToast } from "@/lib/hooks/useToast";
import type {
  Conversation,
  Delegate,
  DelegateFreq,
  DelegateKind,
  DelegateRun,
  DelegateRunStatus,
  KbInfo,
} from "@/lib/types";

/** 启用中的委托上限。写在页面上，别让用户撞到 400 才知道 */
const MAX_ACTIVE = 5;
/** 执行历史默认露几条：再多的收进「查看全部」（2026-11-17） */
const HIST_PEEK = 3;
const TZ = "Asia/Shanghai";

const KIND_OPTIONS: { value: DelegateKind; label: string }[] = [
  { value: "study_plan", label: "学习计划" },
  { value: "review", label: "复盘" },
  { value: "encourage", label: "鼓励" },
  { value: "custom", label: "自定义" },
];
const KIND_LABEL: Record<DelegateKind, string> = {
  study_plan: "学习计划",
  review: "复盘",
  encourage: "鼓励",
  custom: "自定义",
};

const FREQ_OPTIONS: { value: DelegateFreq; label: string; hint: string }[] = [
  { value: "daily", label: "每天", hint: "每天同一时刻" },
  { value: "weekdays", label: "工作日", hint: "周一到周五" },
  { value: "weekly", label: "每周", hint: "每周固定一天" },
  { value: "interval", label: "间隔", hint: "每隔 N 分钟一次" },
];

// 下标即后端 weekday 取值：0=周一 … 6=周日（见 api/delegate.py 的 ScheduleIn.weekday）。
// 顺序刻意从「一」开始：第 0 项必须和「周一」对上，否则每周委托整体错一天。
const WEEKDAYS = ["一", "二", "三", "四", "五", "六", "日"];

const RUN_TAG: Record<DelegateRunStatus, [string, string]> = {
  succeeded: ["ok", "成功"],
  failed: ["bad", "失败"],
  running: ["info", "运行中"],
  pending: ["info", "排队中"],
  skipped: ["warn", "已跳过"],
};

/** 把结构化 schedule 翻译成一句人话。用户不该看到 cron。 */
function scheduleText(d: Delegate): string {
  const s = d.schedule;
  const at = s.at ?? "—";
  if (s.freq === "interval") return `每 ${s.every_minutes ?? "?"} 分钟`;
  if (s.freq === "daily") return `每天 ${at}`;
  if (s.freq === "weekdays") return `工作日 ${at}`;
  return `每周${WEEKDAYS[s.weekday ?? 0]} ${at}`;
}

/** 列表里的一行：要么是分组标题，要么是一条委托。拍平成一个数组，
 *  渲染时只写一次委托卡 JSX —— 分层嵌套写两遍最容易两边改漏一边。 */
type DelRow =
  | {
      kind: "head";
      key: string;
      title: string;
      note: string;
      count: number;
      collapsible: boolean;
      open: boolean;
    }
  | { kind: "item"; key: string; d: Delegate; i: number };

interface FormState {
  /** null = 新建 */
  id: string | null;
  name: string;
  kind: DelegateKind;
  freq: DelegateFreq;
  at: string;
  weekday: number;
  everyMinutes: number;
  sessionId: string;
  kbId: string;
  instruction: string;
  tone: string;
  maxChars: number;
  enabled: boolean;
}

const BLANK_FORM: FormState = {
  id: null,
  name: "",
  kind: "review",
  freq: "daily",
  at: "21:00",
  weekday: 0,
  everyMinutes: 60,
  sessionId: "",
  kbId: "",
  instruction: "",
  tone: "neutral",
  maxChars: 600,
  enabled: true,
};

function toForm(d: Delegate): FormState {
  return {
    id: d.id,
    name: d.name,
    kind: d.kind,
    freq: d.schedule.freq,
    at: d.schedule.at ?? "21:00",
    weekday: d.schedule.weekday ?? 0,
    everyMinutes: d.schedule.every_minutes ?? 60,
    sessionId: d.session_id ?? "",
    kbId: d.kb_id ?? "",
    instruction: d.instruction,
    tone: d.tone,
    maxChars: d.max_chars,
    enabled: d.enabled,
  };
}

export default function DelegatePage() {
  const { toasts, showToast } = useToast();
  const auth = useAuth();
  const authedId = auth.me?.user.id ?? null;
  const [list, setList] = useState<ProbeState<Delegate[]>>({ state: "loading" });
  const [runs, setRuns] = useState<ProbeState<DelegateRun[]>>({ state: "loading" });
  const [sessions, setSessions] = useState<Conversation[]>([]);
  const [kbs, setKbs] = useState<KbInfo[]>([]);
  const [form, setForm] = useState<FormState>(BLANK_FORM);
  const [preview, setPreview] = useState<{ name: string; text: string } | null>(null);
  const [busy, setBusy] = useState<string | null>(null);
  /** 执行历史是否展开成全量（默认只看最近 HIST_PEEK 条） */
  const [histOpen, setHistOpen] = useState(false);
  const formRef = useRef<HTMLDivElement>(null);

  /* 「创建/保存」条：手机端表单约 1000px 高，提交按钮要一直挂在屏幕底部。
     但只在**表单进入视口时**挂 —— 否则用户在看委托列表，屏幕底下永远压着一个
     「创建」按钮，既突兀又挡住列表最后一条。

     ★ 这里不能用 position: sticky 代替。sticky 只对「已经滚过视口底边」的元素生效，
       元素还在视口下方时不会被提前拉上来（10-30 实测：滚到「生成指令」那一屏，
       动作条 bottom 仍停在 736，视口 844）。 */
  const [formInView, setFormInView] = useState(false);
  useEffect(() => {
    const el = formRef.current;
    const root = document.querySelector(".console-scroll");
    if (!el || !root || typeof IntersectionObserver === "undefined") return;
    const io = new IntersectionObserver(
      ([entry]) => setFormInView(entry.isIntersecting),
      // root 必须是真正的滚动容器（.console-scroll），默认 viewport 在这里永远为真
      { root, threshold: 0.05 }
    );
    io.observe(el);
    return () => io.disconnect();
    // list.state：表单要等列表加载完才渲染，首帧 formRef 还是 null
  }, [list.state]);

  /* ---- 首次进委托页的一次性提示 ----
     用户 B 的原话：「创建委托需要先创建一个对话，我找了一分钟左右才知道这个创建对话
     是什么玩意」。首选方案（点按钮直接出表单）已经做了，但**他不知道**，所以点之前
     仍在原地找"先建对话"的入口。这条提示只解决一件事：告他不用先建任何东西。
     每个账号只出现一次，点 × 或建完第一条委托都算看过。 */
  const tipKey = authedId ? `baomi.delegate.tip.v1.${authedId}` : "";
  const [tip, setTip] = useState(false);
  useEffect(() => {
    if (!tipKey) return;
    try {
      if (!localStorage.getItem(tipKey)) setTip(true);
    } catch {
      /* 隐私模式：读不到就当没看过，提示多出现几次不算问题 */
    }
  }, [tipKey]);
  const dismissTip = useCallback(() => {
    setTip(false);
    try {
      if (tipKey) localStorage.setItem(tipKey, "1");
    } catch {
      /* ignore */
    }
  }, [tipKey]);

  const loadList = useCallback(() => {
    api.delegate
      .list()
      .then((d) => setList(toProbe(d)))
      .catch((e) => setList(errProbe(e)));
    // 执行历史读全量表（/api/schedule/runs），不是逐条去问每个委托
    api.schedule
      .runs()
      .then((d) => setRuns(toProbe(d)))
      .catch(() => setRuns({ state: "absent" }));
  }, []);

  useEffect(() => {
    // 未登录不发请求：这一页自己的 useAuth 实例挂载时还没确认完身份
    // （外壳的登录门只保证「登录后才会挂载本页」，不解决这一份实例的时序），
    // 此时发出去必然是 401。登录成功会经 AUTHORIZED_EVENT 同步进 auth.me
    // （见 useAuth / api.ts），依赖变化后自动补加载。
    if (!authedId) return;
    loadList();
    api
      .listSessions()
      .then((r) => setSessions(r.sessions))
      .catch(() => {
        /* 拉不到会话就退化成「默认会话」，不影响列表展示 */
      });
    api
      .listKbs()
      .then((r) => setKbs(r.kbs))
      .catch(() => {
        /* 同上 */
      });
  }, [authedId, loadList]);

  /**
   * 接住从模板广场带过来的预填（`/delegate?new=1` + sessionStorage）。
   *
   * 模板广场的「设为每日委托」会把指令写进 sessionStorage 再跳过来 ——
   * 那条 `baomi:delegate-preset` 读完立刻删掉，否则下次用户自己点「新建委托」
   * 还会莫名其妙冒出一段模板文案。
   *
   * ⚠️ 两个刻意之处，改动前先看这里：
   *  · setState 推在 `setTimeout(..., 0)` 里 —— 本项目的 react-hooks/set-state-in-effect
   *    不允许在 effect 体内直接 setState。
   *  · **故意不返回 cleanup**。如果写成 `return () => clearTimeout(t)`，那么只要
   *    effect 的依赖（showToast）变了、effect 重跑，cleanup 就会把这个定时器取消掉，
   *    而 sessionStorage 已经在同步阶段删过了 —— 结果是预填永远不生效。
   *    防重入改由 presetGuard 这个 ref 承担（它一旦置位，后续重跑一律早退）。
   */
  const presetGuard = useRef(false);
  useEffect(() => {
    if (presetGuard.current) return;
    if (typeof window === "undefined") return;
    if (new URLSearchParams(window.location.search).get("new") !== "1") return;

    let raw: string | null = null;
    try {
      raw = sessionStorage.getItem("baomi:delegate-preset");
      if (raw) sessionStorage.removeItem("baomi:delegate-preset");
    } catch {
      return; // 隐私模式禁了 sessionStorage：没有预填可用，静默放过
    }
    if (!raw) return;

    let preset: { from?: string; instruction?: string } | null = null;
    try {
      preset = JSON.parse(raw) as { from?: string; instruction?: string };
    } catch {
      return; // 存进去的不是合法 JSON，当没这回事
    }
    if (!preset?.instruction) return;

    presetGuard.current = true;
    const from = preset.from ?? "模板";
    const instruction = preset.instruction;
    window.setTimeout(() => {
      setForm((f) => ({ ...f, name: from.slice(0, 32), instruction }));
      // URL 上的 ?new=1 用完就清：刷新页面不该再预填一次
      window.history.replaceState(null, "", "/delegate");
      // 表单在右侧常驻但位置靠下，不滚过去用户会以为"点了没反应"
      formRef.current?.scrollIntoView({ behavior: "smooth", block: "start" });
      showToast("info", `已按「${from}」填好指令，确认频率后保存`);
    }, 0);
  }, [showToast]);

  // 预览浮层的 Esc 关闭 + 焦点归还。
  //
  // 全项目 7 处弹层都支持 Esc，唯独这个浮层之前没有 —— 键盘用户按 Esc 毫无反应，
  // 只能 Tab 到关闭按钮。写法与 FilePreviewModal 保持一致：
  //  · 监听挂在 document 上且用 capture，确保浮层内任何焦点位置都能收到；
  //  · cleanup 里把焦点还给触发元素，否则关掉浮层后键盘用户会被甩回页面开头。
  //    ⚠️ 这里是在 effect 里读 `document.activeElement` 的写法，成立的前提是
  //    **本浮层没有任何 autoFocus/自动聚焦**。若将来给浮层加了自动聚焦，
  //    必须改成在用户点击「预览」的那一刻捕获 opener —— 否则读到的会是浮层内的元素，
  //    焦点归还就静默失效了（FilePreviewModal 正因此改用惰性 useState 抓 opener）。
  useEffect(() => {
    if (!preview) return;
    const opener = document.activeElement;
    const onKey = (e: KeyboardEvent) => {
      if (e.key !== "Escape") return;
      e.stopPropagation();
      setPreview(null);
    };
    document.addEventListener("keydown", onKey, true);
    return () => {
      document.removeEventListener("keydown", onKey, true);
      if (opener instanceof HTMLElement) opener.focus?.();
    };
  }, [preview]);

  // 后端没上线时用演示数据顶住版面，但界面上会挂「演示数据」标记
  const isDemo = list.state === "absent";
  const items = list.state === "ready" ? list.data : isDemo ? DEMO_DELEGATES : [];
  const runItems = runs.state === "ready" ? runs.data : isDemo ? DEMO_RUNS : [];

  const activeCount = useMemo(() => items.filter((d) => d.enabled).length, [items]);

  /* 执行历史的一行汇总。原来这块只列时间，用户得自己数有多少次失败；
     改成「近 N 次 · 成功 X · 失败 Y」之后，那 50 行可以放心折叠。 */
  const runOk = runItems.filter((r) => r.status === "succeeded").length;
  const runBad = runItems.filter((r) => r.status === "failed").length;

  /* 执行历史只对管理员整块展开：普通用户要的不是「第 37 次执行的 tokens_out」，
     而是「它上次到底跑没跑成」—— 那一句已经并进每条委托的行内（见 .dele-last）。
     整张历史表留给排障，普通用户看了只会多一个疑问。 */
  const isAdmin = Boolean(auth.me?.is_admin);

  /* 每条委托的「上次执行」：run 记录的 subject_id 就是 delegation_id
     （见 service/daily.py 的 _dispatch_one）。取最近一条，
     这样行内不用再单独请求一次，也不会和 runItems 的口径不一致。 */
  const lastRunOf = useMemo(() => {
    const m = new Map<string, DelegateRun>();
    const at = (r: DelegateRun) => r.finished_at ?? r.started_at ?? r.planned_at ?? 0;
    for (const r of runItems) {
      const sid = r.subject_id;
      if (!sid) continue;
      const cur = m.get(sid);
      if (!cur || at(r) > at(cur)) m.set(sid, r);
    }
    return (id: string) => m.get(id) ?? null;
  }, [runItems]);

  /** 正在编辑的那条（删除 / 预览要拿到完整对象，表单里只有字段） */
  const editingItem = useMemo(
    () => (form.id ? items.find((d) => d.id === form.id) ?? null : null),
    [items, form.id]
  );

  /* ---- 列表分组 ----
     原来是一张平铺的单子，用户看不出「哪些还在跑、哪些已经停了」——
     而这一页的全部价值就是"它会自己来找我"，看不出在不在跑，等于看不出有没有用。
     ★ 后端没有 status 字段，只有 enabled / next_run_at：委托是**周期性**的，
       不存在"已完成"这种终态。所以只分「正在跑」「停下来了」两组，
       不硬造一个永远为空的"已完成"组 —— 空的分类比没有分类更让人困惑。 */
  const [openPaused, setOpenPaused] = useState(false);
  const rows = useMemo(() => {
    const running = items.filter((d) => d.enabled);
    const paused = items.filter((d) => !d.enabled);
    // 组内排序：正在跑的按下次触发升序（最快来的在前，还没算出下次的垫底）；
    // 停下来的按创建时间倒序（刚停的最可能被找回来）
    const FAR = Number.MAX_SAFE_INTEGER;
    running.sort((a, b) => (a.next_run_at ?? FAR) - (b.next_run_at ?? FAR));
    paused.sort((a, b) => (b.created_at ?? 0) - (a.created_at ?? 0));
    const out: DelRow[] = [];
    if (running.length) {
      out.push({
        kind: "head",
        key: "g-run",
        title: "正在跑",
        note: "按下次触发时间，最快来的在前",
        count: running.length,
        collapsible: false,
        open: true,
      });
      running.forEach((d, i) => out.push({ kind: "item", key: d.id, d, i }));
    }
    if (paused.length) {
      out.push({
        kind: "head",
        key: "g-pause",
        title: "停下来了",
        note: openPaused ? "不会再触发，直到你重新打开开关" : "不会再触发 · 点这里展开",
        count: paused.length,
        collapsible: true,
        open: openPaused,
      });
      if (openPaused) paused.forEach((d, i) => out.push({ kind: "item", key: d.id, d, i }));
    }
    return out;
  }, [items, openPaused]);

  /** 演示模式下所有写操作都要明说没生效，不能假装成功 */
  const demoGuard = useCallback(
    (what: string): boolean => {
      if (!isDemo) return false;
      showToast("info", `接口待上线，${what}未提交。合入 feat/ai-module 分支后自动生效。`);
      return true;
    },
    [isDemo, showToast],
  );

  const patch = (p: Partial<FormState>) => setForm((f) => ({ ...f, ...p }));

  const submit = async () => {
    if (!form.name.trim() || form.name.trim().length < 3) {
      showToast("error", "名称至少 3 个字");
      return;
    }
    if (!form.instruction.trim()) {
      showToast("error", "生成指令不能为空 —— 它是知穗每次要照做的事");
      return;
    }
    if (form.id === null && form.enabled && activeCount >= MAX_ACTIVE) {
      showToast("error", `启用中的委托最多 ${MAX_ACTIVE} 条，请先暂停一条`);
      return;
    }
    if (demoGuard(form.id ? "保存" : "创建")) return;

    const body = {
      kind: form.kind,
      schedule: {
        freq: form.freq,
        at: form.freq === "interval" ? null : form.at,
        weekday: form.freq === "weekly" ? form.weekday : null,
        every_minutes: form.freq === "interval" ? form.everyMinutes : null,
        tz: TZ,
      },
      session_id: form.sessionId || null,
      kb_id: form.kbId || null,
      instruction: form.instruction.trim(),
      tone: form.tone,
      max_chars: form.maxChars,
      enabled: form.enabled,
    };

    setBusy("submit");
    try {
      if (form.id) {
        // name 建后不可改，所以更新时不带它进去
        await api.delegate.update(form.id, body);
        showToast("success", "已保存");
      } else {
        await api.delegate.create({ ...body, name: form.name.trim() });
        showToast("success", `已创建「${form.name.trim()}」`);
      }
      setForm(BLANK_FORM);
      // 能成功建成一条，说明他早就过了"要不要先建对话"这道坎，这条提示不用再出现
      dismissTip();
      loadList();
    } catch (e) {
      showToast("error", e instanceof Error ? e.message : "提交失败，请稍后重试");
    } finally {
      setBusy(null);
    }
  };

  const toggleEnabled = async (d: Delegate, next: boolean) => {
    if (next && activeCount >= MAX_ACTIVE) {
      showToast("error", `启用中的委托最多 ${MAX_ACTIVE} 条，请先暂停一条`);
      return;
    }
    if (demoGuard(next ? "启用" : "暂停")) return;
    setBusy(`toggle-${d.id}`);
    try {
      await api.delegate.update(d.id, { enabled: next });
      loadList();
    } catch (e) {
      showToast("error", e instanceof Error ? e.message : "操作失败");
    } finally {
      setBusy(null);
    }
  };

  const doRemove = async (d: Delegate) => {
    if (!window.confirm(`删除「${d.name}」？委托本身会被移除，但它的执行记录会保留，便于回看。`)) return;
    if (demoGuard("删除")) return;
    setBusy(`del-${d.id}`);
    try {
      await api.delegate.remove(d.id);
      showToast("info", "已删除");
      if (form.id === d.id) setForm(BLANK_FORM);
      loadList();
    } catch (e) {
      showToast("error", e instanceof Error ? e.message : "删除失败");
    } finally {
      setBusy(null);
    }
  };

  /** dryRun=true 只生成不投递；false 才是真的发到会话里 */
  const doRun = async (d: Delegate, dryRun: boolean) => {
    if (demoGuard(dryRun ? "预览" : "立即执行")) {
      setPreview({
        name: d.name,
        text:
          "（演示内容）今天的复盘：\n\n你今天把二叉树三种遍历的递归实现自己写出来了，中序遍历为什么能得到有序序列也说清楚了。\n\n最该补的是线索二叉树 —— 你知道它省了栈，但说不出哪种场景下比递归更划算。\n\n明天的一条动作：找一道需要频繁找前驱/后继的题，分别用递归和线索化各做一遍，对比代码量和栈深度。",
      });
      return;
    }
    setBusy(`run-${d.id}`);
    try {
      const r = await api.delegate.run(d.id, dryRun);
      if (dryRun) {
        setPreview({ name: d.name, text: r?.content ?? "（后端未返回内容）" });
      } else {
        showToast("success", "已执行，结果存好了，回首页就能看到");
        loadList();
      }
    } catch (e) {
      showToast("error", e instanceof Error ? e.message : "执行失败");
    } finally {
      setBusy(null);
    }
  };

  const editing = form.id !== null;

  return (
    <PageShell
      title="每日委托"
      // 页头说明整句退场（2026-11-17）：「让知穗在固定时间替你复盘…」原来占两行。
      // 说的是这一页能干什么，而列表里每条委托自己就写着"每天 21:00 · 下次 …"。
      // 宽度：单列页面，980 是「两列表单 + 一行委托卡」都还读得下去的上限。
      width={980}
      actions={
        <>
          <span className="ctag">
            启用中 <b style={{ fontWeight: 700, marginLeft: 3 }}>{activeCount}</b> / {MAX_ACTIVE}
          </span>
          <button type="button" className="btn btn-primary" onClick={() => setForm(BLANK_FORM)}>
            <CornIcon name="plus" />
            新建委托
          </button>
        </>
      }
    >
      {tip && (
        <div className="del-tip" role="status">
          <div className="del-tip-body">
            <b>直接说你要做什么就行。</b>
            比如「每天早上 7 点提醒我背 20 个单词」。点「新建委托」直接出表单，不用先建别的。
          </div>
          <button
            type="button"
            className="del-tip-x"
            onClick={dismissTip}
            aria-label="知道了，不再提示"
          >
            ×
          </button>
        </div>
      )}
      {list.state === "loading" && (
        <div className="card card-pad">
          <SkeletonLines widths={["70%", "50%", "84%"]} />
        </div>
      )}

      {list.state === "error" && (
        <Callout icon="warn">
          委托列表读不到：{list.message}
          <button type="button" className="btn btn-ghost btn-sm" style={{ marginLeft: 10 }} onClick={loadList}>
            重试
          </button>
        </Callout>
      )}

      {(list.state === "ready" || isDemo) && (
        <>
          {isDemo && (
            <div style={{ marginBottom: 14 }}>
              <NotReady
                what="每日委托接口（/api/delegate，7 个端点）"
                note="下面的列表与历史是设计稿的演示数据，按钮点了不会真的提交。"
              />
            </div>
          )}

          {/* 2026-11-17：两栏收成一条纵列 —— 我的委托 → 新建委托 → 执行历史。
              手机上原来执行历史（最多 50 行）夹在中间，把新建表单推到了三四屏之外。 */}
          <div className="del-page">
            <div>
              <p className="sec-label">
                我的委托{isDemo && <span className="ctag warn" style={{ marginLeft: 6 }}>演示数据</span>}
              </p>

              <div className="card card-pad">
                {items.length === 0 ? (
                  <div style={{ padding: "10px 2px" }}>
                    <div style={{ display: "flex", alignItems: "center", gap: 10 }}>
                      <CornIcon name="clock" className="h-7 w-7" />
                      <div>
                        <div className="card-title">让知穗每天主动找你一次</div>
                        <div className="meta" style={{ marginTop: 3 }}>
                          比如每晚 21:00 把当天学过的东西复盘成一段话，存到你的复习记录里。
                        </div>
                      </div>
                    </div>
                    <button
                      type="button"
                      className="btn btn-ghost btn-sm"
                      style={{ marginTop: 12 }}
                      onClick={() =>
                        setForm({
                          ...BLANK_FORM,
                          name: "每日学习复盘",
                          kind: "review",
                          instruction:
                            "根据我今天的学习产出给一段复盘：先说清我今天掌握了什么，再指出一个最该补的漏洞，最后给明天一条具体到动作的建议。",
                        })
                      }
                    >
                      <CornIcon name="plus" />
                      用这个示例填一份
                    </button>
                  </div>
                ) : (
                  rows.map((r) => {
                    if (r.kind === "head") {
                      return (
                        <button
                          key={r.key}
                          type="button"
                          className={`del-group-head${r.collapsible ? " is-collapsible" : ""}`}
                          aria-expanded={r.open}
                          onClick={() => {
                            if (r.collapsible) setOpenPaused((v) => !v);
                          }}
                        >
                          <span className="del-group-title">
                            {r.title}
                            <em>{r.count}</em>
                          </span>
                          <span className="del-group-note">{r.note}</span>
                          {r.collapsible && (
                            <span className="del-group-toggle">{r.open ? "收起" : "展开"}</span>
                          )}
                        </button>
                      );
                    }
                    const d = r.d;
                    const last = lastRunOf(d.id);
                    const [lastCls, lastLabel] = last
                      ? RUN_TAG[last.status] ?? ["warn", last.status]
                      : ["", ""];
                    // 「下次什么时候」这件事有四种状态，必须分开说：
                    //   · 关掉了 → 已暂停
                    //   · worker 自动停用 → 说清原因（last_error）
                    //   · 刚建好、还没派发过 → next_run_at 是 NULL，但**不是暂停**
                    //   · 正常 → 下次时间 + 还有多久
                    // ★ 第 3 种以前被错归到「已暂停」，开关明明是开的，用户以为坏了。
                    //   next_run_at=NULL 在后端语义里是「待首次派发」（save_delegation 注释）。
                    return (
                    <div key={d.id}>
                      {r.i > 0 && <div className="divide" />}
                      <div className="dele">
                        <div className="dele-main">
                          <div className="dele-name">
                            {d.name}
                            <span className="ctag">{KIND_LABEL[d.kind] ?? d.kind}</span>
                          </div>
                          <div className="dele-when">
                            <span className="sched">
                              <CornIcon name={d.schedule.freq === "weekly" ? "calendar" : "clock"} />
                              {scheduleText(d)}
                            </span>
                            {/* 中间那个「·」用 CSS 伪元素画在状态文字前面，不写成独立元素：
                                独立 span 在 flex-wrap 下会被留在行尾，变成「每天 21:00 ·」
                                然后下一行才开始「下次 …」（10-30 手机截图就是这个）。 */}
                            {!d.enabled ? (
                              <span className="dele-off">已暂停</span>
                            ) : d.last_error ? (
                              <span className="dele-bad">{d.last_error}</span>
                            ) : d.next_run_at ? (
                              <span className="next">
                                下次 {fmtWhen(d.next_run_at)}
                                {/* 相对时间（还有 5 小时）只有 24h 内才直观，
                                    窄屏放不下就让位，绝对时刻已经说清了 */}
                                <span className="dele-remain">（{fmtRemaining(d.next_run_at)}）</span>
                              </span>
                            ) : (
                              <span className="dele-wait">已启用，等第一次执行</span>
                            )}
                          </div>
                          {/* 上次执行：普通用户只需要这一行，不需要整张历史表 */}
                          {last && (
                            <div className="dele-last">
                              上次 {last.planned_at ? fmtWhen(last.planned_at) : "—"}
                              <span className={`ctag ${lastCls}`} style={{ marginLeft: 6 }}>
                                {lastLabel}
                              </span>
                              {last.trigger === "manual" && (
                                <span className="dele-dim">（你手动跑的）</span>
                              )}
                              {last.error && <span className="dele-bad"> · {last.error}</span>}
                            </div>
                          )}
                          {(d.session_title || d.kb_name) && (
                            <div className="dele-sub">
                              {d.session_title && (
                                <span>
                                  结果放回 <b>{d.session_title}</b>
                                </span>
                              )}
                              {d.kb_name && (
                                <span>
                                  只参考 <b>{d.kb_name}</b>
                                </span>
                              )}
                            </div>
                          )}
                        </div>
                        <div className="dele-side">
                          <Switch
                            checked={d.enabled}
                            disabled={busy === `toggle-${d.id}`}
                            label={`${d.name} 启用`}
                            onChange={(v) => void toggleEnabled(d, v)}
                          />
                        </div>
                        <div className="dele-acts">
                          <button
                            type="button"
                            className="btn btn-ghost btn-sm"
                            disabled={busy === `run-${d.id}`}
                            onClick={() => void doRun(d, false)}
                          >
                            <CornIcon name="bolt" />
                            立即执行
                          </button>
                          <button
                            type="button"
                            className="icon-btn"
                            title="编辑"
                            aria-label={`编辑 ${d.name}`}
                            onClick={() => setForm(toForm(d))}
                          >
                            <CornIcon name="pencil" />
                          </button>
                        </div>
                      </div>
                    </div>
                    );
                  })
                )}
              </div>

              {/* ============ 新建 / 编辑表单 ============ */}
              <div ref={formRef}>
                {/* 说明：这一块 2026-11-17 从右栏挪到「我的委托」下面。
                    手机上两栏本来就是一栏，执行历史（最多 50 行）夹在中间，
                    新建表单被推到三四屏之外 —— 用户以为这页只能看不能建。 */}
                <p className="sec-label" style={{ marginTop: 22 }}>
                  {editing ? "编辑委托" : "新建委托"}
                </p>
                {/* del-form-grid：宽屏两列、窄屏一列。字段横跨 900px 时
                    「名称（3–32 字）」这种输入框会长得像一段正文。 */}
                <div className="card card-pad del-form-grid">
                  <Field className="wide" label="名称（3–32 字，建后不可改）">
                    <input
                      className="input"
                      value={form.name}
                      maxLength={32}
                      disabled={editing}
                      placeholder="例如：每日学习复盘"
                      onChange={(e) => patch({ name: e.target.value })}
                    />
                  </Field>

                  <div className="field">
                    <span className="f">类型</span>
                    <Seg
                      ariaLabel="委托类型"
                      options={KIND_OPTIONS}
                      value={form.kind}
                      onChange={(v) => patch({ kind: v })}
                    />
                  </div>

                  <div className="field">
                    <span className="f">频率</span>
                    <Seg
                      ariaLabel="触发频率"
                      options={FREQ_OPTIONS}
                      value={form.freq}
                      onChange={(v) => patch({ freq: v })}
                      stretch
                    />
                  </div>

                  {form.freq === "interval" ? (
                    <Field label="每多少分钟一次" hint="最小 60 分钟（1 小时），最多 1440">
                      <input
                        className="input"
                        type="number"
                        min={60}
                        max={1440}
                        value={form.everyMinutes}
                        onChange={(e) => patch({ everyMinutes: Number(e.target.value) || 60 })}
                      />
                    </Field>
                  ) : (
                    <div className="row field wide">
                      <div style={{ flex: 1 }}>
                        <Field label="触发时间">
                          <input
                            className="input"
                            type="time"
                            value={form.at}
                            onChange={(e) => patch({ at: e.target.value })}
                          />
                        </Field>
                      </div>
                      <div style={{ flex: 1 }}>
                        <Field label="时区" hint="当前只支持一个时区">
                          <input className="input" value={TZ} disabled />
                        </Field>
                      </div>
                    </div>
                  )}

                  {form.freq === "weekly" && (
                    <div className="field">
                      <span className="f">星期几</span>
                      <Seg
                        ariaLabel="星期几"
                        options={WEEKDAYS.map((w, i) => ({ value: String(i), label: w }))}
                        value={String(form.weekday)}
                        onChange={(v) => patch({ weekday: Number(v) })}
                        stretch
                      />
                    </div>
                  )}

                  <Field label="结果放在哪" hint="不选就放默认位置">
                    <select
                      className="input"
                      value={form.sessionId}
                      onChange={(e) => patch({ sessionId: e.target.value })}
                    >
                      <option value="">默认位置（不用选）</option>
                      {sessions.map((s) => (
                        <option key={s.id} value={s.id}>
                          {s.title}
                        </option>
                      ))}
                    </select>
                  </Field>

                  <Field label="绑定资料库（可选）" hint="绑了之后生成时只参考这个库">
                    <select
                      className="input"
                      value={form.kbId}
                      onChange={(e) => patch({ kbId: e.target.value })}
                    >
                      <option value="">不绑定</option>
                      {kbs.map((k) => (
                        <option key={k.kb_id} value={k.kb_id}>
                          {k.name}
                        </option>
                      ))}
                    </select>
                  </Field>

                  <Field className="wide" label="生成指令" hint="知穗每次要照做的事，写得越具体结果越稳">
                    <textarea
                      className="input"
                      value={form.instruction}
                      maxLength={1000}
                      placeholder="例如：根据我今天的学习产出给一段复盘，先说掌握了什么，再指出一个最该补的漏洞。"
                      onChange={(e) => patch({ instruction: e.target.value })}
                    />
                  </Field>

                  <div className="row field wide">
                    <div style={{ flex: 1 }}>
                      <Field label="语气">
                        <select
                          className="input"
                          value={form.tone}
                          onChange={(e) => patch({ tone: e.target.value })}
                        >
                          <option value="neutral">中性</option>
                          <option value="warm">温和</option>
                          <option value="strict">严格</option>
                        </select>
                      </Field>
                    </div>
                    <div style={{ flex: 1 }}>
                      <Field label="长度上限（字）">
                        <input
                          className="input"
                          type="number"
                          min={200}
                          max={2000}
                          step={50}
                          value={form.maxChars}
                          onChange={(e) => patch({ maxChars: Number(e.target.value) || 600 })}
                        />
                      </Field>
                    </div>
                  </div>

                  <div
                    className="field wide"
                    style={{ display: "flex", alignItems: "center", justifyContent: "space-between" }}
                  >
                    <span style={{ fontSize: "var(--fs-sm)", color: "var(--text-2)" }}>
                      {editing ? "启用这条委托" : "创建后立即启用"}
                    </span>
                    <Switch
                      checked={form.enabled}
                      label="启用"
                      onChange={(v) => patch({ enabled: v })}
                    />
                  </div>

                  {/* 预览与删除：从行内挪到编辑面板里。
                      行内只留「开关 + 立即执行」两件事（任务型布局），
                      预览是「配置时验证」的动作、删除是不可逆的破坏性动作，
                      两者都属于「打开这一条再动手」，摆在列表上每行重复一遍只是噪音。 */}
                  {editing && editingItem && (
                    <div className="form-tools wide">
                      <button
                        type="button"
                        className="btn btn-ghost btn-sm"
                        disabled={busy === `run-${editingItem.id}`}
                        onClick={() => void doRun(editingItem, true)}
                      >
                        先预览一次
                      </button>
                      <button
                        type="button"
                        className="btn btn-danger btn-sm"
                        disabled={busy === `del-${editingItem.id}`}
                        onClick={() => void doRemove(editingItem)}
                      >
                        <CornIcon name="trash" />
                        删除这条
                      </button>
                    </div>
                  )}
                  {editing && (
                    <p className="hint wide" style={{ marginTop: 8 }}>
                      「先预览一次」只生成内容给你看一遍，不会发到会话里，也不会改下次触发时间。
                    </p>
                  )}

                  {/* 手机上表单长约 1000px，提交按钮原来在最后一个字段之后 ——
                      滑到中间时找不到它。is-fixed 只在窄屏固定到底部（桌面右栏常驻，
                      一条横跨全屏的底栏反而更难用），且只在表单可见时挂上。 */}
                  <div className={`row form-actions wide${formInView ? " is-fixed" : ""}`}>
                    <button
                      type="button"
                      className="btn btn-primary"
                      style={{ flex: 1 }}
                      disabled={busy === "submit"}
                      onClick={() => void submit()}
                    >
                      <CornIcon name="check" />
                      {editing ? "保存" : "创建"}
                    </button>
                    <button type="button" className="btn btn-ghost" onClick={() => setForm(BLANK_FORM)}>
                      {editing ? "取消编辑" : "清空"}
                    </button>
                  </div>
                  <p className="hint wide">
                    启用中的委托上限 {MAX_ACTIVE} 条；名字撞上已有的会自动提醒你换一个。
                  </p>
                </div>
              </div>

              {/* ---- 执行历史：只给管理员 ----
                  普通用户要的是「它上次跑成没有」，那一句已经并进每条委托的行内；
                  整张表的价值在排障（哪次定时、耗时多少、烧了多少 token）。

                  ★ 2026-11-17 换了显示方式：默认只露最近 3 条 + 一行汇总，
                    其余收进「查看全部」。原来最多 50 条平铺，一条 40px，
                    光这一块就 2000px —— 手机上要划六屏才到底，
                    而每天真正要看的是「最近跑成没有」这 3 条。 */}
              {isAdmin && (
                <>
                  <p className="sec-label del-hist-head" style={{ marginTop: 22 }}>
                    执行历史
                    <span className="del-hist-sum">
                      近 {runItems.length} 次 · 成功 {runOk}
                      {runBad > 0 ? ` · 失败 ${runBad}` : ""}
                    </span>
                  </p>
                  <div className="card card-pad">
                    {runItems.length === 0 ? (
                      <p className="hint" style={{ marginTop: 0 }}>
                        还没有执行记录。第一次触发之后，这里会显示每次的结果和耗时。
                      </p>
                    ) : (
                      <>
                        <div className="del-hist-list">
                          {(histOpen ? runItems : runItems.slice(0, HIST_PEEK)).map((r) => {
                            const [cls, label] = RUN_TAG[r.status] ?? ["warn", r.status];
                            const dur = fmtDuration(r.started_at, r.finished_at);
                            return (
                              <div className="run run--tight" key={r.run_id}>
                                <span className="when">
                                  {r.planned_at ? fmtWhen(r.planned_at) : "—"}
                                </span>
                                <span>
                                  <span className={`ctag ${cls}`}>{label}</span>{" "}
                                  <span className="meta">
                                    {r.trigger === "manual" ? "手动" : "定时"}
                                    {dur ? ` · ${dur}` : ""}
                                    {r.error ? ` · ${r.error}` : ""}
                                  </span>
                                </span>
                                <span className="meta">
                                  {r.tokens_out ? `${fmtNum(r.tokens_out)} tok` : ""}
                                </span>
                              </div>
                            );
                          })}
                        </div>
                        {runItems.length > HIST_PEEK && (
                          <button
                            type="button"
                            className="del-hist-more"
                            aria-expanded={histOpen}
                            onClick={() => setHistOpen((v) => !v)}
                          >
                            {histOpen ? "收起" : `查看全部 ${runItems.length} 条`}
                          </button>
                        )}
                      </>
                    )}
                  </div>
                </>
              )}
            </div>

          </div>
        </>
      )}

      {/* ---- 预览浮层：dry_run 的产物，只给人看 ---- */}
      {preview && (
        <div
          role="dialog"
          aria-modal="true"
          aria-label="预览生成内容"
          style={{
            position: "fixed",
            inset: 0,
            background: "rgba(0,0,0,.42)",
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
            padding: 20,
            zIndex: 60,
          }}
          onClick={() => setPreview(null)}
        >
          <div
            className="card card-pad"
            style={{ maxWidth: 560, width: "100%", maxHeight: "80vh", overflowY: "auto" }}
            onClick={(e) => e.stopPropagation()}
          >
            <div className="card-head">
              <span className="card-title">预览 · {preview.name}</span>
              <button
                type="button"
                className="icon-btn"
                aria-label="关闭预览"
                onClick={() => setPreview(null)}
              >
                <CornIcon name="close" />
              </button>
            </div>
            <p className="hint" style={{ marginTop: 4 }}>
              这是 <code>dry_run</code> 的结果：没有真的执行，也没有改下次触发时间。
            </p>
            <div
              style={{
                marginTop: 12,
                whiteSpace: "pre-wrap",
                fontSize: "var(--fs-lg)",
                lineHeight: "var(--lh-loose)",
              }}
            >
              {preview.text}
            </div>
          </div>
        </div>
      )}

      <ToastHost toasts={toasts} />
    </PageShell>
  );
}

"use client";

// 混合架构管理面：工作流定义 + 切换规则
//
// 契约来源：docs/前端对接接口文档_混合架构_2026-10-14.md（林宏亮 v1）
// 后端已合入 main（提交 231a9c7），本地 8010/8000 实跑 17/17 契约通过。
// 页面仍保留**三态降级**（加载中 / 端点 404 演示数据+「接口待上线」 / 真实数据）：
// 服务器尚未部署新版本时，前端不会白屏。
//
// ★ 这个页面最容易踩的坑（文档 §六.6 也特意点了）：
// **编辑工作流定义必须用「非受控文本域 + 失焦提交」**。
// 用受控写法（value 绑定 state + onChange）的话，用户输入到一半的
// `{"nodes": [` 一定是**非法 JSON** ⇒ JSON.parse 抛错 ⇒ onChange 里 setState 失败
// ⇒ 字符打不进去 ⇒ 用户连一个括号都删不掉。
// 所以：编辑期间不解析，只在**失焦/点保存**时解析并标红。

import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import PageShell from "@/components/console/PageShell";
import { Seg, ToastHost } from "@/components/console/ui";
import { SkeletonLines } from "@/components/Skeleton";
import CornIcon from "@/components/CornIcon";
import { api } from "@/lib/api";
import { useAuth } from "@/lib/hooks/useAuth";
import { useToast } from "@/lib/hooks/useToast";
import type { HybridRunRow, RuleRow, WorkflowDef, WorkflowRow } from "@/lib/types";
import { KNOWN_SIGNALS } from "@/lib/types";

type Tab = "wf" | "rule" | "run";

/** 演示数据：后端未上线时顶住版面，界面上挂「接口待上线」标记 */
const DEMO_WORKFLOWS: WorkflowRow[] = [
  {
    id: "builtin_plan_execute",
    owner_id: "-",
    name: "规划-执行（内置）",
    description: "先用模型拆步骤，再交给智能体按规划完成",
    version: 1,
    created_at: 0,
    updated_at: 0,
    builtin: true,
    definition: {
      id: "builtin_plan_execute",
      name: "规划-执行（内置）",
      version: 1,
      entry: "plan",
      nodes: [
        { id: "plan", type: "llm", name: "任务规划", config: { prompt: "…{question}", output_key: "plan" } },
        { id: "execute", type: "agent", name: "自主执行", config: { goal: "…{shared.plan}", output_key: "agent_result" } },
      ],
      edges: [{ source: "plan", target: "execute" }],
    },
  },
];

const DEMO_RULES: RuleRow[] = [
  { id: "1", owner_id: "-", name: "wf_requires_agent", signal: "requires_agent", condition: null, action: "to_agent", reason: "工作流节点声明需要自主执行，移交智能体", priority: 10, enabled: true, cooldown_seconds: 0, builtin: true },
  { id: "2", owner_id: "-", name: "wf_node_failure", signal: "node_failed", condition: null, action: "to_agent", reason: "工作流节点失败且无补偿分支，智能体降级接管", priority: 20, enabled: true, cooldown_seconds: 30, builtin: true },
  { id: "3", owner_id: "-", name: "agent_budget_exhausted", signal: "budget_exhausted", condition: null, action: "to_workflow", reason: "智能体预算耗尽，收编回工作流", priority: 20, enabled: true, cooldown_seconds: 30, builtin: true },
  { id: "4", owner_id: "-", name: "agent_goal_satisfied", signal: "goal_satisfied", condition: null, action: "to_workflow", reason: "智能体子目标完成，工作流从断点继续", priority: 30, enabled: true, cooldown_seconds: 0, builtin: true },
];

const DEMO_RUNS: HybridRunRow[] = [
  { run_id: "run-demo-001", task_id: "t1", workflow_id: "builtin_plan_execute", status: "completed", created_at: 0, updated_at: 0 },
];

const ACTION_LABEL: Record<string, string> = {
  to_agent: "交给智能体",
  to_workflow: "收回工作流",
  terminate: "终止",
};

const STATUS_LABEL: Record<string, string> = {
  running: "进行中",
  completed: "已完成",
  failed: "失败",
  timeout: "超时",
  stopped: "已停止",
};

export default function FlowPage() {
  const { toasts, showToast } = useToast();
  const auth = useAuth();
  const authedId = auth.me?.user.id ?? null;
  const [tab, setTab] = useState<Tab>("wf");
  // 三态而不是两态：undefined = 加载中（还没结果）；null = 加载失败（降级演示
  // 数据）；数组 = 真实数据。若让 null 兼作「加载中」，每次打开页面都会先闪
  // 一下「接口待上线」的假降级（请求回来前的空窗期），慢网络下能停好几秒。
  const [wfs, setWfs] = useState<WorkflowRow[] | null | undefined>(undefined);
  const [rules, setRules] = useState<RuleRow[] | null | undefined>(undefined);
  const [runs, setRuns] = useState<HybridRunRow[] | null | undefined>(undefined);
  const [editing, setEditing] = useState<WorkflowRow | null>(null);
  const [err, setErr] = useState("");
  const [busy, setBusy] = useState(false);
  const editorRef = useRef<HTMLTextAreaElement>(null);

  const load = useCallback(() => {
    api.hybrid.workflows().then((d) => setWfs(d)).catch(() => setWfs(null));
    api.hybrid.rules().then((d) => setRules(d)).catch(() => setRules(null));
    api.hybrid.runs(20).then((d) => setRuns(d)).catch(() => setRuns(null));
  }, []);
  useEffect(() => {
    // 未登录不发请求：这一页自己的 useAuth 实例挂载时还没确认完身份，
    // 此时发出去必然 401，页面就会停在「接口待上线」那种失败结果上（10-14 实测）。
    // 登录成功会经 AUTHORIZED_EVENT 同步进本实例的 auth.me，依赖变化后自动补加载。
    if (!authedId) return;
    load();
  }, [authedId, load]);

  const isLoading = wfs === undefined || rules === undefined || runs === undefined;
  const isDemo = wfs === null;
  const wfItems = wfs ?? DEMO_WORKFLOWS;
  const ruleItems = rules ?? DEMO_RULES;
  const runItems = runs ?? DEMO_RUNS;

  // 演示模式下所有写操作都要明说没生效，不能假装成功（与四屏同一约定）
  const demoGuard = useCallback(
    (what: string) => {
      if (isDemo) {
        showToast("info", `接口待上线，${what}暂未生效`);
        return true;
      }
      return false;
    },
    [isDemo, showToast]
  );

  const onDeleteWf = useCallback(
    async (row: WorkflowRow) => {
      if (row.builtin) {
        showToast("info", "内置工作流只读，不能删除");
        return;
      }
      if (demoGuard("删除")) return;
      setBusy(true);
      try {
        await api.hybrid.deleteWorkflow(row.id);
        showToast("success", "已删除");
        load();
      } catch {
        showToast("error", "删除失败");
      } finally {
        setBusy(false);
      }
    },
    [demoGuard, isDemo, load, showToast]
  );

  const onSaveWf = useCallback(async () => {
    if (!editing) return;
    if (demoGuard("保存")) {
      setEditing(null);
      return;
    }
    // 从 DOM 现读编辑器内容：编辑器是**非受控**的（输入期间不能解析，否则
    // 用户连括号都删不掉），state 里的 definition 还是打开时的旧值 —— 不现读
    // 的话用户改的 JSON 会被静默丢弃：界面弹「已保存」，落库的还是旧内容
    // （10-14 浏览器联调实测：改完保存再打开，定义原样不动）。
    let def: WorkflowDef;
    try {
      def = JSON.parse(editorRef.current?.value ?? "") as WorkflowDef;
    } catch (ex) {
      setErr(String(ex));
      return;
    }
    setBusy(true);
    try {
      await api.hybrid.updateWorkflow(editing.id, {
        name: editing.name,
        description: editing.description,
        definition: def,
      });
      showToast("success", "已保存");
      setEditing(null);
      load();
    } catch {
      showToast("error", "保存失败：可能定义非法（边指向不存在的节点等）");
    } finally {
      setBusy(false);
    }
  }, [demoGuard, editing, load, showToast]);

  return (
    <PageShell
      eyebrow="管理 · 内部"
      title="工作流与切换规则"
      actions={
        <div className="flow-tabs">
          <Seg
            ariaLabel="管理视图切换"
            options={[
              { value: "wf", label: isLoading ? "工作流" : `工作流 ${wfItems.length}` },
              { value: "rule", label: isLoading ? "切换规则" : `切换规则 ${ruleItems.length}` },
              { value: "run", label: isLoading ? "执行记录" : `执行记录 ${runItems.length}` },
            ]}
            value={tab}
            onChange={(v) => setTab(v as Tab)}
          />
        </div>
      }
    >
      {isLoading && <SkeletonLines widths={["70%", "96%", "80%"]} label="正在加载工作流" />}

      {isDemo && (
        <p className="flow-demo" role="status">
          <CornIcon name="info" /> 接口待上线，以下是演示数据。
        </p>
      )}

      {!isLoading && tab === "wf" && (
        <ul className="flow-list">
          {wfItems.map((w) => (
            <li key={w.id} className="flow-card">
              <div className="flow-card-main">
                <div className="flow-card-title">
                  {w.name}
                  {w.builtin && <em className="flow-tag">内置</em>}
                  <em className="flow-ver">v{w.version}</em>
                </div>
                {w.description && <p className="flow-desc">{w.description}</p>}
                <details className="flow-detail">
                  <summary>定义（{w.definition?.nodes?.length ?? 0} 个节点）</summary>
                  <pre className="flow-pre">{JSON.stringify(w.definition, null, 2)}</pre>
                </details>
              </div>
              <div className="flow-card-side">
                <button
                  type="button"
                  className="btn-ghost"
                  disabled={busy || w.builtin}
                  title={w.builtin ? "内置工作流只读" : "编辑定义"}
                  onClick={() => {
                    setErr("");
                    setEditing(w);
                  }}
                >
                  编辑
                </button>
                <button
                  type="button"
                  className="btn-ghost danger"
                  disabled={busy || w.builtin}
                  onClick={() => onDeleteWf(w)}
                >
                  删除
                </button>
              </div>
            </li>
          ))}
        </ul>
      )}

      {!isLoading && tab === "rule" && (
        <>
          <p className="flow-hint">
            引擎只会上报 4 个 signal（下面这四个）。自定义 signal 能存下但不会有事件触发。
          </p>
          <ul className="flow-list">
            {ruleItems.map((r) => (
              <li key={r.name} className="flow-card">
                <div className="flow-card-main">
                  <div className="flow-card-title">
                    {r.name}
                    {r.builtin && <em className="flow-tag">内置</em>}
                    <em className="flow-ver">优先级 {r.priority}</em>
                  </div>
                  <p className="flow-desc">
                    <code>{r.signal}</code> → <strong>{ACTION_LABEL[r.action] ?? r.action}</strong>
                    {r.reason ? ` · ${r.reason}` : ""}
                    {r.cooldown_seconds ? ` · 冷却 ${r.cooldown_seconds}s` : " · 无防抖"}
                  </p>
                </div>
                {!r.builtin && (
                  <div className="flow-card-side">
                    <button
                      type="button"
                      className="btn-ghost danger"
                      disabled={busy}
                      onClick={async () => {
                        if (demoGuard("删除规则")) return;
                        setBusy(true);
                        try {
                          await api.hybrid.deleteRule(r.name);
                          showToast("success", "已删除用户覆盖，系统默认重新生效");
                          load();
                        } catch {
                          showToast("error", "删除失败");
                        } finally {
                          setBusy(false);
                        }
                      }}
                    >
                      删覆盖
                    </button>
                  </div>
                )}
              </li>
            ))}
          </ul>
          <p className="flow-hint">
            已知 signal：{KNOWN_SIGNALS.map((s) => (
              <code key={s} className="flow-signal">{s}</code>
            ))}
          </p>
        </>
      )}

      {!isLoading && tab === "run" && (
        <ul className="flow-list">
          {runItems.map((r) => (
            <li key={r.run_id} className="flow-card">
              <div className="flow-card-main">
                <div className="flow-card-title">
                  {r.run_id}
                  <em className={`flow-status is-${r.status}`}>{STATUS_LABEL[r.status] ?? r.status}</em>
                </div>
                <p className="flow-desc">
                  工作流 {r.workflow_id || "（裸跑智能体）"} · 任务 {r.task_id}
                </p>
              </div>
              <div className="flow-card-side">
                <button
                  type="button"
                  className="btn-ghost"
                  disabled={busy}
                  onClick={async () => {
                    if (demoGuard("查看日志")) return;
                    setBusy(true);
                    try {
                      const logs = await api.hybrid.logs(r.run_id);
                      showToast("info", logs && logs.length ? `共 ${logs.length} 条日志` : "没有日志");
                    } catch {
                      showToast("error", "取日志失败");
                    } finally {
                      setBusy(false);
                    }
                  }}
                >
                  看日志
                </button>
              </div>
            </li>
          ))}
        </ul>
      )}

      {editing && (
        <div className="flow-modal" role="dialog" aria-modal="true" aria-label="编辑工作流定义">
          <div className="flow-modal-box">
            <h3>编辑「{editing.name}」</h3>
            <p className="flow-hint">
              定义是 JSON。<strong>失焦或点保存时才校验</strong> ——
              输入过程中允许非法 JSON，否则你连括号都删不掉。
            </p>
            <textarea
              ref={editorRef}
              className="flow-editor"
              defaultValue={JSON.stringify(editing.definition, null, 2)}
              onBlur={(e) => {
                try {
                  JSON.parse(e.target.value);
                  setErr("");
                } catch (ex) {
                  setErr(String(ex));
                }
              }}
            />
            {err && <p className="flow-err">JSON 不合法：{err}</p>}
            <div className="flow-modal-actions">
              <button type="button" className="btn-ghost" onClick={() => setEditing(null)}>
                取消
              </button>
              <button type="button" className="btn-primary" disabled={busy || !!err} onClick={onSaveWf}>
                保存
              </button>
            </div>
          </div>
        </div>
      )}

      <ToastHost toasts={toasts} />
    </PageShell>
  );
}

"use client";

// 知识库（/knowledge）—— 独立页面。
//
// 为什么单独一页：这个入口原先指向 `/?kb=1`，和「对话」是同一个路由，
// 只是把首页右栏那个抽屉拉开（用户原话："点击对话和点击知识库都是一样的跳转"）。
// 资料管理本身是件独立的事：建库、传文件、看文件名和段数、删错的文件、重新整理。
// 塞在对话页 280px 的侧栏里，这些信息一件都放不下。
//
// 版式参考 ima 的知识库：左侧库列表，右侧当前库的文件卡片网格。
// 数据直接走后端已有的 /api/kb 一组接口（与首页资料库面板同一套），
// 不新增后端端点 —— 这里的"新"只是**摆放方式**新，能力与首页面板一致。
import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import Link from "next/link";
import PageShell from "@/components/console/PageShell";
import CornIcon from "@/components/CornIcon";
import SedimentModal from "@/components/chat/SedimentModal";
import { SkeletonLines, ToastHost } from "@/components/console/ui";
import { api } from "@/lib/api";
import { useAuth } from "@/lib/hooks/useAuth";
import { useToast } from "@/lib/hooks/useToast";
import { fmtNum, fmtWhen } from "@/lib/time";
import { CHUNK_PROFILES, nearestProfileId, profileParams, type ChunkProfileId } from "@/lib/chunkProfiles";
import { loadKbChunks, saveKbChunks, type KbChunkMap } from "@/lib/kbChunkPrefs";
import type { AccessMode, Defaults, FavoriteKbInfo, FilePreview, KbFile, KbInfo } from "@/lib/types";

/** 文件类型标：只区分"读得出来的三类 + 其它"，不追求完整 MIME */
function kindOf(name: string): "pdf" | "doc" | "text" | "other" {
  const ext = (name.split(".").pop() ?? "").toLowerCase();
  if (ext === "pdf") return "pdf";
  if (ext === "doc" || ext === "docx") return "doc";
  if (ext === "md" || ext === "markdown" || ext === "txt") return "text";
  return "other";
}

function extOf(name: string): string {
  const ext = (name.split(".").pop() ?? "").toLowerCase();
  return ext && ext !== name.toLowerCase() ? ext.slice(0, 4) : "FILE";
}

const errMsg = (e: unknown, fallback: string) => (e instanceof Error ? e.message : fallback);

export default function KnowledgePage() {
  const auth = useAuth();
  const authedId = auth.me?.user.id ?? null;
  const { toasts, showToast } = useToast();

  const [kbs, setKbs] = useState<KbInfo[]>([]);
  /**
   * 我收藏的公开库。
   *
   * 用户原话："二级导航的知识库那块也要有收藏知识库"。
   * 这些库不是自己的 —— 不能在这里传文件、删资料，所以点一下跳去
   * 公开详情页 /library/{kb_id}（那边能看清单、能预览），而不是在右侧面板里
   * 假装它是自己的库。混在一起编辑，迟早会有人以为改了别人的东西。
   */
  const [favKbs, setFavKbs] = useState<FavoriteKbInfo[]>([]);
  const [loading, setLoading] = useState(true);
  const [activeId, setActiveId] = useState<string | null>(null);
  /**
   * 手机上现在是"哪一屏"（2026-11-16 P1：资料库改 push）。
   *
   * 原来两栏在 ≤900 只是竖着堆：上面库列表、下边同一个库的详情，
   * 库名连着出现两次，要滑过整张列表才看得见详情，也分不清"我在列表里还是在库里"。
   * 现在列表点进库 = 整屏切换，左上角「‹ 我的资料库」退回。
   * 桌面端这个 state 不影响布局（两栏并排本来就都在）。
   */
  const [mobilePane, setMobilePane] = useState<"list" | "detail">("list");
  const [defaults, setDefaults] = useState<Defaults | null>(null);
  /** 正在进行的操作：upload / rebuild / import / create / delete */
  const [busy, setBusy] = useState<string | null>(null);
  const [creating, setCreating] = useState(false);
  const [newName, setNewName] = useState("");
  /** 删库的二次确认（库 id）；删文件用下面那个 */
  const [confirmDelKb, setConfirmDelKb] = useState<string | null>(null);
  const [confirmDelFile, setConfirmDelFile] = useState<string | null>(null);
  /** 「分享到广场」的二次确认（库 id）。分享是把库交出去给人看，点一下就生效太草率：
   *  简历、成绩单这类库，用户未必意识到「全站登录用户都能检索」是什么概念。
   *  收回不设确认 —— 收回是止损，多一步只会拖慢。
   *  改简介复用同一个确认条（区别只在按钮文案与 toast），所以下面还有一份草稿。 */
  const [confirmPub, setConfirmPub] = useState<string | null>(null);
  /** 确认条里那句简介的草稿。打开确认条时用 public_desc 预填，收进 state 才能编辑 */
  const [pubDesc, setPubDesc] = useState("");
  /** 公开期间别人能做什么：仅观看 / 可下载（2026-11-13） */
  const [pubAccess, setPubAccess] = useState<AccessMode>("preview");
  const [dragging, setDragging] = useState(false);
  /** 每个库上次用的切法（kb_id → 参数）。后端不记这件事，存在本地，
      和首页资料库面板共用同一份 baomi.kbChunk.v1 —— 两个入口改的是同一件事，
      不能各存一套。 */
  const [chunkMap, setChunkMap] = useState<KbChunkMap>({});
  const [urlOpen, setUrlOpen] = useState(false);
  const [url, setUrl] = useState("");
  // 从对话里收几条：这一页进来时不知道是哪段对话，弹层第一步会让用户挑
  const [sedimentOpen, setSedimentOpen] = useState(false);
  /** 正在预览的资料正文；previewBusy 是"正在读哪一条"，两者独立：
      卡片上要能立刻显示"在读"，而弹层只在拿到正文后才出现（避免空壳闪一下） */
  const [preview, setPreview] = useState<FilePreview | null>(null);
  const [previewBusy, setPreviewBusy] = useState<string | null>(null);
  const fileInput = useRef<HTMLInputElement | null>(null);
  const detailRef = useRef<HTMLDivElement | null>(null);
  const previewCloseRef = useRef<HTMLButtonElement | null>(null);

  useEffect(() => {
    const t = window.setTimeout(() => setChunkMap(loadKbChunks()), 0);
    return () => window.clearTimeout(t);
  }, []);

  const active = useMemo(() => kbs.find((k) => k.kb_id === activeId) ?? null, [kbs, activeId]);

  // 库被删掉后详情是空的：手机上要退回列表，否则会停在一张空卡片上（什么都点不了）
  useEffect(() => {
    if (!active) setMobilePane("list");
  }, [active]);

  /** 当前库的切法：这张表记过就用它，没记过才回落到全局默认值 */
  const fallbackParams = useMemo(
    () => ({ size: defaults?.chunk_size ?? 500, overlap: defaults?.chunk_overlap ?? 50 }),
    [defaults]
  );
  const activeParams = (active && chunkMap[active.kb_id]) || fallbackParams;
  const size = activeParams.size;
  const overlap = activeParams.overlap;
  const modeId = nearestProfileId(size, overlap);

  const refresh = useCallback(
    async (select?: string) => {
      try {
        const { kbs: list } = await api.listKbs();
        setKbs(list);
        // 选中项：优先用刚建的，其次保留原选中，最后退回第一个
        setActiveId((prev) => {
          if (select && list.some((k) => k.kb_id === select)) return select;
          if (prev && list.some((k) => k.kb_id === prev)) return prev;
          return list[0]?.kb_id ?? null;
        });
      } catch (e) {
        showToast("error", errMsg(e, "资料库列表读不到，请稍后重试"));
      } finally {
        setLoading(false);
      }
    },
    [showToast],
  );

  // 未登录不发请求：登录前必然是 401，且登录成功后不会自动重来
  useEffect(() => {
    if (!authedId) return;
    void refresh();
    // 收藏库：辅助列表，读不到就当空（不该因为广场接口抽风把整页拖垮）
    api
      .listFavoriteKbs()
      .then((r) => setFavKbs(r.kbs))
      .catch(() => {});
    // 切块默认值：后端是唯一权威，前端不硬编码 500/50
    api
      .defaults()
      .then(setDefaults)
      .catch(() => {
        /* 读不到就用兜底值，不阻断上传 */
      });
  }, [authedId, refresh]);

  /**
   * 窄屏从"把详情滚进视野"改成"推进去"（2026-11-16 P1：资料库改 push）。
   *
   * 原来两栏竖堆时，点了库只能平滑滚到下面那张卡 —— 用户要滑过一整张列表，
   * 返回还得自己往上滚，而且库名在两处同时出现，看着像重复渲染。
   * 现在点库 = 换一屏，返回用详情左上角那个「‹ 我的资料库」。
   * 桌面两栏并排，本来就在眼前，不做任何切换。
   */
  const pickKb = (id: string) => {
    setActiveId(id);
    setConfirmDelKb(null);
    setConfirmDelFile(null);
    if (window.matchMedia("(max-width: 900px)").matches) setMobilePane("detail");
  };

  const create = async () => {
    const name = newName.trim();
    if (!name || busy) return;
    setBusy("create");
    try {
      const r = await api.createKb(name);
      setNewName("");
      setCreating(false);
      await refresh(r.kb_id);
      showToast("success", `建好了「${r.name}」，往里放点资料吧`);
    } catch (e) {
      showToast("error", errMsg(e, "建库失败，请稍后重试"));
    } finally {
      setBusy(null);
    }
  };

  const upload = async (files: FileList | File[] | null) => {
    if (!active || !files) return;
    const arr = Array.from(files);
    if (arr.length === 0) return;
    setBusy("upload");
    try {
      const r = await api.uploadFiles(active.kb_id, arr, size, overlap);
      await refresh(active.kb_id);
      showToast("success", `收进 ${fmtNum(r.chunks)} 段`);
    } catch (e) {
      showToast("error", errMsg(e, "上传失败，请稍后重试"));
    } finally {
      setBusy(null);
      if (fileInput.current) fileInput.current.value = "";
    }
  };

  const removeFile = async (name: string) => {
    if (!active) return;
    setBusy("delete");
    try {
      const r = await api.deleteKbFile(active.kb_id, name);
      setConfirmDelFile(null);
      await refresh(active.kb_id);
      showToast("info", r.removed > 0 ? `已移除「${name}」` : `已移除「${name}」`);
    } catch (e) {
      showToast("error", errMsg(e, "删除失败，请稍后重试"));
    } finally {
      setBusy(null);
    }
  };

  const removeKb = async (id: string) => {
    setBusy("delete");
    try {
      await api.deleteKb(id);
      setConfirmDelKb(null);
      // 删掉的是当前选中的库时，refresh 会自动退回第一个
      await refresh();
      showToast("info", "资料库已删除");
    } catch (e) {
      showToast("error", errMsg(e, "删除失败，请稍后重试"));
    } finally {
      setBusy(null);
    }
  };

  const rebuild = async () => {
    if (!active) return;
    setBusy("rebuild");
    try {
      const r = await api.rebuildKb(active.kb_id, size, overlap);
      await refresh(active.kb_id);
      showToast("success", `重新整理好了，共 ${fmtNum(r.chunks)} 段`);
    } catch (e) {
      showToast("error", errMsg(e, "重新整理失败，请稍后重试"));
    } finally {
      setBusy(null);
    }
  };

  /** 换切法只记下来，不自动重切：重切要重算向量，几秒到几十秒，
   *  用户只是想先选好再动手时不该被卡住。文件卡片下面那行提示会说清这件事。 */
  const pickMode = (id: ChunkProfileId) => {
    if (!active) return;
    const p = profileParams(id);
    const next: KbChunkMap = { ...chunkMap, [active.kb_id]: p };
    setChunkMap(next);
    saveKbChunks(next);
  };

  /** 分享到广场 / 从广场收回 / 改简介。
   *
   *  2026-11-13 广场化：原来这里叫「设为公开」，现在这个动作的结果是
   *  「出现在公开知识库广场上等别人挑」。同一件事，但说「分享」用户才知道
   *  它的结果长什么样。
   *  放开的仍然只有「他人只读检索」：文件清单、上传、删除只有库主能动。
   *  收回立即生效，别人对话里挂着的这个库下一轮就检索不到了。 */
  const shareToPlaza = async () => {
    if (!active || busy) return;
    setBusy("public");
    try {
      await api.setKbPublic(active.kb_id, true, pubDesc.trim(), pubAccess);
      await refresh(active.kb_id);
      // 成功才收起确认条；失败时留着，用户可以直接再点一次
      setConfirmPub(null);
      showToast(
        "success",
        `「${active.name}」已分享到广场，其他用户可以在对话里检索它${
          pubAccess === "download" ? "并下载原件" : "、在线预览（不提供下载）"
        }`,
      );
    } catch (e) {
      showToast("error", errMsg(e, "分享失败，请稍后重试"));
    } finally {
      setBusy(null);
    }
  };

  const withdrawFromPlaza = async () => {
    if (!active || busy) return;
    setBusy("public");
    try {
      await api.setKbPublic(active.kb_id, false);
      await refresh(active.kb_id);
      showToast("success", "已从广场收回：其他用户不再能检索这个库");
    } catch (e) {
      showToast("error", errMsg(e, "收回失败，请稍后重试"));
    } finally {
      setBusy(null);
    }
  };

  const importUrl = async () => {
    if (!active || !url.trim()) return;
    setBusy("import");
    try {
      const r = await api.importUrl(active.kb_id, url.trim(), size, overlap);
      setUrl("");
      setUrlOpen(false);
      await refresh(active.kb_id);
      showToast("success", `已收进「${r.title}」，${fmtNum(r.chunks)} 段`);
    } catch (e) {
      showToast("error", errMsg(e, "这个网址抓不下来，换个页面或稍后再试"));
    } finally {
      setBusy(null);
    }
  };

  /** 看正文：以前这一页只能看到文件名和段数，对话沉淀进来的东西更是连条目都没有。
   *  后端 /file-content 对两种来源都兜得住 —— 有留档读原始文件，没有就从向量片段拼回来。 */
  const openPreview = async (name: string) => {
    if (!active || previewBusy) return;
    setPreviewBusy(name);
    try {
      const data = await api.getFileContent(active.kb_id, name);
      setPreview(data);
    } catch (e) {
      showToast("error", errMsg(e, "这份资料的正文读不出来，可能还没入库完整"));
    } finally {
      setPreviewBusy(null);
    }
  };

  // 预览弹层：Esc 关闭 + 打开时把焦点交给关闭键（键盘用户不至于被关在里面）
  useEffect(() => {
    if (!preview) return;
    const onKey = (e: KeyboardEvent) => {
      if (e.key === "Escape") setPreview(null);
    };
    window.addEventListener("keydown", onKey);
    previewCloseRef.current?.focus();
    return () => window.removeEventListener("keydown", onKey);
  }, [preview]);

  const files: KbFile[] = active?.files ?? [];
  const exts = defaults?.supported_extensions ?? [".pdf", ".md", ".txt"];

  return (
    <PageShell
      title="我的资料库"
      // 页头说明退场（2026-11-17）：「课件、笔记、论文都能放进来。」
      // 与「上传文件」按钮说的是同一件事；detail 那句（选中一个库、回答先从这里找依据）
      // 也一并删掉 —— 它讲的是选库之后发生什么，而选库这个动作本身就在左栏。
      actions={
        <>
          {/* 页头只放"对当前这个库的主操作"。原来这里还有一个「+ 新建」，
              和左栏标题栏那个「新建」是同一件事 —— 同屏两个同级按钮，用户
              第一反应是"这俩有什么区别"，所以库管理统一收进左栏。 */}
          <button
            type="button"
            className="btn btn-primary"
            disabled={!active || busy !== null}
            onClick={() => fileInput.current?.click()}
          >
            <CornIcon name="upload" />
            {busy === "upload" ? "收集中…" : "上传文件"}
          </button>
        </>
      }
    >
      <input
        ref={fileInput}
        type="file"
        multiple
        accept={exts.join(",")}
        style={{ display: "none" }}
        onChange={(e) => void upload(e.target.files)}
      />

      {loading ? (
        <div className="card card-pad">
          <SkeletonLines widths={["40%", "100%", "86%"]} />
        </div>
      ) : kbs.length === 0 ? (
        <div className="card kbp-empty">
          <CornIcon name="book" className="h-10 w-10" />
          <b>还没有资料库</b>
          <p>
            建一个库，把这一门课的课件、笔记、往年题放进去 ——
            之后问的时候，回答会先从这里找依据，再补自己的话。
          </p>
          {/* 空态下的新建**必须在这里就地长出输入框**：左侧栏这时根本没渲染
              （kbs.length === 0 走的是这个分支），把 creating 只挂在左栏上，
              用户点「建第一个资料库」会看到毫无反应。 */}
          {creating ? (
            <div className="kbp-newrow" style={{ width: "100%", maxWidth: 380 }}>
              <input
                autoFocus
                value={newName}
                placeholder="给它起个名字，比如「数据结构」"
                onChange={(e) => setNewName(e.target.value)}
                onKeyDown={(e) => {
                  if (e.key === "Enter") void create();
                  if (e.key === "Escape") {
                    setCreating(false);
                    setNewName("");
                  }
                }}
              />
              <button
                type="button"
                className="btn btn-primary btn-sm"
                disabled={!newName.trim() || busy === "create"}
                onClick={() => void create()}
              >
                建
              </button>
            </div>
          ) : (
            <button type="button" className="btn btn-primary btn-sm" onClick={() => setCreating(true)}>
              建第一个资料库
            </button>
          )}
        </div>
      ) : (
        <div className={mobilePane === "detail" ? "kbp kbp--detail" : "kbp"}>
          {/* ---------- 左：库列表 ---------- */}
          <aside className="card kbp-side">
            <div className="kbp-side-head">
              <span className="t">全部资料库</span>
              <button type="button" className="kbp-new" onClick={() => setCreating((v) => !v)}>
                <CornIcon name="plus" />
                新建
              </button>
            </div>

            {creating && (
              <div className="kbp-newrow">
                <input
                  autoFocus
                  value={newName}
                  placeholder="给它起个名字，比如「数据结构」"
                  onChange={(e) => setNewName(e.target.value)}
                  onKeyDown={(e) => {
                    if (e.key === "Enter") void create();
                    if (e.key === "Escape") {
                      setCreating(false);
                      setNewName("");
                    }
                  }}
                />
                <button
                  type="button"
                  className="btn btn-primary btn-sm"
                  disabled={!newName.trim() || busy === "create"}
                  onClick={() => void create()}
                >
                  建
                </button>
              </div>
            )}

            {kbs.map((k) => (
              <button
                key={k.kb_id}
                type="button"
                className="kbp-item"
                aria-current={k.kb_id === activeId ? "true" : undefined}
                onClick={() => pickKb(k.kb_id)}
              >
                <CornIcon name="book" className="ico" />
                <span className="nm">
                  <b title={k.name}>{k.name}</b>
                  <span>
                    {k.files.length} 份资料 · {fmtNum(k.chunks)} 段
                    {k.public && <em className="kbp-pub">公开</em>}
                  </span>
                </span>
              </button>
            ))}

            {/* 收藏的公开库：不是自己的库，所以只能"去查看"，不能在这里编辑。
                单独一组而不是混进上面的列表 —— 上面的每一行都能传文件、能删，
                混在一起用户会以为收藏的库也能改。 */}
            {favKbs.length > 0 && (
              <div className="kbp-favs">
                <p className="kbp-favs-head">
                  收藏的公开库
                  <span>{favKbs.length}</span>
                </p>
                {favKbs.map((k) => (
                  <Link key={k.kb_id} href={`/library/${encodeURIComponent(k.kb_id)}`} className="kbp-fav">
                    <CornIcon name="star" className="ico" />
                    <span className="nm">
                      <b title={k.name}>{k.name}</b>
                      <span>
                        {/* 来源与作者：官方库由后端拼成「官方课程库」，同学的是「某某 的库」 */}
                        来源{k.source}
                        {k.at > 0 && ` · ${fmtWhen(k.at)}上传`}
                      </span>
                    </span>
                  </Link>
                ))}
                <Link href="/library" className="kbp-fav-more">
                  去广场挑更多
                  <CornIcon name="arrow" className="ico" />
                </Link>
              </div>
            )}
          </aside>

          {/* ---------- 右：当前库 ---------- */}
          <section className="card kbp-main" ref={detailRef}>
            {active ? (
              <>
                {/* 手机上是"推进去"的一屏，不是堆在列表下面的一段：
                    左上角给一个返回，回到全部资料库。桌面端两栏并排，这个按钮不显示。 */}
                <button
                  type="button"
                  className="kbp-back"
                  onClick={() => setMobilePane("list")}
                  aria-label="返回全部资料库"
                >
                  <CornIcon name="back" className="ico" />
                  全部资料库
                </button>
                <div className="kbp-main-head">
                  <div style={{ minWidth: 0 }}>
                    <h3 className="kbp-title">{active.name}</h3>
                    <p className="kbp-sub">
                      {files.length} 份资料 · 切成 {fmtNum(active.chunks)} 段
                    </p>
                  </div>
                  <div className="kbp-acts">
                    <button
                      type="button"
                      className="btn btn-ghost btn-sm"
                      disabled={busy !== null}
                      title={
                        active.public
                          ? "从广场收回：其他用户将不能再检索这个库"
                          : "分享后其他登录用户可以在广场上看到并在对话里检索它（只读）；文件清单与修改仍只有你能做"
                      }
                      onClick={() => {
                        // 分享要先过确认条（分享=把库交出去）；收回是止损，直接执行
                        if (active.public) {
                          void withdrawFromPlaza();
                        } else {
                          setPubDesc(active.public_desc ?? "");
                          setPubAccess(active.public_access ?? "preview");
                          setConfirmPub(active.kb_id);
                        }
                      }}
                    >
                      <CornIcon name="globe" />
                      {busy === "public" ? "处理中…" : active.public ? "从广场收回" : "分享到广场"}
                    </button>
                    {active.public && (
                      <button
                        type="button"
                        className="btn btn-ghost btn-sm"
                        disabled={busy !== null}
                        title="改广场卡片上那句简介，不影响谁能检索"
                        onClick={() => {
                          setPubDesc(active.public_desc ?? "");
                          setPubAccess(active.public_access ?? "preview");
                          setConfirmPub(active.kb_id);
                        }}
                      >
                        <CornIcon name="pencil" />
                        改简介
                      </button>
                    )}
                    <button
                      type="button"
                      className="btn btn-ghost btn-sm"
                      disabled={busy !== null || files.length === 0}
                      title="按当前读法把整个库重新切一遍（要重新算向量，会慢一点）"
                      onClick={() => void rebuild()}
                    >
                      <CornIcon name="refresh" />
                      {busy === "rebuild" ? "整理中…" : "重新整理"}
                    </button>
                    <button
                      type="button"
                      className="btn btn-ghost btn-sm kbp-del"
                      onClick={() => setConfirmDelKb(active.kb_id)}
                    >
                      <CornIcon name="trash" />
                      删除
                    </button>
                  </div>
                </div>

                {confirmPub === active.kb_id && (
                  <div className="kbp-confirm kbp-confirm-info">
                    <span>
                      {active.public
                        ? `改一下「${active.name}」在广场上的简介。改简介不影响谁能检索它。`
                        : `分享「${active.name}」到广场？其他登录用户都能在对话里检索这 ${files.length} 份资料，
                           也能点进去看清单。上传和删除仍然只有你能做，随时可以收回。`}
                    </span>
                    <label className="kbp-pub-desc" htmlFor="kbp-pub-desc">
                      <span>一句话简介（选填）</span>
                      <textarea
                        id="kbp-pub-desc"
                        value={pubDesc}
                        maxLength={200}
                        rows={2}
                        placeholder="例：考研数学一，近十年真题按章节整理，含错题标注"
                        onChange={(e) => setPubDesc(e.target.value)}
                      />
                      <em>{pubDesc.length}/200</em>
                    </label>
                    <div className="kbp-access">
                      <span>别人能做什么</span>
                      <div className="kbp-access-pick" role="radiogroup" aria-label="访问方式">
                        <button
                          type="button"
                          role="radio"
                          aria-checked={pubAccess === "preview"}
                          className={"kbp-access-opt" + (pubAccess === "preview" ? " on" : "")}
                          onClick={() => setPubAccess("preview")}
                        >
                          仅观看<span>能看清单和预览，不能下载</span>
                        </button>
                        <button
                          type="button"
                          role="radio"
                          aria-checked={pubAccess === "download"}
                          className={"kbp-access-opt" + (pubAccess === "download" ? " on" : "")}
                          onClick={() => setPubAccess("download")}
                        >
                          可以下载<span>还能把原件存到本地</span>
                        </button>
                      </div>
                    </div>
                    <button
                      type="button"
                      className="btn btn-primary btn-sm"
                      disabled={busy === "public"}
                      onClick={() => void shareToPlaza()}
                    >
                      {busy === "public" ? "处理中…" : active.public ? "保存设置" : "确认分享"}
                    </button>
                    <button type="button" className="btn btn-ghost btn-sm" onClick={() => setConfirmPub(null)}>
                      {active.public ? "取消" : "先不分享"}
                    </button>
                  </div>
                )}

                {confirmDelKb === active.kb_id && (
                  <div className="kbp-confirm">
                    <span>删掉「{active.name}」连同里面的 {files.length} 份资料？这一步不可撤销。</span>
                    <button
                      type="button"
                      className="btn btn-danger btn-sm"
                      disabled={busy === "delete"}
                      onClick={() => void removeKb(active.kb_id)}
                    >
                      确认删除
                    </button>
                    <button type="button" className="btn btn-ghost btn-sm" onClick={() => setConfirmDelKb(null)}>
                      先留着
                    </button>
                  </div>
                )}

                {/* 上传区：可点可拖。限制写在下面一行，并给出出路 */}
                {/* 这份资料怎么切。原先这个选项只在首页右栏的小面板里有，
                    用户从「知识库」进来就找不到了 —— 而设置页恰好写着"在资料库里给每个库单独选"。
                    三档用的是同一套 lib/chunkProfiles，改的是同一个本地映射。 */}
                <div className="kbp-read">
                  <span className="kbp-read-l">怎么切</span>
                  <div className="kbp-read-seg" role="group" aria-label="这份资料怎么切">
                    {CHUNK_PROFILES.map((p) => (
                      <button
                        key={p.id}
                        type="button"
                        aria-pressed={modeId === p.id}
                        title={`${p.examples} — ${p.benefit}`}
                        onClick={() => pickMode(p.id)}
                      >
                        {p.label}
                      </button>
                    ))}
                  </div>
                  <span className="kbp-read-n">每段约 {size} 字</span>
                  {files.length > 0 && (
                    <span className="kbp-read-tip">换了记得点「重新整理」</span>
                  )}
                </div>

                <label
                  className={`kbp-drop${dragging ? " drag" : ""}`}
                  onDragOver={(e) => {
                    e.preventDefault();
                    setDragging(true);
                  }}
                  onDragLeave={() => setDragging(false)}
                  onDrop={(e) => {
                    e.preventDefault();
                    setDragging(false);
                    void upload(e.dataTransfer.files);
                  }}
                >
                  <CornIcon name="upload" />
                  <span>
                    {busy === "upload" ? "正在收进来…" : "上传文件，或把文件拖到这里"}
                    <small>
                      支持 {exts.join(" / ")}；Word、PPT 和图片里的字读不出来 ——
                      先把它们另存为 PDF 再放进来。
                    </small>
                  </span>
                  <input
                    type="file"
                    multiple
                    accept={exts.join(",")}
                    style={{ display: "none" }}
                    disabled={busy !== null}
                    onChange={(e) => void upload(e.target.files)}
                  />
                </label>

                {/* 网址入库：走的是同一个库的 import-url，不影响本地上传 */}
                <div style={{ marginTop: 10 }}>
                  {urlOpen ? (
                    <div className="kbp-newrow" style={{ padding: 0 }}>
                      <input
                        autoFocus
                        value={url}
                        placeholder="粘贴一个网页地址，比如某篇博客或文档页"
                        onChange={(e) => setUrl(e.target.value)}
                        onKeyDown={(e) => {
                          if (e.key === "Enter") void importUrl();
                          if (e.key === "Escape") setUrlOpen(false);
                        }}
                      />
                      <button
                        type="button"
                        className="btn btn-primary btn-sm"
                        disabled={!url.trim() || busy === "import"}
                        onClick={() => void importUrl()}
                      >
                        {busy === "import" ? "抓取中…" : "收进来"}
                      </button>
                    </div>
                  ) : (
                    <button
                      type="button"
                      className="kbp-url"
                      onClick={() => setUrlOpen(true)}
                    >
                      <CornIcon name="link" />
                      或者从一个网址收进来
                    </button>
                  )}
                  {/* 第二个入料口：从对话里挑几条。跟上面那条并列而不是另起一块，
                      因为用户在这一片的心智就是「往这个库再放点东西」。
                      display:flex 是因为 .kbp-url 本身是 inline-flex，
                      两个 inline 元素会挤在同一行。 */}
                  <button
                    type="button"
                    className="kbp-url"
                    style={{ display: "flex" }}
                    onClick={() => setSedimentOpen(true)}
                  >
                    <CornIcon name="plus" />
                    或者从对话里收几条
                  </button>
                </div>

                {files.length === 0 ? (
                  <p className="kbp-hint">
                    这个库还是空的 —— 放一份课件或笔记进来，里面第一段话就能被问到。
                  </p>
                ) : (
                  <div className="kbp-files">
                    {files.map((f) => {
                      const fromDialogue = f.origin === "dialogue";
                      return (
                        <div
                          className="kbp-file"
                          key={f.name}
                          role="button"
                          tabIndex={0}
                          aria-label={`查看 ${f.name}`}
                          onClick={() => void openPreview(f.name)}
                          onKeyDown={(e) => {
                            if (e.key !== "Enter" && e.key !== " ") return;
                            e.preventDefault();
                            void openPreview(f.name);
                          }}
                        >
                          <span
                            className="kbp-ext"
                            data-kind={fromDialogue ? "dialogue" : kindOf(f.name)}
                          >
                            {fromDialogue ? "对话" : extOf(f.name)}
                          </span>
                          <div className="fn" title={f.name}>
                            {f.name}
                          </div>
                          <div className="fm">
                            {previewBusy === f.name
                              ? "正在读…"
                              : f.chunks != null
                                ? `${fmtNum(f.chunks)} 段`
                                : "已入库"}
                            {f.added_at ? ` · ${fmtWhen(f.added_at)}` : ""}
                            {f.origin === "web" ? " · 来自网页" : ""}
                            {fromDialogue ? " · 来自对话" : ""}
                          </div>
                          {confirmDelFile === f.name ? (
                            <button
                              type="button"
                              className="btn btn-danger btn-sm"
                              style={{ marginTop: 8 }}
                              disabled={busy === "delete"}
                              onClick={(e) => {
                                e.stopPropagation();
                                void removeFile(f.name);
                              }}
                            >
                              确认删掉
                            </button>
                          ) : (
                            <button
                              type="button"
                              className="x"
                              aria-label={`删除 ${f.name}`}
                              title={`删除 ${f.name}`}
                              onClick={(e) => {
                                // 卡片本身是"看正文"，删除不能连带触发它
                                e.stopPropagation();
                                setConfirmDelFile(f.name);
                              }}
                            >
                              <CornIcon name="close" />
                            </button>
                          )}
                        </div>
                      );
                    })}
                  </div>
                )}
              </>
            ) : (
              <div className="kbp-empty">
                <b>左边挑一个库</b>
                <p>选中之后，这里会列出它装了什么、每份资料被切成了几段。</p>
              </div>
            )}
          </section>
        </div>
      )}

      {sedimentOpen && (
        <SedimentModal
          defaultKbId={activeId}
          onClose={() => setSedimentOpen(false)}
          onImported={(kbId) => {
            // 存进了别的库就顺手切过去 —— 用户刚决定把东西放那儿，
            // 结果界面还停在原来的库上，会以为没生效
            void refresh(kbId);
            const name = kbs.find((k) => k.kb_id === kbId)?.name ?? "资料库";
            showToast("success", `已存进「${name}」`);
          }}
        />
      )}

      {preview && (
        <div className="kbp-prev-mask" onClick={() => setPreview(null)}>
          <div
            className="kbp-prev"
            role="dialog"
            aria-modal="true"
            aria-label={`${preview.name} 正文`}
            onClick={(e) => e.stopPropagation()}
          >
            <div className="kbp-prev-head">
              <div>
                <div className="kbp-prev-t">{preview.name}</div>
                <div className="kbp-prev-m">
                  {preview.origin === "chunks" ? "从库里的片段拼回来的正文" : "库内留档的原文"}
                  {preview.truncated ? " · 只显示前 3 万字" : ""}
                </div>
              </div>
              <button
                type="button"
                ref={previewCloseRef}
                className="kbp-prev-x"
                aria-label="关闭预览"
                onClick={() => setPreview(null)}
              >
                <CornIcon name="close" />
              </button>
            </div>
            <div className="kbp-prev-body">{preview.content}</div>
          </div>
        </div>
      )}

      <ToastHost toasts={toasts} />
    </PageShell>
  );
}

"use client";

// 主页面：三栏布局（会话栏 + 对话区 + 知识库面板）与跨域编排
// 2026-09 重构：toast/偏好/会话/知识库各域逻辑拆到 lib/hooks/*，
// 本文件只保留：断点与主题、抽屉管理、聊天流（SSE）、联网建库编排、布局
import { useCallback, useEffect, useRef, useState, useSyncExternalStore } from "react";
import { useRouter } from "next/navigation";
import Sidebar from "@/components/Sidebar";
import ChatArea, { type ChatAttachment } from "@/components/ChatArea";
import KnowledgePanel from "@/components/KnowledgePanel";
import SedimentModal from "@/components/chat/SedimentModal";
import UsagePanel from "@/components/UsagePanel";
import { api } from "@/lib/api";
import { streamChat } from "@/lib/sse";
import { uid } from "@/lib/id";
import { useToast } from "@/lib/hooks/useToast";
import { getSendGeo, getCachedGeo, isGeoEnabled, acquireGeo, reverseGeocodePlace, setGeoEnabled, updateCachedPlace, formatPlace, getManualCity, setManualCity } from "@/lib/geo";
import { usePrefs } from "@/lib/hooks/usePrefs";
