// ---- 断点订阅（matchMedia 作为外部数据源） ----
type Viewport = "wide" | "medium" | "narrow";

function getViewport(): Viewport {
  if (window.matchMedia("(max-width: 899px)").matches) return "narrow";
  if (window.matchMedia("(min-width: 1280px)").matches) return "wide";
  return "medium";
}

function subscribeViewport(onChange: () => void) {
  const narrow = window.matchMedia("(max-width: 899px)");
  const wide = window.matchMedia("(min-width: 1280px)");
  narrow.addEventListener("change", onChange);
  wide.addEventListener("change", onChange);
  return () => {
    narrow.removeEventListener("change", onChange);
    wide.removeEventListener("change", onChange);
  };
}

// ---- 主题：以 documentElement 上的 dark class 为唯一事实来源 ----
const themeListeners = new Set<() => void>();

function readTheme(): boolean {
  return document.documentElement.classList.contains("dark");
}

function writeTheme(next: boolean) {
  document.documentElement.classList.toggle("dark", next);
  try {
    localStorage.setItem("theme", next ? "dark" : "light");
  } catch {
    /* 隐私模式下写入失败可忽略 */
  }
  themeListeners.forEach((cb) => cb());
}

function subscribeTheme(cb: () => void) {
  themeListeners.add(cb);
  return () => {
    themeListeners.delete(cb);
  };
}

export default function Home() {
  // ---- 各域 hooks ----
  const router = useRouter();
  const { toasts, showToast } = useToast();
  const auth = useAuth();
  const prefs = usePrefs();
  const {
    // mode 只剩「兼容字段」一个用途：照旧发给后端（后端在两个开关都在时忽略它），
    // 以及老偏好迁移的输入。2026-10-31 批 B 起界面上已没有改它的入口。
    mode, topK, setTopK, chunkSize, setChunkSize,
    chunkOverlap, setChunkOverlap, kbPanelPref, setKbPanelPref, savedRef,
    fontScale, setFontScale,
    useKb, setUseKb, useWeb, setUseWeb,
  } = prefs;
  // 两枚能力开关的当前值（2026-10-31 批 B 起常驻，不再是 ?caps=1 的预览）。
  // 由页面层持有是必须的：它要进请求体（use_kb / use_web），
  // 住在 ChatArea 内部的 state 里就发不出去。
  const capValue = { kb: useKb, web: useWeb };
  const onCapChange = useCallback(
    (next: { kb: boolean; web: boolean }) => {
      setUseKb(next.kb);
      setUseWeb(next.web);
    },
    [setUseKb, setUseWeb]
  );
  const sessions_ = useSessions(showToast);
  const {
    sessions, setSessions, activeSid, setActiveSid, messages, setMessages,
    loading: sessionsLoading, loadError: bootError,
    refreshSessions, createSession, selectSession, renameSession,
    deleteSession, deleteTurn, reloadSessions,
  } = sessions_;
  const {
    kbs, publicKbs, favKbs, toggleFavorite, kbNameMap, loading: kbsLoading,
    refreshKbs, uploadFiles, deleteKbFile, rebuildKb, searchPreview, deleteKb,
    rememberChunk, chunkParamsOf,
  } = useKnowledge(showToast, chunkSize, chunkOverlap);

  // ---------- 混合架构（mode=hybrid）----------
  //
  // hybrid 是「每轮一个实例」的归并器：消息发出去时 reset，流式过程中被三个事件喂，
  // done 时收尾。刻意不做成全局 state —— 轨迹属于**某一条消息**，
  // 放全局就会出现「A 轮的节点状态串到 B 轮」。
  const hybrid = useHybridTrace();
  // 轨迹是 hook 内部 state，但它要落到消息上（才能随消息持久化 / 刷新后重建），
  // 所以订阅它变化，把 items 同步进当前那条助手消息。
  const hybridItems = hybrid.trace.items;
  // 本轮助手消息 id：轨迹同步要靠它定位「往哪条消息上写」
  const asstIdRef = useRef<string | null>(null);
  // 本轮用户消息 id（前端临时 id）：done 帧带回 user_message_id 时按它回填 dbId。
  // 不回填的话，用户消息永远没有 dbId —— 消息下方的「存进资料库」和「删除」
  // 都要 dbId 才渲染，表现为"刚发完看不见，刷新一下才有"。
  const userMsgIdRef = useRef<string | null>(null);

  // 轨迹 → 消息。hybrid hook 内部持有 items，这里把它落到消息上，
  // 目的是让它随消息一起被持久化（刷新后还能拿到 hybridRunId 去 /logs 重建）。
  //
  // ⚠️ 用 ref 定位而不是在流式回调里顺手写：那样每个事件都要多一次 setMessages，
  // 会和 token 的累加打架（同一条消息被两个分支各自 map）。
  // 独立 effect 只在 items 真的变了时才动，语义单一。
  useEffect(() => {
    const target = asstIdRef.current;
    if (!target || hybridItems.length === 0) return;
    setMessages((prev) =>
      prev.map((m) => (m.id === target ? { ...m, hybridTrace: hybridItems } : m))
    );
  }, [hybridItems, setMessages]);

  // 登录成功后要重新拉一次：门后面的首屏请求是被 401 挡掉的，
  // 两个 hook 的 init effect 已经跑过了，不补这一次就是空列表。
  const authedId = auth.me?.user.id ?? null;
  useEffect(() => {
    if (!authedId) return;
    void reloadSessions();
    void refreshKbs();
    // 只在"换人/刚登录"时补拉，不跟着这两个函数的新引用反复跑
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, [authedId]);

  const [sending, setSending] = useState(false);
  // 地理定位开关：开启后发送消息自动附带坐标，天气/本地问答免手输城市
  const [geoEnabled, setGeoEnabledState] = useState(isGeoEnabled());
  // 当前定位地名（角标展示用）；从缓存里读出，避免刷新后角标丢失。两级：「茂名 · 茂南区」
  const [geoCity, setGeoCity] = useState<string | null>(() => formatPlace(getCachedGeo()) || null);
  // 定位请求进行中：授权弹窗 + IP 兜底最长 18s，期间按钮转圈，否则看着像没反应
  const [geoPending, setGeoPending] = useState(false);
  // 「手填城市」小输入框是否展开。定位拿不到时直接展开它 —— 不弹报错，给出路
  const [cityEdit, setCityEdit] = useState(false);
  // 场景预设（scenario state + localStorage 随会话保存）已随「场景选择撤出
  // 主界面」整体删除（10-14 晚）：场景化入口统一走模板广场（完整启动包），
  // 工作台不再给对话贴场景标签；后端 /api/chat 的 scenario 字段保留兼容。

  // 联网建库后把建议问题预填进输入框（不自动发送），让用户确认/补充
  const [prefill, setPrefill] = useState<{ text: string; ts: number } | null>(null);
  const abortRef = useRef<AbortController | null>(null);
  /** 当前回答的播放器（把 token 按阅读速度往外放，见 lib/typewriter.ts） */
  const playerRef = useRef<Typewriter | null>(null);

  // 模板广场套用后跳回：?sid 自动选中新建会话，?q 预填引导问题
  // 放在 setPrefill 声明之后；依赖 sessions 列表先回来，列表没回来时这个
  // sid 还不在里面，过早 select 会选空。
  // 2026-10-31 批 B：`?mode=` 已不再读取 —— 四档模式条下架后前端没有"模式"
  // 这个概念，模板页也不再拼这个参数（改了只会带一个没人认的 query）。
  const applyRef = useRef<{ sid: string; q: string | null } | null>(null);
  useEffect(() => {
    const sp = new URLSearchParams(window.location.search);
    const sid = sp.get("sid");
    if (sid) applyRef.current = { sid, q: sp.get("q") };
    // 只跑一次：读 query 是幂等的，无需进 deps
    // eslint-disable-next-line react-hooks/exhaustive-deps
  }, []);
  useEffect(() => {
    const a = applyRef.current;
    if (!a) return;
    if (sessions.length === 0) return; // 列表还没回来
    if (!sessions.some((s) => s.id === a.sid)) return; // 这个会话还没进列表
    if (a.q) setPrefill({ text: a.q, ts: Date.now() });
    if (activeSid !== a.sid) void selectSession(a.sid);
    void refreshKbs();
    applyRef.current = null;
    // 清掉 query，避免刷新又跳一次
    window.history.replaceState({}, "", "/");
  }, [sessions, activeSid, selectSession, refreshKbs, setPrefill]);
  // 抽屉容器：打开时把焦点送进去，关闭后还给触发按钮
  const sidebarRef = useRef<HTMLElement | null>(null);
  const kbRef = useRef<HTMLElement | null>(null);

  // 响应式三档：≥1280 三栏 / 1024–1279 右栏抽屉 / <900 左栏也抽屉
  // 用 useSyncExternalStore 订阅 matchMedia，避免 effect 里 setState 造成的二次渲染
  const viewport = useSyncExternalStore(subscribeViewport, getViewport, () => "wide" as const);
  const [sidebarPref, setSidebarPref] = useState(false);
  // 用量与反馈看板（P2）：侧栏账号块点开
  const [usageOpen, setUsageOpen] = useState(false);
  /**
   * 「存进资料库」弹层。
   *
   * `focus` 是从哪条消息点进来的（消息 dbId）；右栏「对话里的内容」进来时为 null。
   * 弹层放在页面层而不是面板里：两个入口要开的是同一个东西、共用同一份勾选状态。
   */
  const [sediment, setSediment] = useState<{
    focus: number | null;
    text: string | null;
    /** 这条消息是谁说的：用户的短句原样存，助手的回答分节存 */
    role: "user" | "assistant";
  } | null>(null);
  const kbPanelOpen = kbPanelPref ?? viewport === "wide";
  const sidebarOpen = sidebarPref && viewport === "narrow";

  const setKbPanelOpen = useCallback((v: boolean) => setKbPanelPref(v), [setKbPanelPref]);
  const setSidebarOpen = useCallback((v: boolean) => setSidebarPref(v), []);

  // 深色模式：直接以 <html class="dark"> 为准（layout 内联脚本已写入），避免首帧闪白
  const dark = useSyncExternalStore(subscribeTheme, readTheme, () => false);
  const toggleDark = useCallback(() => writeTheme(!readTheme()), []);

  // 字号档位：与 layout 内联脚本同源（html[data-fs]），变化时同步到文档根
  useEffect(() => {
    document.documentElement.dataset.fs = fontScale;
  }, [fontScale]);

  // 四屏导航里点「知识库」会带 ?kb=1 落到本页。
  // 桌面视口资料库本来就常驻，窄屏则是抽屉 —— 不补这一下，窄屏用户点进来什么都看不到。
  // 只在挂载时读一次并立刻清掉 query，避免用户手动关掉抽屉后又被刷新拉回来。
  useEffect(() => {
    if (new URLSearchParams(window.location.search).get("kb") !== "1") return;
    setKbPanelOpen(true);
    window.history.replaceState(null, "", window.location.pathname);
  }, [setKbPanelOpen]);

  // 初始化 defaults：本地存过的参数优先，没存过才用后端默认值
  // （sessions/kbs 列表由各自 hook 的 effect 并发拉取）
  useEffect(() => {
    let alive = true;
    (async () => {
      const d = await api.defaults().catch(() => null);
      if (!alive || !d) return;
      const saved = savedRef.current;
      if (saved.topK === undefined) setTopK(d.top_k);
      if (saved.chunkSize === undefined) setChunkSize(d.chunk_size);
      if (saved.chunkOverlap === undefined) setChunkOverlap(d.chunk_overlap);
    })();
    return () => {
      alive = false;
    };
  }, [savedRef, setTopK, setChunkSize, setChunkOverlap]);

  const boundKb = sessions.find((s) => s.id === activeSid)?.kb_id ?? null;

  // 首屏「继续上次」：会话列表后端已按 updated_at DESC 排好，取第一条**有真标题**的。
  // 占位名要一起排掉 —— 后端建会话时 title 默认就是「新对话」（api/sessions.py:26），
  // 不是空串，所以只判 trim() 会把刚点开的新会话当成"上次聊的"，
  // 显示成「继续上次 · 新对话 · 刚刚」，等于什么都没说。
  // 这三个占位名与 core/sediment_store.py:369 同一套口径，别各写一份。
  const resumeSession = (() => {
    const PLACEHOLDER = ["新对话", "未命名会话", "untitled"];
    const s = sessions.find((c) => {
      const t = (c.title || "").trim();
      return t && !PLACEHOLDER.includes(t);
    });
    return s ? { id: s.id, title: s.title, updated_at: s.updated_at } : null;
  })();

  // 发送消息（SSE 流式）；attachments 先走 /api/chat/upload 上传，图片由视觉模型消费，
  // 非图片格式后端暂不解析。
  // display：气泡显示的文本（计划功能发送结构化提示时传原问题，提示只给 AI 看）
  // approval：L4 重发（用户在确认卡上点了「允许执行」）。带它时**不追加用户气泡**
  //   —— 那句话已经在消息流里了，重发只是让后端拿到 token 再执行一次工具。
  //   后端也认这个字段（见 api/chat.py 的 user_msg_id 分支）：重发不重复落库。
  // useCallback：保持引用稳定，配合 Bubble 的 memo，流式时不连带重渲染旧消息
  const sendMessage = useCallback(async (
    question: string,
    attachments?: ChatAttachment[],
    display?: string,
    plan?: boolean,
    approval?: { token: string; turnId: string }
  ) => {
    let sid = activeSid;
    // 无会话时自动新建
    if (!sid) {
      try {
        const conv = await api.createSession();
        sid = conv.id;
        setSessions((prev) => [conv, ...prev]);
        setActiveSid(conv.id);
      } catch (e) {
        showToast("error", "新建会话失败，请稍后重试");
        return;
      }
    }

    // 先给用户消息一个临时 id 并记下来：done 帧回来时按它回填 dbId
    if (approval) {
      // 重发：不新增气泡，也不动 userMsgIdRef（那条消息上一轮已经回填过 dbId）。
      // 留着上一轮的值会让 done 里的 user_message_id=0 被当成"没给"而跳过，
      // 这没问题；但若清空则更安全 —— 免得别的分支拿它去比 id。
      userMsgIdRef.current = "";
    } else {
      const userId = uid();
      userMsgIdRef.current = userId;
      setMessages((prev) => [
        ...prev,
        { id: userId, role: "user", content: display ?? question, attachments },
      ]);
    }
    const asstId = uid();
    // 上一轮可能还在播（用户没等它念完就发了新消息）：丢掉剩余缓冲，
    // 并把那条消息的流式状态关掉，否则会卡在"还在写"的样子
    if (playerRef.current) {
      playerRef.current.cancel();
      playerRef.current = null;
      setMessages((prev) => prev.map((m) => (m.streaming ? { ...m, streaming: false } : m)));
    }
    // 播放器：后端 180 字/秒、人读 6 字/秒，差 30 倍 —— 不控速就只能是刷屏。
    // 控速后滚动才可能连续，落点（ChatArea 的锚定）也才有意义。
    const player = createTypewriter({
      onText: (full) =>
        setMessages((prev) => prev.map((m) => (m.id === asstId ? { ...m, content: full } : m))),
      onDone: () => {
        // 播放器放完（正常收尾 / 出错 flush）：到这一刻这一轮才算真正结束
        playerRef.current = null;
        setMessages((prev) =>
          prev.map((m) => (m.id === asstId ? { ...m, streaming: false, status: undefined } : m))
        );
        setSending(false);
      },
    });
    playerRef.current = player;
    // 新一轮开始：先把上一轮的轨迹归零，否则新旧两轮的节点会串在一条时间轴上
    hybrid.reset();
    setMessages((prev) => [
      ...prev,
      { id: asstId, role: "assistant", content: "", streaming: true, toolCalls: [] },
    ]);
    // 记住本轮助手消息 id，供下面的轨迹同步 effect 定位
    asstIdRef.current = asstId;
    const controller = new AbortController();
    abortRef.current = controller;
    setSending(true);

    try {
      // 有附件时先上传到后端（图片理解用）
      let sentAttachments: { path: string; type: string; filename?: string }[] = [];
      if (attachments && attachments.length > 0) {
        const files = attachments.map((a) => a.file).filter((f): f is File => !!f);
        if (files.length > 0) {
          const up = await api.uploadChatAttachments(files);
          sentAttachments = up.files.map((f) => ({
            path: f.path,
            type: f.type,
            filename: f.filename,
          }));
        }
      }
      const gen = streamChat(
        {
          sid,
          question,
          top_k: topK,
          // 能力开关优先于 mode：后端只有在这两个字段都不出现时才看 mode。
          // 两个都显式发（哪怕都是 false），否则只发一个会把另一个压成 false。
          use_kb: useKb,
          use_web: useWeb,
          // 兼容字段：留着兜底，后端在 use_kb/use_web 都在时忽略它。
          mode,
          attachments: sentAttachments,
          location: getSendGeo(),
          // 混合工作流：前端已无「混合」档的入口（四档模式条里没有它，且
          // usePrefs 读偏好时会把遗留的 hybrid 归一成 auto），所以恒为 null。
          // 保留字段是为了不改后端契约；将来若重开，从偏好派生即可。
          workflow_id: null,
          plan: plan ?? false,
          // L4：只有确认卡片点过才有值。两个字段必须一起发 —— 后端把 token
          // 绑在 turn 上，少一个就按"令牌无效"处理，工具会再被拒一次。
          approval_token: approval?.token,
          turn_id: approval?.turnId,
        },
        controller.signal
      );
      let finalRefs = "";
      for await (const ev of gen) {
        // 用户点了「停止生成」就立刻踩刹车。
        // 正常情况 abort 会让 reader.read() 抛 AbortError；但如果中间层（代理 / CDN）
        // 把响应缓冲过，整段帧其实已经到浏览器了，abort 不会报错，也不会让 yield 停下，
        // 于是文字继续往外蹦、看起来「停不掉」。这里主动丢掉剩余帧。
        if (controller.signal.aborted) break;
        switch (ev.event) {
          // ---------- 混合架构三事件（仅 mode=hybrid 才有）----------
          case "hybrid_start": {
            hybrid.onStart(String(ev.data.run_id ?? ""), ev.data.mode === "workflow" ? "workflow" : "agent");
            break;
          }
          case "workflow_node": {
            const phase = ev.data.phase === "exit" ? "exit" : "enter";
            if (phase === "enter") {
              hybrid.onNode({
                phase: "enter",
                node_id: String(ev.data.node_id ?? ""),
                type: (ev.data.type ?? "llm") as never,
                name: String(ev.data.name ?? ""),
              });
            } else {
              hybrid.onNode({
                phase: "exit",
                node_id: String(ev.data.node_id ?? ""),
                status: ev.data.status === "failed" ? "failed" : "ok",
                on_fail: (ev.data.on_fail ?? null) as string | null,
                error: (ev.data.error ?? null) as string | null,
              });
            }
            break;
          }
          case "mode_switch": {
            hybrid.onSwitch({
              rule: String(ev.data.rule ?? ""),
              reason: String(ev.data.reason ?? ""),
              from: ev.data.from === "workflow" ? "workflow" : "agent",
              to: ev.data.to === "workflow" ? "workflow" : "agent",
            });
            break;
          }
          case "token": {
            // 后端现在只发增量，前端自己累加（以前每帧回传全文，长回答流量是平方级）
            const delta = String(ev.data.text ?? "");
            finalRefs = String(ev.data.refs ?? "") || finalRefs;
            // 不直接塞进消息：交给播放器按阅读速度放。180 字/秒的吐字速度
            // 会让页面变成"刷屏到底"，用户只看得见最后一行。
            player.push(delta);
            break;
          }
          case "status": {
            // 检索/规划阶段的进度：带资料库时首帧要等 14 秒，
            // 这期间最少要让人知道"它在干什么"。技术黑话在这里被翻译掉。
            const say = humanizeStatus(String(ev.data.text ?? ""));
            if (!say) break;
            setMessages((prev) =>
              prev.map((m) => (m.id === asstId ? { ...m, status: say } : m))
            );
            break;
          }
          case "sources": {
            // 引用溯源：把检索到的原文片段挂到这条回答上，角标可展开
            const items = (ev.data.items ?? []) as RefSource[];
            if (items.length > 0) {
              setMessages((prev) =>
                prev.map((m) => (m.id === asstId ? { ...m, sources: items } : m))
              );
            }
            break;
          }
          case "web_sources": {
            // 联网来源：web_search 真实返回的网页，收尾时一次性下发。
            // 单独一条事件而不是塞进 sources —— 那条帧是给资料库检索的，
            // 前端按"整条覆盖"处理，挤进去会把知识库来源顶掉。
            const items = (ev.data.items ?? []) as WebSource[];
            if (items.length > 0) {
              setMessages((prev) =>
                prev.map((m) => (m.id === asstId ? { ...m, webSources: items } : m))
              );
            }
            break;
          }
          case "grounding": {
            // 依据强度：后端判定本轮检索够不够格当依据。
            // 单独发一帧而不是塞进 done，是因为用户边流边读，
            // 「依据较弱」这个提示必须赶在正文之前出现在气泡里。
            const g = ev.data as unknown as Grounding;
            setMessages((prev) =>
              prev.map((m) => (m.id === asstId ? { ...m, grounding: g } : m))
            );
            break;
          }
          case "tool": {
            const t = ev.data as unknown as ToolEvent;
            setMessages((prev) =>
              prev.map((m) =>
                m.id === asstId
                  ? { ...m, toolCalls: [...(m.toolCalls ?? []), t] }
                  : m
              )
            );
            break;
          }
          case "title": {
            const title = String(ev.data.title ?? "");
            if (title) {
              setSessions((prev) =>
                prev.map((c) => (c.id === sid ? { ...c, title } : c))
              );
            }
            break;
          }
          case "kb_proposal": {
            // 板块 D7 / D11：后端在回答结束后问「要不要把这轮的东西存成一个库」。
            // 只挂到这一条回答上（不是全局弹窗）：建议针对的正是"这一轮"，
            // 而且用户决定之前它会一直留在原地，刷新页面不会重放（一次性交互）。
            const proposal = {
              proposal_id: String(ev.data.proposal_id ?? ""),
              topic: String(ev.data.topic ?? ""),
              source: String(ev.data.source ?? "no_kb_retrieval") as
                | "no_kb_retrieval"
                | "web_search",
              candidates: Number(ev.data.candidates ?? 0) || 0,
              kb_hint: String(ev.data.kb_hint ?? ""),
              expires_at: Number(ev.data.expires_at ?? 0) || 0,
              reason: String(ev.data.reason ?? ""),
            };
            if (!proposal.proposal_id) break;
            setMessages((prev) =>
              prev.map((m) => (m.id === asstId ? { ...m, proposal } : m))
            );
            break;
          }
          case "approval": {
            // L4：模型要执行会改外部状态的动作（目前只有 download_file），
            // 后端已登记一条待确认请求。这一帧里**没有 token** ——
            // 用户点确认后由卡片去 POST /api/chat/approval 换。
            // 追加而不是覆盖：同一条回答里模型可能对不同参数调两次，
            // 覆盖会让前一张卡片凭空消失（表现就是工具静默不执行）。
            const req = {
              request_id: String(ev.data.request_id ?? ""),
              tool_name: String(ev.data.tool_name ?? ""),
              input: String(ev.data.input ?? ""),
              turn_id: String(ev.data.turn_id ?? ""),
              question: String(ev.data.question ?? ""),
              expires_in: Number(ev.data.expires_in ?? 0) || 0,
            };
            if (!req.request_id) break;
            setMessages((prev) =>
              prev.map((m) =>
                m.id === asstId
                  ? { ...m, approvals: [...(m.approvals ?? []), req] }
                  : m
              )
            );
            break;
          }
          case "done": {
            const refs = String(ev.data.refs ?? "");
            // 后端回传的 messages 表 id：赞踩要按它落库，
            // 前端自己生成的 uid 后端不认，只能在这里补挂
            const dbId = Number(ev.data.message_id ?? 0) || undefined;
            // 混合架构收尾：run_id 回传给消息（刷新后靠它 + /logs 重建轨迹），
            // done.mode 才是**最终**模式（静默回退时这里是 agent）
            const doneMode = String(ev.data.mode ?? "");
            const doneRunId = String(ev.data.run_id ?? "");
            hybrid.onDone(doneMode || null);
            // 只有**本轮真的请求了 hybrid** 时，done.mode=agent 才代表"混合模式回落"。
            // 模式入口收敛成 自动/检索/纯对话 之后，auto 常由后端路由到 agent，
            // 那是正常执行，不是回落 —— 以前这里不看请求模式，于是每条 auto 回答
            // 都挂一块「混合模式当前不可用」，用户看到的是假故障（2026-10-30 修）。
            const requestedHybrid = mode === "hybrid";
            if (doneRunId || (requestedHybrid && (doneMode === "workflow" || doneMode === "agent"))) {
              setMessages((prev) =>
                prev.map((m) =>
                  m.id === asstId
                    ? {
                        ...m,
                        hybridRunId: doneRunId || m.hybridRunId,
                        // 静默回退时这里是 agent：用户选了 hybrid 却没走混合，
                        // 界面要能据此提示，而不是假装一切正常
                        hybridMode: requestedHybrid
                          ? (doneMode === "workflow" || doneMode === "agent" ? doneMode : m.hybridMode ?? null)
                          : null,
                      }
                    : m
                )
              );
            }
            // 计划主题名（P2）：主题可能是后端从历史推断的，前端猜不到，只能靠它回填
            const planTopic = String(ev.data.plan_topic ?? "");
            // 用户那条消息的 id：回填后「存进资料库」不用刷新就能点
            const userDbId = Number(ev.data.user_message_id ?? 0) || undefined;
            const userMsgId = userMsgIdRef.current;
            setMessages((prev) =>
              prev.map((m) => {
                if (m.id === asstId) {
                  // streaming 不在这里关：模型说完了，但播放器手里还有没念完的字。
                  // 关早了光标会提前消失、文字停在半截；收尾交给 player.onDone。
                  return {
                    ...m,
                    refs: refs || finalRefs || m.refs,
                    dbId: dbId ?? m.dbId,
                    planTopic: planTopic || m.planTopic,
                  };
                }
                // 后端没给（旧版本 / 异常分支）就保持原样，不要拿 undefined 覆盖
                if (userMsgId && m.id === userMsgId && userDbId) {
                  return { ...m, dbId: userDbId };
                }
                return m;
              })
            );
            // 上游结束：把手里的字按节奏放完再收尾（"稳稳放完"）
            player.finish();
            break;
          }
          case "error": {
            const detail = detailToMessage(ev.data.detail, "未知错误");
            // 出错就别再慢放：把手里已有的字一次性落地，让错误信息马上可见
            player.flush();
            setMessages((prev) =>
              prev.map((m) =>
                m.id === asstId ? { ...m, error: detail, streaming: false } : m
              )
            );
            break;
          }
        }
      }
      // 兜底：结束流式状态（如果是用户中途停止，气泡要显示"已停止生成"）
      const aborted = controller.signal.aborted;
      if (aborted) {
        // 用户点了「停止生成」：只保留**画面上已经显示出来**的部分。
        // 这里不能 flush —— 打字机里还压着一大段没放出来的字（模型 180 字/秒，
        // 播放器 18~50 字/秒），一次全倒出来，看起来就是"根本没截断"。
        player.cancel();
        playerRef.current = null;
        setMessages((prev) =>
          prev.map((m) =>
            m.id === asstId
              ? { ...m, streaming: false, stopped: true, status: undefined }
              : m
          )
        );
        // cancel() 不会触发 onDone，这一轮的 sending 在这里收
        setSending(false);
      } else {
        // 流断了但没收到 done 帧：让播放器把缓冲放完并收尾，不要留一条永远"正在写"
        player.finish();
      }
    } catch (e) {
      // 用户主动停止（AbortError）不视为错误
      if ((e as Error)?.name !== "AbortError") {
        const detail = e instanceof Error ? e.message : String(e);
        player.flush();
        setMessages((prev) =>
          prev.map((m) =>
            m.id === asstId ? { ...m, error: detail, streaming: false } : m
          )
        );
      } else {
        // 用户主动停止（AbortError）：同样只保留已经显示出来的部分，停在当前画面，
        // 不能把播放器缓冲着的字一次性倒出来（那样等于没有截断）
        player.cancel();
        playerRef.current = null;
        setMessages((prev) =>
          prev.map((m) =>
            m.id === asstId
              ? { ...m, streaming: false, stopped: true, status: undefined }
              : m
          )
        );
        setSending(false);
      }
    } finally {
      abortRef.current = null;
      refreshSessions();
      // 注意：这里不再无条件 setSending(false)。上游结束后打字机还要慢慢放十几秒，
      // 这期间按钮必须仍是「停止」，用户才能随时截断回放；收尾交给 onDone / 上面的 abort 分支。
    }
  }, [activeSid, mode, useKb, useWeb, topK, setSessions, setActiveSid, setMessages, showToast, refreshSessions]);

  // 消息镜像：重试需要读当前列表，但不能让回调依赖 messages，否则每个 token
  // 都会生成新的 onRetry，把 Bubble 的 memo 全部打穿
  const messagesRef = useRef<UiMessage[]>(messages);
  useEffect(() => {
    messagesRef.current = messages;
  }, [messages]);

  // 重新生成：先移除原来的「提问 + 回答」对，再用同一个问题重发，
  // 否则每次重试都会在历史里追加一条新问答，点几次就翻几倍
  const retryMessage = useCallback(
    (assistantId: string, question: string) => {
      if (!question || sending) return;
      const list = messagesRef.current;
      const i = list.findIndex((m) => m.id === assistantId);
      if (i < 0) return;
      const start = i > 0 && list[i - 1].role === "user" ? i - 1 : i;
      setMessages(list.slice(0, start));
      // 重试沿用同一问题：计划类请求要重新带上 plan 标志，否则卡片不会再生成
      void sendMessage(question, undefined, undefined, isPlanRequest(question));
    },
    [sendMessage, sending, setMessages]
  );

  // L4：确认卡点了「允许执行」→ 带 token 重发本轮提问。
  //
  // 为什么是"重发"而不是"直接调用工具"：token 只能证明用户点过，
  // 真正的工具调用发生在模型那一轮里（参数、上下文、守卫都在那条链上）。
  // 所以这里只是把同一句话再问一遍，并让服务端知道"这一轮有人点过确认"。
  //
  // 正在生成时先不接：重发会顶掉当前那条流（sendMessage 会 cancel 播放器），
  // 用户点确认的瞬间往往正是上一轮刚说完的时候，容易出现"点了没反应"。
  const approveTool = useCallback(
    (issued: IssuedApproval, req: ToolApprovalRequest) => {
      if (sending) {
        showToast("info", "还在生成，等这一轮结束再确认");
        return;
      }
      void sendMessage(req.question, undefined, undefined, false, {
        token: issued.approval_token,
        turnId: issued.turn_id,
      });
    },
    [sendMessage, sending, showToast]
  );

  // 停止当前流式生成（中断 SSE 请求）；上游已经结束、只剩打字机在慢放时，直接截断回放。
  //
  // 分两种情况：
  //   ① 请求还在跑 —— abort 掉 SSE，剩下的帧不再收；
  //   ② 请求早就结束了，只是**打字机还在吐字** —— abortRef 已是 null，
  //      老代码直接 ?.abort() 等于什么都没做；1300 字的回答模型 2 秒推完，
  //      播放器按 18~50 字/秒还要放 30 秒，这期间用户随时可能想停。
  const stopSending = () => {
    if (abortRef.current) {
      abortRef.current.abort();
      return;
    }
    // 没有在收流，但文字还在慢慢放：把没放出来的缓冲丢掉，停在当前画面
    const player = playerRef.current;
    if (!player) return;
    player.cancel();
    playerRef.current = null;
    setMessages((prev) =>
      prev.map((m) =>
        m.streaming ? { ...m, streaming: false, stopped: true, status: undefined } : m
      )
    );
    setSending(false);
  };

  // 定位开关：开 → 先试浏览器定位，公网 http 下自动退到服务端 IP 定位；关 → 仅关闭开关（保留缓存）
  const toggleGeo = async () => {
    if (geoEnabled) {
      setGeoEnabled(false);
      setGeoEnabledState(false);
      return;
    }
    // 这一段最长要 18 秒：等浏览器授权弹窗 10s（用户不点允许/拒绝就一直等到超时），
    // 拿不到再退服务端 IP 定位 8s。不给 pending 反馈的话，用户会以为按钮坏了。
    setGeoPending(true);
    const r = await acquireGeo();
    if (!r) {
      setGeoPending(false);
      /* ★ 这里以前弹一句「定位失败：当前环境不支持浏览器定位，后端也未能按 IP 推断城市
         （需 AMAP_API_KEY）」—— 这是把服务端的配置缺失念给用户听。他既看不懂也修不了，
         只会得出"这应用坏了"的结论。定位拿不到绝大多数是环境限制（http 下浏览器不给坐标、
         服务端没配高德 key），不是用户做错了什么。
         现在改成：不报错，直接把「你在哪个城市」的输入框展开。给出路比说原因有用。 */
      setCityEdit(true);
      return;
    }
    // IP 定位只有市级名（高德 IP 接口的上限）；浏览器定位只有坐标，
    // 要逆地理补出「市 + 区县」——仅角标展示用，失败不影响定位本身。
    // ★ 区县只用于**展示**，绝不进 getSendGeo 的 city 字段：
    //   agent/builder.py 会把它拼成 get_weather(city='...')，带「·」的串查不到城市。
    const manual = getManualCity();
    if (manual) {
      // 用户手填过城市：定位照开（坐标对天气精度仍有价值），但**地名不覆盖他改的**
      setGeoEnabled(true);
      setGeoEnabledState(true);
      setGeoPending(false);
      // 提示语不再说「定位已开启」：针已经变金色、角标已经出现，再说一遍是重复。
      // 这句话只留一件用户真正想知道的事 —— 他手填的城市没被覆盖。
      showToast("success", `城市用你填的${manual}，问天气不用再输`);
      return;
    }
    let place: { city: string; district: string } | null = null;
    if (r.geo.city) {
      place = { city: r.geo.city, district: "" }; // IP 兜底：城市级就到此为止，不编区县
    } else if (typeof r.geo.lat === "number" && typeof r.geo.lon === "number") {
      try {
        place = await reverseGeocodePlace(r.geo.lat, r.geo.lon);
      } catch {
        place = null;
      }
    }
    const label = formatPlace(place);
    if (place) {
      updateCachedPlace(place);
      setGeoCity(label || null);
    }
    setGeoEnabled(true);
    setGeoEnabledState(true);
    setGeoPending(false);
    showToast(
      "success",
      label
        ? r.source === "ip"
          ? `已按 IP 定位到${label}（城市级），问天气无需再输城市`
          : `定位到${label}，问天气无需再输城市`
        : // 拿到了坐标但认不出城市名：角标不会出现，这句话是唯一的反馈，
          // 所以不能吹「问天气无需再输城市」—— 直接告诉他下一步怎么做
          "拿到了位置，但没认出城市名 —— 问天气时直接说城市就行"
    );
  };

  /**
   * 手填城市：用户说了算。
   * 只保存城市名、不保存坐标 —— getSendGeo 会在有手填值时只送 city，
   * 否则后端拿坐标重新逆地理，会把用户改的结果又推回原样，等于没得改。
   */
  const saveCity = (name: string) => {
    const v = setManualCity(name);
    setCityEdit(false);
    if (!v) {
      // 清空 = 撤销手填，角标回到自动定位的结果（可能为空 —— 那就没有地名可显示，
      // 角标整块不出现；定位针仍是金色，状态不丢）
      setGeoCity(formatPlace(getCachedGeo()) || null);
      return;
    }
    setGeoEnabled(true);
    setGeoEnabledState(true);
    setGeoCity(v);
    showToast("success", `已设为${v}，问天气不用再输城市`);
  };

  // 绑定/解绑知识库（跨域：改会话，所以留在编排层）
  const bindKb = async (kbId: string | null) => {
    let sid = activeSid;
    // 绑定是「按会话生效」的，一个会话都没有时先自动建一个（与 sendMessage 的做法一致）。
    // 不能像之前那样直接 return：静默失败等于让用户对着一个看起来坏掉的勾选框反复点。
    if (!sid) {
      try {
        const conv = await api.createSession();
        sid = conv.id;
        setSessions((prev) => [conv, ...prev]);
        setActiveSid(conv.id);
      } catch {
        showToast("error", "绑定失败：无法新建会话，请稍后重试");
        return;
      }
    }
    try {
      const conv = await api.bindKb(sid, kbId);
      setSessions((prev) => prev.map((c) => (c.id === sid ? conv : c)));
      showToast(kbId ? "success" : "info", kbId ? "已绑定资料库" : "已解绑资料库");
    } catch (e) {
      showToast("error", "绑定失败，请稍后重试");
    }
  };

  // 联网建库：逐条抓（带进度）→ 自动绑定当前会话 → 预填一个建议问题（不自动发送）
  // params：面板上选的「处理方式」档位；没传则用全局兜底值
  const webImport = async (
    kbName: string,
    urls: string[],
    onProgress: (i: number, total: number, title: string) => void,
    params?: ChunkParams
  ): Promise<string> => {
    const cs = params?.size ?? chunkSize;
    const co = params?.overlap ?? chunkOverlap;
    // 本次是否新建了库：全失败时要回滚，否则会留一个里面空空的库
    let createdId: string | null = null;
    try {
      // 先把名字对上当前用户已有的库：手打的名字只要大小写/首尾空格略有出入，
      // 直连 createKb 就会用不同 kb_id 再建一个同名库。命中则复用，不新建。
      const norm = kbName.trim().toLowerCase();
      const existing = kbs.find((k) => (k.name || "").trim().toLowerCase() === norm);
      let kb_id: string;
      if (existing) {
        kb_id = existing.kb_id;
      } else {
        kb_id = (await api.createKb(kbName)).kb_id;
        createdId = kb_id;
      }
      let ok = 0;
      for (let i = 0; i < urls.length; i++) {
        const url = urls[i];
        try {
          const r = await api.importUrl(kb_id, url, cs, co);
          ok += 1;
          onProgress(i + 1, urls.length, r.title || url);
        } catch {
          onProgress(i + 1, urls.length, "");
        }
      }
      // 一篇都没抓到、库又是这次新建的：删掉空壳并明确报错，别让用户以为导进去了
      if (ok === 0 && createdId) {
        await api.deleteKb(createdId).catch(() => {});
        createdId = null; // 已清理，外层 catch 不要重复删
        await refreshKbs();
        showToast("error", `这 ${urls.length} 篇都没抓到正文，已取消建库`);
        throw new Error("web-import-empty");
      }
      // 至少抓到一篇才算用上了这套参数，记下来供列表标签和「重新整理」复用
      if (ok > 0) rememberChunk(kb_id, { size: cs, overlap: co });
      await refreshKbs();
      // 不再用 if (activeSid) 挡一道：bindKb 自己会在没有会话时建一个，
      // 否则「联网建库成功但没绑上」会让人以为是导入失败了。
      await bindKb(kb_id);
      const suggested = `根据「${kbName}」里刚导入的 ${ok} 篇资料，帮我做个要点总结`;
      setPrefill({ text: suggested, ts: Date.now() });
      showToast("success", `联网建库完成：成功 ${ok} / ${urls.length}`);
      return kb_id;
    } catch (e) {
      if (createdId) {
        // 其它异常（如 bindKb 失败）同样把空壳清掉
        await api.deleteKb(createdId).catch(() => {});
        createdId = null;
        await refreshKbs();
        showToast("error", "导入失败，已取消建库，请稍后重试");
      } else if ((e as Error)?.message !== "web-import-empty") {
        showToast("error", "导入失败，请稍后重试");
      }
      throw e;
    }
  };

  // 首屏三件套都完成才算 boot 完成（骨架屏统一消失）
  const booting = sessionsLoading || kbsLoading;

  // 抽屉遮罩：窄屏开了左栏，或中/窄屏开了右栏时显示
  const overlayOpen =
    (viewport === "narrow" && sidebarOpen) || (viewport !== "wide" && kbPanelOpen);

  const closeOverlays = useCallback(() => {
    setSidebarOpen(false);
    if (viewport !== "wide") setKbPanelOpen(false);
  }, [viewport, setKbPanelOpen]);

  // 抽屉：Esc 关闭，打开时焦点移入面板，关闭后归还给触发它的按钮
  useEffect(() => {
    if (!overlayOpen) return;
    const opener = document.activeElement as HTMLElement | null;
    const panel = sidebarOpen ? sidebarRef.current : kbRef.current;
    // 等浮层开始滑入再抢焦点，否则会被 transform 过渡打断
    const t = window.setTimeout(() => panel?.focus(), 60);
    const onKey = (e: KeyboardEvent) => {
      if (e.key !== "Escape") return;
      e.preventDefault();
      closeOverlays();
    };
    document.addEventListener("keydown", onKey);
    return () => {
      window.clearTimeout(t);
      document.removeEventListener("keydown", onKey);
      opener?.focus?.();
    };
  }, [overlayOpen, sidebarOpen, closeOverlays]);

  // ---- 登录门 ----
  // 必须放在所有 hooks 之后：React 不允许条件调用 hook，但允许提前 return。
  // 身份没确认完先不给工作台，免得空列表闪一下又跳回登录页。
  if (auth.loading) {
    return <AuthLoading />;
  }
  if (!auth.me) {
    // 未登录看到的是落地页，不再是一张孤零零的登录卡片。
    // 第一次从搜索结果 / 别人发的链接进来的人，需要一个说清楚"这是什么"的地方，
    // 而不是先被要一个账号。登录卡片挪到 /login，落地页里每个「开始使用」都指向它。
    return (
      <>
        <Landing />
        {/* 登录门之外也挂一个：?ann=<期号> 是拿来给人看版式的预览入口，
            没账号也该看得见。不带这个参数时它自己什么都不渲染（见组件里的 open 判定） */}
        <AnnounceModal userId={null} />
      </>
    );
  }

  return (
    <>
    <main className="workbench-main flex overflow-hidden">
      {/* ★ 2026-11-18（合并外壳）：这一页搬进了 (console) 路由组。
         以前 `/` 和 `(console)` 是两套外壳 —— 两套 layout、两个滚动容器、
          两套页头语法，只有底栏是同一个组件。用户的原话是「从对话到功能模块
          整体割裂感较强」：点进打卡的感觉是"换了一个 App"，不是"翻了一页"。
         现在 layout 只有一份（components/console/ConsoleLayout.tsx）：
           · 底栏、登录门、上手说明、公告、切页淡入全在外壳里，本页不再自己挂
             ConsoleTabBar（外壳按路由给 dialog 页 `variant="dock"`）；
           · 滚动容器归外壳的 .console-scroll，对话页给它加 `--chat` 变体
             （不滚动、不铺卡片、高度铺满），对话自己的 .chat-scroll 仍管消息区；
           · 本页仍然是唯一的 `<main>`：外壳在对话路由下把容器渲染成 div，
             否则会套出 <main><main>。
         桌面左栏仍由 Sidebar 担任（它本来就带完整模块入口，见 lib/nav 的
         chatRailNav）—— 外壳的 .console-nav 在对话页隐藏，避免两条左栏。
          底栏与输入区"并成一块"的做法（dock 变体 / --chat-dock-chrome）没变，
          只让位那一套仍然在 fx.css 的 main.workbench-main 里。 */}
      {/* 「装到桌面」的首次提示。★ 刻意挂在登录态确定之后（这里或上面的登录门分支），
          不挂根布局：根布局会在登录门出现之前就渲染，组件判定「可以弹」→
          立刻写下 60 天冷却，等用户真登录进来就再也不弹了（线上实测，探针里
          localStorage 里躺着一个比登录更早的时间戳）。
          position:fixed 的浮层不受 main 的 flex 与 overflow:hidden 影响，不占位。
          ★ 2026-11-16：原生壳里已注入 window.__zhisuiApp，isInstalled() 会返回 true，
            这条在 App 里不再出现（以前会在 App 里劝用户"把知穗装到桌面"）。 */}
      <InstallBanner />
      <Sidebar
        sessions={sessions}
        activeSid={activeSid}
        onSelect={(sid) => {
          selectSession(sid);
          setSidebarOpen(false); // 窄屏抽屉里点完会话就收起来
        }}
        onCreate={() => {
          void createSession();
          // 与 onSelect 同理：抽屉是「选会话」的地方，点了「新建对话」就该落在
          // 新会话上。原来只关 onSelect，手机点完「新建对话」抽屉还盖着，
          // 看起来像没点中（2026-11-16 复现：截图里欢迎页整块被抽屉压住）。
          setSidebarOpen(false);
        }}
        onOpenLibrary={() => {
          // 曾经是 window.location.href —— 那是**整页刷新**：浏览器白一帧、
          // 重新下载整包 JS、再重新探活。广场本来就在同一个 Next 应用里，
          // 走路由跳转才有"页面被换掉"而不是"应用被重启"的观感。
          router.push("/library");
        }}
        onRename={renameSession}
        onDelete={deleteSession}
        kbNameMap={kbNameMap}
        containerRef={sidebarRef}
        loading={booting}
        loadError={bootError}
        onRetryLoad={reloadSessions}
        dark={dark}
        fontScale={fontScale}
        onFontScaleChange={setFontScale}
        onToggleDark={toggleDark}
        overlay={viewport === "narrow"}
        open={sidebarOpen}
        username={auth.me?.user.username}
        isAdmin={auth.me?.is_admin}
        displayName={auth.me?.user.nickname || auth.me?.user.username}
        avatar={auth.me?.user.avatar}
        onOpenUsage={() => setUsageOpen(true)}
        onLogout={() => void auth.logout()}
      />

      <div className="flex min-w-0 flex-1 flex-col">
        <ChatArea
          messages={messages}
          sending={sending}
          // 播放器还在放字（网络可能早就结束了）：让停止键在这段时间也留着
          playing={messages.some((m) => m.streaming)}
          capValue={capValue}
          onCapChange={onCapChange}
          onSend={sendMessage}
          onStop={stopSending}
          onRetry={retryMessage}
          onNotice={showToast}
          topK={topK}
          onTopKChange={setTopK}
          sessionTitle={sessions.find((s) => s.id === activeSid)?.title ?? null}
          resumeSession={resumeSession}
          onResumeSession={(sid) => void selectSession(sid)}
          boundKb={boundKb}
          kbCount={kbs.length}
          kbNameMap={kbNameMap}
          onUnbindKb={() => bindKb(null)}
          onToggleKbPanel={() => setKbPanelOpen(!kbPanelOpen)}
          kbPanelOpen={kbPanelOpen}
          onOpenSidebar={viewport === "narrow" ? () => setSidebarOpen(true) : undefined}
          prefill={prefill ?? undefined}
          onDeleteTurn={deleteTurn}
          onSediment={(dbId, text, role) => setSediment({ focus: dbId, text, role })}
          onKbSaved={refreshKbs}
          onApproveTool={approveTool}
          geoEnabled={geoEnabled}
          geoCity={geoCity}
          geoPending={geoPending}
          onToggleGeo={toggleGeo}
          cityEditOpen={cityEdit}
          onCityEditOpenChange={setCityEdit}
          onSaveCity={saveCity}
          sessionId={activeSid}
          userId={authedId}
        />
      </div>

      <KnowledgePanel
        kbs={kbs}
        publicKbs={publicKbs}
        favKbs={favKbs}
        onToggleFavorite={(kbId, on) => void toggleFavorite(kbId, on)}
        boundKb={boundKb}
        onUpload={async (kbName, files, size, overlap) => {
          const kbId = await uploadFiles(kbName, files, size, overlap);
          // 导入成功就顺手绑上：建库的意图本来就是「要用它」，
          // 之前让用户自己去勾方框，等于把系统分内事推给用户。
          if (kbId) await bindKb(kbId);
        }}
        onSearch={searchPreview}
        onWebImport={webImport}
        onDeleteKb={deleteKb}
        onDeleteFile={deleteKbFile}
        onRebuildKb={rebuildKb}
        kbChunkOf={chunkParamsOf}
        onBind={bindKb}
        containerRef={kbRef}
        loading={booting}
        chunkSize={chunkSize}
        chunkOverlap={chunkOverlap}
        onCollapse={() => setKbPanelOpen(false)}
        overlay={viewport !== "wide"}
        open={kbPanelOpen}
        sid={activeSid}
        onOpenSediment={() => setSediment({ focus: null, text: null, role: "user" })}
      />

      {sediment && (
        <SedimentModal
          sid={activeSid}
          defaultKbId={boundKb}
          boundKb={boundKb}
          onBind={bindKb}
          focusRef={sediment.focus}
          focusText={sediment.text}
          focusRole={sediment.role}
          onClose={() => setSediment(null)}
          onImported={() => {
            // 库里多了几条，右栏的条目数要跟着变
            void refreshKbs();
            showToast("success", "存好了 —— 下次问到相关的事，会先翻这个库");
          }}
        />
      )}

      {/* 抽屉遮罩：点击关闭浮层 */}
      <div
        className={`drawer-backdrop ${overlayOpen ? "show" : ""}`}
        onClick={closeOverlays}
        aria-hidden="true"
      />

      {/* Toast 容器：role/aria-live 让屏幕阅读器能播报操作结果，
          与 console/ui.tsx 的 ToastHost 保持同一份语义（两个渲染点都要带） */}
      <div className="toast-container" role="status" aria-live="polite">
        {toasts.map((t) => (
          <div key={t.id} className={`toast ${t.type}`}>
            <span>{t.msg}</span>
          </div>
        ))}
      </div>

      {/* 用量与反馈看板（portal 到 body，不受三栏布局裁切） */}
      {usageOpen && <UsagePanel onClose={() => setUsageOpen(false)} />}

      {/* ★ 底栏在 2026-11-18 的合并外壳里由 layout 统一挂载（这里是它的内容区，
          自己再挂一份就会出现两条导航）。层级关系随之搬进 CSS：
          本页的 main 不再是层叠上下文，改由 .console-scroll--chat 统一决定
          40（底栏）< 60（遮罩）< 70（抽屉 / 资料库面板）—— 见 console.css 里
          「合并外壳」那一段。 */}
    </main>
    </>
  );
}

