"use client";

// 中央对话区：书本打开效果 + 欢迎页 + 底部输入框
// 视觉：暖米黄书本风格 · 大圆角 · 柔阴影 · 金色点缀
//
// 2026-09 重构：消息类型/常量/正文渲染/计划卡片/Bubble/Field 拆到 ./chat/*，
// 本文件只保留主组件（顶栏 + 欢迎页 + 消息区 + 输入区）。
import { useCallback, useEffect, useMemo, useRef, useState } from "react";
import Link from "next/link";
import MascotLogo from "./chat/MascotLogo";
import CornIcon from "./CornIcon";
import NavIcon from "./NavIcon";
import { api } from "@/lib/api";
import type { RefSource, IssuedApproval, ToolApprovalRequest } from "@/lib/types";
import { HOME_GROUPS, TOOLS_URL } from "./chat/constants";
import TodayStrip from "./chat/TodayStrip";
import PushNudge from "./chat/PushNudge";
import ResumeStrip from "./chat/ResumeStrip";
import { isPlanRequest, stripPlanHint } from "./chat/plan";
import CapToggles, { type CapValue } from "./chat/CapToggles";
import Bubble from "./chat/Bubble";
import BubbleErrorBoundary from "./chat/BubbleErrorBoundary";
import TurnOutline from "./chat/TurnOutline";
import QueryEnhance from "./chat/QueryEnhance";
import FeedbackModal from "./feedback/FeedbackModal";
import type { ChatAttachment, UiMessage } from "./chat/types";
import FilePreviewModal from "./FilePreviewModal";

// 兼容导出：page.tsx 仍从 "@/components/ChatArea" 引入这些符号
export type { UiMessage, ChatAttachment } from "./chat/types";
export { stripPlanHint } from "./chat/plan";

const aid = () => Math.random().toString(36).slice(2, 10);

/**
 * 回答顶边与视口顶部之间留的空隙。
 * 不留会顶到边框上，读第一行时眼睛没有落点；留太多又会显得内容被"推下去"。
 */
const ANCHOR_GAP = 14;

/**
 * 跟随阶段回答底边与视口底部之间留的空隙。
 * 贴死会显得最后一行被裁掉半截，留 18px 读起来有收尾感。
 */
const TAIL_PAD = 18;

/**
 * 锚定后「先让开头留在视口里」的时长（毫秒）。
 *
 * 2026-11-02：原来写死 320ms，实测在手机上几乎等于没有 —— 回答长得比眼睛快，
 * 刚锚好就被下一帧顶走，用户根本来不及确认"这是开头"。1400ms 大约够读完 3 行，
 * 之后才转入跟随。不是越长越好：太长会让"正在写"的反馈断掉。
 */
const ANCHOR_HOLD_MS = 1400;

/**
 * 跟随滚动「追平一段落差」所用的时长（毫秒）。
 *
 * 2026-11-02 第三轮：手机上一行中文约 25~33px，每 0.3~0.4 秒来一行。
 * 原来的「每帧走剩余量 1/3、最多 6 帧」会在 100ms 内把一整行走完然后停 300ms ——
 * 节奏是"弹一下、静一下"，用户原话"一抽一抽"。
 *
 * 现在不管落差多大都用固定时长匀速走完：25px 摊到 280ms，每帧只动 1~2px，
 * 和"下一行什么时候来"基本同拍，观感是内容匀速上移。
 * 取 280ms 而不是更长：再长就跟不上新行，视野会被越拖越远。
 */
const SCROLL_DURATION_MS = 280;

/**
 * 「一屏以上」的落差直接落位，不播动画（2026-11-18）。
 *
 * 上面的匀速追平是为**流式跟随**调的：一行 33px、0.28 秒走完，每帧 1~2px，
 * 眼睛看到的是内容自己往上淌。可它被复用到了「进会话」那条路上 ——
 * 从别的页面回到对话时，`messages` 从空变成整段历史，`scrollHeight` 一口气
 * 多出几千像素，`programScroll` 照样按 280ms 匀速走完：5000px / 280ms ≈ 18px/ms，
 * 一屏内容在一瞬间刷过去。用户的原话是「返回对话框时会出现极强的滑动效果」。
 *
 * 落差的语义本来就分两种：
 *   · 小落差 = 内容长了，视野跟着走 → 该有动画（否则一顿一顿）；
 *   · 大落差 = 换了一个视野（进会话 / 切会话 / 回到最新）→ 动画只会让人晕。
 * 所以用一屏当界：超过 0.9 屏就 `scrollTop = target`，一帧到位、零位移感。
 * 为什么是 0.9 而不是 1：留一点提前量，键盘收起/地址栏伸缩导致可视区变高时
 * 那点差额不该被判成"大落差"。
 */
const JUMP_SCREENS = 0.9;

/**
 * 检索条数也换成白话档位。
 * 「topK = 5」没人看得懂，「参考 5 段资料」一看就明白，
 * 顺带把「多参考 = 更全但更慢」的取舍讲清楚。
 */
const TOP_K_MODES = [
  { value: 3, hint: "更快" },
  { value: 5, hint: "均衡" },
  { value: 8, hint: "更全" },
] as const;

interface Props {
  messages: UiMessage[];
  sending: boolean;
  /**
   * 回答是否还在**逐字播放**（网络已结束，打字机还在按 18~50 字/秒往外放）。
   *
   * ★ 为什么要单独传：`sending` 只跟网络请求的生死。1300 字的回答模型 2 秒推完，
   *   播放器还要放 30 秒 —— 这 30 秒里 `sending` 已经是 false，停止键就变回了发送键，
   *   而字还在一个个往外冒。用户点"截断"根本找不到按钮，这就是「截断不可用」的真身。
   */
  playing?: boolean;
  /**
   * 两枚能力开关的当前值（受控）。2026-10-31 批 B：四档模式条下架后，
   * 它成了输入区上方**唯一**的能力入口，所以是必填 —— 它要进请求体
   * （use_kb / use_web），住在本组件内部的 state 里就发不出去了。
   */
  capValue: CapValue;
  /** 开关变化。页面层写进 usePrefs，下一轮请求体生效 */
  onCapChange?: (next: CapValue) => void;
  onSend: (question: string, attachments?: ChatAttachment[], display?: string, plan?: boolean) => void;
  onStop: () => void;
  /** 重新生成：传入目标助手消息 id 与原始问题，覆盖原答案而不是追加 */
  onRetry?: (assistantId: string, question: string) => void;
  /** 轻量反馈出口：复制失败、赞踩等，交给页面出 toast */
  onNotice?: (type: "success" | "error" | "info", msg: string) => void;
  topK: number;
  /** 检索条数变化。资料怎么切片是「建库时」的事，在右侧资料库面板按库设置 */
  onTopKChange: (v: number) => void;
  sessionTitle?: string | null;
  /**
   * 首屏「继续上次」要显示的那一次对话。传 null / 不传 = 整块不渲染。
   *
   * 由页面层从会话列表里挑（最近的、且标题不为空的），不在本组件里取数：
   * 本组件是纯展示，会话列表归 useSessions 管 —— 在这里再拉一次列表，
   * 首屏就会多一个请求，而它和外壳的加载时序还不同步（闪烁的来源）。
   */
  resumeSession?: { id: string; title: string; updated_at: number } | null;
  onResumeSession?: (sid: string) => void;
  boundKb?: string | null;
  /** 该用户拥有的资料库总数：>0 且当前未绑定时，顶栏给「未绑定」引导提示 */
  kbCount?: number;  kbNameMap?: Record<string, string>;
  onUnbindKb?: () => void;
  kbPanelOpen?: boolean;
  onToggleKbPanel?: () => void;
  /** 窄屏下打开会话列表抽屉 */
  onOpenSidebar?: () => void;
  /** 外部把建议问题预填进输入框（如联网建库后），不自动发送 */
  prefill?: { text: string; ts: number };
  /** 删除某条消息及其所在的一轮对话（user + 后续 assistant） */
  onDeleteTurn?: (msgDbId: number) => void;
  /**
   * 把某条用户消息收进资料库。
   *
   * 入口长在消息自己的动作排里（不是右栏、不是资料库页）——这个功能最难的地方
   * 不是能不能存，而是用户想不起来它存在。它必须出现在「刚刚说清楚一件事」
   * 的那一刻，而那一刻用户的视线就在自己那条消息下面。
   */
  onSediment?: (msgDbId: number, text: string, role: "user" | "assistant") => void;
  /**
   * 建库建议卡点了「建库并存入」之后要做什么。
   *
   * 必须由上层刷新资料库列表：卡片只知道「我建成了」，右侧面板和顶部「资料库 N」
   * 各自持有一份早先拉到的列表，不刷新就会出现「卡片说已存进，面板说还没有资料库」
   * —— 用户会以为没成功，又点一遍。
   */
  onKbSaved?: () => void;
  /**
   * 高风险工具确认卡点了「允许执行」并拿到 token（L4）。
   * 透传到 Bubble → ApprovalCard；重发这件事只有页面层能做（会话 / 播放器 /
   * 中止句柄都在那儿），所以这一层只负责往下递，不实现任何逻辑。
   */
  onApproveTool?: (issued: IssuedApproval, req: ToolApprovalRequest) => void;
  /** 地理定位开关状态（开启后发送消息自动带坐标） */
  geoEnabled?: boolean;
  /** 当前定位城市（角标展示用，可能为 null） */
  geoCity?: string | null;
  /** 定位请求进行中：等授权 + IP 兜底最长要 18 秒，期间按钮禁用并转圈 */
  geoPending?: boolean;
  /** 切换定位开关（请求权限 / 关闭），由页面层处理权限与缓存 */
  onToggleGeo?: () => void;
  /** 手填城市的输入框是否展开（定位拿不到时由页面层直接展开，不弹报错） */
  cityEditOpen?: boolean;
  onCityEditOpenChange?: (v: boolean) => void;
  /** 保存手填的城市；传空串表示撤销手填，回到自动定位 */
  onSaveCity?: (name: string) => void;
  /** 当前会话 id：赞踩要按「会话 + 消息 id」落库，否则后端无从归档 */
  sessionId?: string | null;
  /** ★ 2026-11-18：额度不再进对话区 —— 顶栏胶囊已拆，见设置页的「今日额度」。
  /** 当前用户 id：新手引导条的「已关闭」状态按人存，换人登录要重新看到 */
  userId?: string | null;
}

export default function ChatArea({
  messages,
  sending,
  playing = false,
  capValue,
  onCapChange,
  onSend,
  onStop,
  onRetry,
  onNotice,
  topK,
  onTopKChange,
  sessionTitle,
  boundKb,
  kbCount,
  kbNameMap,
  onUnbindKb,
  kbPanelOpen,
  onToggleKbPanel,
  onOpenSidebar,
  prefill,
  onDeleteTurn,
  onSediment,
  onKbSaved,
  onApproveTool,
  geoEnabled = false,
  geoCity = null,
  geoPending = false,
  onToggleGeo,
  cityEditOpen = false,
  onCityEditOpenChange,
  onSaveCity,
  sessionId = null,
  userId = null,
  resumeSession = null,
  onResumeSession,
}: Props) {
  const [input, setInput] = useState("");
  const [showParams, setShowParams] = useState(false);
  // 「自己填」展开：想直接敲数字的少数人才会点
  const [advancedTopK, setAdvancedTopK] = useState(false);
  const [pending, setPending] = useState<ChatAttachment[]>([]);
  const scrollRef = useRef<HTMLDivElement>(null);
  const inputRef = useRef<HTMLTextAreaElement>(null);
  const attachRef = useRef<HTMLInputElement>(null);
  // 输入历史：↑/↓ 在历史里前后翻，Esc 清空输入框
  // 本地历史用惰性初始值读，不在 effect 里 setState（会触发 react-hooks/set-state-in-effect）
  const [history, setHistory] = useState<string[]>(() => {
    try {
      const raw = typeof localStorage === "undefined" ? null : localStorage.getItem("baomi.history");
      if (!raw) return [];
      const arr = JSON.parse(raw);
      return Array.isArray(arr) ? arr.filter((x) => typeof x === "string").slice(0, 50) : [];
    } catch {
      // 历史是锦上添花，读不到（隐私模式下 localStorage 不可用）不影响主流程
      return [];
    }
  });
  const histIdxRef = useRef(-1); // -1 = 正在编辑草稿
  const draftRef = useRef("");
  const stickRef = useRef(true);
  const [atBottom, setAtBottom] = useState(true);
  /** 已经锚定过顶部的助理消息 id：锚定只做一次，之后回到正常跟随 */
  const anchoredRef = useRef<string | null>(null);
  /** 程序自己设的 scrollTop 目标：onScroll 靠它区分"用户在滚"和"我们在滚" */
  const progTopRef = useRef<number | null>(null);
  /** 平滑滚动的截止时刻：期间不把滚动事件算成用户意图 */
  const smoothUntilRef = useRef(0);
  /** 锚定后的开头保护截止时刻：这段时间内不跟随，让"开头"在视口里停一会儿 */
  const anchorUntilRef = useRef(0);
  /** 锚定落地的 scrollTop：跟随阶段不能比它更靠上，否则回答还没长满一屏开头就被顶走 */
  const anchoredPosRef = useRef<number | null>(null);
  const scrollRafRef = useRef<number | null>(null);
  /** 我们最后一次把 scrollTop 设成的值。onScroll 用它认领"这是我们自己滚的" ——
   *  比时间窗可靠：手机上 rAF 慢、scroll 事件有延迟，时间窗经常开错。 */
  const appliedTopRef = useRef<number | null>(null);
  /** 消息末尾的留白元素：让"回答不足一屏"时也滚得到顶部（详见下方 effect） */
  const tailRef = useRef<HTMLDivElement | null>(null);
  // 从引用角标打开的全文预览（文件名来自 RefSource，kb 用当前会话绑定的）
  const [previewFile, setPreviewFile] = useState<string | null>(null);
  // 今天条到底有没有出现（由 TodayStrip 回填）。推送入口靠它决定要不要渲染 ——
  // 详见 chat/PushNudge.tsx 顶部：两个东西的人群是同一批，位置也就该在一起。
  const [todayHasAny, setTodayHasAny] = useState(false);
  // 顶栏「反馈」弹窗。**必须是 useCallback**：FeedbackModal 的 Esc / 焦点 effect
  // 依赖 onClose，每次渲染都换引用会让 effect 反复重跑、把焦点从文本框里抢回来。
  const [fbOpen, setFbOpen] = useState(false);
  const closeFeedback = useCallback(() => setFbOpen(false), []);
  // 联网建库后把建议问题预填进输入框：渲染期基于 prop 调整 state（用 state 去重，避免 ref 在渲染期被读写），
  // 不自动发送，让用户确认/补充后再发
  const [appliedPrefillTs, setAppliedPrefillTs] = useState<number>(-1);
  if (prefill && prefill.ts !== appliedPrefillTs) {
    setAppliedPrefillTs(prefill.ts);
    setInput(prefill.text);
  }

  // 高度自适应统一在这里做：历史回填时也会跟着变高
  useEffect(() => {
    const el = inputRef.current;
    if (!el) return;
    el.style.height = "auto";
    el.style.height = Math.min(el.scrollHeight, 160) + "px";
  }, [input]);

  // 进来就能打字：省掉"先点一下输入框"这一步
  useEffect(() => {
    inputRef.current?.focus();
  }, []);

  // 预填建议问题后把焦点送进输入框（仅副作用，不在此 setState）
  useEffect(() => {
    if (!prefill) return;
    inputRef.current?.focus();
  }, [prefill]);

  // 按时段问候：SSR 与水合各算一次可能跨过整点，首帧用安全默认值，挂载后再校准
  const [greeting, setGreeting] = useState("你好呀");
  useEffect(() => {
    const h = new Date().getHours();
    setGreeting(
      h < 6 ? "夜深了" : h < 11 ? "早上好" : h < 13 ? "中午好" : h < 18 ? "下午好" : "晚上好"
    );
  }, []);

  const pendingImageCount = pending.filter((a) => a.type.startsWith("image/")).length;
  const pendingOtherCount = pending.length - pendingImageCount;

  // capValue 是受控 props（页面层持有）：它要进请求体，住在这里就发不出去。
  // 输入框下面那行提示跟着它变 —— 这是四档模式条下架后用户唯一能看到的
  // "这一轮会怎么答"的说明，所以两枚开关的四种组合都要说清楚。
  // 每句都控制在 9 字以内：这行右侧还钉着「Enter 发送 · ↑ 上一条 · Esc 清空」，
  // 390px 下超了就被截成「…」（第一版「先翻你的资料库，不够再上网」就被截）
  const capHint = capValue.kb
    ? capValue.web
      ? "先查资料，再联网"
      : "只查你的资料库"
    : capValue.web
      ? "会联网查最新信息"
      : "都不勾＝纯对话";

  // 程序滚动：同一帧里多次触发只落一次，且把目标值记下来供 onScroll 认领
  //
  // ★ 2026-11-02 第二次重做（手机端「还是在底部一抽一抽」）：
  //   上一版是「每帧走剩余量的 1/3，最多 6 帧后直接 snap 到位」。线上采样暴露了问题：
  //   一行中文约 33px，先在 ~100ms 内一口气走完 6 帧，然后停 300ms 等下一行 ——
  //   节奏是「弹一下、静一下、弹一下」。桌面一行字多（~40 字），0.9 秒才弹一次，
  //   察觉不到；手机一行只有 21 字，0.4 秒弹一次，就成了"一抽一抽"。
  //   实测位移分布：一共 732 个 50ms 采样点，只有 108 个点在动（15%），
  //   动的那些中位 16.5px、90 分位 25px —— 典型的"脉冲式"位移。
  //
  //   现在的做法：**匀速追平**。不管落差是 25px 还是 800px，都在固定的
  //   SCROLL_DURATION_MS 内以恒定速度走完 —— 每帧的步长完全一样，
  //   视觉上是一条匀速上移的带子，而不是"起步一冲、尾巴拖沓"。
  //
  //   ★ 为什么不用指数缓动（试过，不行）：指数缓动第一帧就走掉剩余量的 20%，
  //     25px 的一行会变成「100ms 内冲 20px，然后 3px、1px」—— 还是起步一顿。
  //     实测缓动版：25px 分成 20/3/1 三段；匀速版每一帧都是 1~2px。
  //   ★ 为什么必须按时间算、不能按帧数算：手机 60fps、ProMotion 120fps、
  //     无头浏览器甚至 240fps，同一个"每帧走固定比例"在不同设备上速度差 4 倍。
  //     （这条是踩出来的：探针里量到帧间隔中位 4.2ms ≈ 240fps。）
  const programScroll = useCallback((el: HTMLDivElement, top: number) => {
    const max = Math.max(0, el.scrollHeight - el.clientHeight);
    const target = Math.max(0, Math.min(top, max));
    progTopRef.current = target;
    // 一屏以上的落差直接落位（见 JUMP_SCREENS 的注释）。
    // 必须先撤掉还在跑的动画：否则它下一帧读到新的 progTopRef 会从半路接着走。
    if (Math.abs(target - el.scrollTop) > el.clientHeight * JUMP_SCREENS) {
      if (scrollRafRef.current != null) {
        cancelAnimationFrame(scrollRafRef.current);
        scrollRafRef.current = null;
      }
      el.scrollTop = target;
      appliedTopRef.current = el.scrollTop;
      return;
    }
    // 已经在追赶：让循环自己读最新的 progTopRef，不要重排（重排会把
    // 走了一半的位移丢掉，反而更抖）
    if (scrollRafRef.current != null) return;

    let lastT = 0;
    const tick = (now: number) => {
      scrollRafRef.current = null;
      const goal = progTopRef.current;
      if (goal == null) return;
      // 追赶途中用户可能已经接管了（手指比 rAF 快），这时立刻让开
      if (!stickRef.current) return;
      // 首帧没有上一帧时间，按 16ms 估；切后台再回来 dt 可能上千毫秒，
      // 夹到 64ms 免得一下子跳过头
      const dt = lastT ? Math.min(now - lastT, 64) : 16;
      lastT = now;
      const cur = el.scrollTop;
      const diff = goal - cur;
      if (Math.abs(diff) <= 0.6) {
        el.scrollTop = goal;
        appliedTopRef.current = el.scrollTop;
        return;
      }
      // 速度 = 剩余量 / 固定时长；落差越大走得越快，但**全程匀速**。
      // 下限 0.02px/ms 只为避免极小落差拖太久。
      const speed = Math.max(0.02, Math.abs(diff) / SCROLL_DURATION_MS);
      const step = Math.sign(diff) * Math.min(Math.abs(diff), dt * speed);
      el.scrollTop = cur + step;
      // 记下"我们刚把它设成了多少"，onScroll 靠这个认领自己的位移。
      // 比时间窗可靠：手机上 rAF 慢、scroll 事件有延迟，时间窗经常开错。
      appliedTopRef.current = el.scrollTop;
      scrollRafRef.current = requestAnimationFrame(tick);
    };
    scrollRafRef.current = requestAnimationFrame(tick);
  }, []);

  // 直接落位：不播动画、不等下一帧（2026-11-18）。
  //
  // 和 programScroll 的分工：programScroll 回答「内容长了，视野怎么跟」，
  // 这里回答「换了一个视野」（进会话 / 切会话 / 从别的页面回来）。
  // 后者不能有动画 —— 落差几千像素时，任何"走完"的过程都是一次白光。
  // 顺手把 appliedTopRef 写上，onScroll 才不会把这一下当成用户接管。
  const settleScroll = useCallback((el: HTMLDivElement, top: number) => {
    const max = Math.max(0, el.scrollHeight - el.clientHeight);
    const target = Math.max(0, Math.min(top, max));
    if (scrollRafRef.current != null) {
      cancelAnimationFrame(scrollRafRef.current);
      scrollRafRef.current = null;
    }
    progTopRef.current = target;
    el.scrollTop = target;
    appliedTopRef.current = el.scrollTop;
  }, []);

  // 尾部留白：让「回答不足一屏」时也滚得到顶部（2026-11-02 重做版）
  //
  // 为什么必须有它：内容总高不足一屏时 maxScrollTop 太小，把回答顶边锚到视口顶
  // 会被浏览器 clamp 掉 —— 结果回答只能贴在视口最下方一字一字长出来，
  // 用户看到的就是"回答一直在屏幕最下面"。实测（390×844）：回答 121px 时
  // 顶边停在 y=505（视口 580），而不是应有的 y=75。
  //
  // ★ 为什么上一版会"一抽一抽"、这一版不会：
  //   上一版在渲染 effect 里每帧 `getBoundingClientRect()` 量一次气泡高度。
  //   DOM 还没更新时量到旧值或 0，tail 就瞬间跳几百像素（实测单次 517px）；
  //   tail 一改 scrollHeight，浏览器立刻把 scrollTop 夹回去 —— 这就是抽搐。
  //   这版改用 ResizeObserver：只在气泡**尺寸真的变了**之后才回调，量的是新值。
  //   于是「气泡高度 + 留白 = 一屏」恒成立，scrollHeight 恒定，scrollTop 不动。
  //
  //   效果：回答在下方"填满"这段留白，顶边稳稳停在视口顶部，一直到写满一屏
  //   才开始跟随 —— 正是豆包那种从上往下淌的观感。
  const lastMsg = messages[messages.length - 1];
  const lastId = lastMsg?.id ?? "";
  const lastStreaming = !!lastMsg?.streaming;
  useEffect(() => {
    const el = scrollRef.current;
    const tail = tailRef.current;
    if (!el || !tail) return;
    const node =
      lastStreaming && lastId
        ? el.querySelector<HTMLElement>(`[data-mid="${lastId}"]`)
        : null;
    if (!node) {
      tail.style.height = "0px";
      return;
    }
    const apply = () => {
      const bh = node.getBoundingClientRect().height;
      const h = Math.max(0, Math.round(el.clientHeight - bh));
      if (Math.abs((parseFloat(tail.style.height) || 0) - h) > 1) {
        tail.style.height = `${h}px`;
      }
    };
    apply();
    const ro = new ResizeObserver(apply);
    ro.observe(node);
    return () => ro.disconnect();
    // 只在「哪一条在流式」变化时重建，内容增长交给 ResizeObserver ——
    // 依赖 messages 会让每个 token 都重建一次 observer。
  }, [lastId, lastStreaming]);

  // 新消息 / 新一段文字进来时的视野策略（2026-11-01 重写）
  //
  // 改动前是每来一个字 `scrollTop = scrollHeight` —— 实测 131 个采样点里 130 个
  // 「距底 ≤2px」。1080×629 的窗口下可视区只有 350px，一条 953px 的回答从第一个字
  // 开始，顶边就在视口上方 185px：用户从头到尾只看得见最后一行。这不是流式坏了，
  // 是视野落点错了。
  //
  // 现在的策略（对齐豆包）：
  //   ① 一条回答的**第一个字**出现时，把这条气泡的顶边放到视口顶部（留 14px），
  //      而不是贴底 —— 贴底意味着第 1 行永远落在视口最下方，越写越往上跑。
  //      回答不足一屏时靠尾部留白（见上方 effect）补出滚动余量，同样能锚到顶。
  //   ② 锚完先停 ANCHOR_HOLD_MS，让开头在视口里待够，再转入跟随；
  //   ③ 跟随阶段让回答底边贴视口底，文字由 typewriter 按阅读速度往外放；
  //   ④ 用户一旦上滚（stickRef=false）就彻底冻结，视野归他。
  //
  // 空态（欢迎页）仍然跳过：欢迎页比可视区高，滚到底会把标题推出视口。
  useEffect(() => {
    const el = scrollRef.current;
    if (!el) return;
    if (messages.length === 0) {
      anchoredRef.current = null;
      anchoredPosRef.current = null;
      programScroll(el, 0);
      return;
    }
    if (!stickRef.current) return;

    const last = messages[messages.length - 1];
    // ★ 只有「正在流式」的那条才锚定（2026-11-02 第四次修正）。
    //   之前只看"有文字"，打开会话时会对**最后一条历史回答**也锚一次，
    //   scrollTop 从 0 直接甩到 25231 —— 用户看到的就是"一打开就跳到底部"。
    //   历史消息的落点由下面的"切会话回到底部"逻辑负责，不该走锚定。
    const hasText =
      last?.role === "assistant" && last.streaming && (last.content ?? "").length > 0;
    if (hasText && anchoredRef.current !== last.id) {
      const node = el.querySelector<HTMLElement>(`[data-mid="${last.id}"]`);
      if (node) {
        // ★ 标记必须放在"确认拿到节点"之后（2026-11-02）：
        //   原来先设 anchoredRef 再找节点，第一个 token 那一帧如果 DOM 还没挂上
        //   （querySelector 返回 null），这次锚定机会就**永久丢掉**了 ——
        //   后续每一帧都因为 id 相同而跳过锚定，回答只能贴在最底下长出来。
        anchoredRef.current = last.id;
        // ★ 先把留白**同步**补上，再算滚动范围（2026-11-02 关键修复）。
        //   留白平时由 ResizeObserver 异步设置，第一个 token 落地那一帧它还是 0，
        //   于是这一刻的 scrollHeight 少了一段，max 不够，锚定被 clamp ——
        //   实测回答顶停在 y=503（视口 580）而不是 y=76，看起来就是"贴着最底下写"。
        //   写 style 后立刻读 scrollHeight 会强制一次同步 layout，取到的就是新值。
        const tailEl = tailRef.current;
        if (tailEl) {
          const th = Math.max(
            0,
            Math.round(el.clientHeight - node.getBoundingClientRect().height)
          );
          tailEl.style.height = `${th}px`;
        }
        const rect = node.getBoundingClientRect();
        const elRect = el.getBoundingClientRect();
        const max = Math.max(0, el.scrollHeight - el.clientHeight);
        // ★ 用「相对当前位置的增量」而不是「绝对 scrollTop」（2026-11-02 第三次修正）。
        //   绝对值的算法依赖 rel 与 max 的精确对齐，tail 是异步写入的，
        //   差一截就被 clamp，实测偏移 428px（回答顶停在 504 而不是 76）。
        //   增量只关心"回答顶边现在在视口哪儿、要上移多少"，不受 scrollHeight 影响。
        const delta = rect.top - elRect.top - ANCHOR_GAP;
        const target = Math.max(0, Math.min(el.scrollTop + delta, max));
        if (typeof window !== "undefined") {
          (window as unknown as Record<string, unknown>).__anchorDbg = {
            rectTop: Math.round(rect.top),
            elTop: Math.round(elRect.top),
            delta: Math.round(delta),
            from: Math.round(el.scrollTop),
            to: Math.round(target),
            max,
            sh: el.scrollHeight,
            ch: el.clientHeight,
            tail: tailEl ? tailEl.style.height : "no-tail",
          };
        }
        // ★ 必须同步落地，不能排进 rAF：下一个 token 通常 16ms 内就到，
        //   进来又会调 programScroll 把排队的这一帧 cancel 掉 ——
        //   实测就是这样：锚定永远被取消，用户看到的仍是 -113px 的末尾。
        progTopRef.current = target;
        if (scrollRafRef.current != null) {
          cancelAnimationFrame(scrollRafRef.current);
          scrollRafRef.current = null;
        }
        el.scrollTop = target;
        // 同上：这一下也是我们自己设的，onScroll 必须认得，否则锚定刚落地的
        // scroll 事件会把 stick 关掉，后面每个字都不再跟随。
        appliedTopRef.current = el.scrollTop;
        anchoredPosRef.current = target;
        // 开头护住一会儿：内容长得比视线快，刚锚好就被下一帧顶走的话，
        // 用户连"这行是开头"都没看清。
        anchorUntilRef.current = performance.now() + ANCHOR_HOLD_MS;
        return;
      }
    }
    // 还没到跟随时间：让开头留在视口里
    if (performance.now() < anchorUntilRef.current) return;

    // 跟随：目标是让这条回答的**底边**贴住视口底部，而不是无脑滚到 scrollHeight。
    //
    // ★ 为什么不能用 scrollHeight：内容末尾还有父容器 padding，滚到 scrollHeight 等于
    //   比锚定位还往下多走十几像素 —— 实测锚定刚落地的 y=14，两个采样点后就变成
    //   -40，看着还是"从半截开始读"。改用"气泡底边对齐视口底"后，回答不足一屏时
    //   这个值小于锚定位，被 Math.max 挡住，开头就钉在视口顶部不动。
    const node = last ? el.querySelector<HTMLElement>(`[data-mid="${last.id}"]`) : null;
    if (node) {
      const box = node.getBoundingClientRect();
      const elBox = el.getBoundingClientRect();
      const bottom = box.bottom - elBox.top + el.scrollTop;
      const want = bottom - el.clientHeight + TAIL_PAD;
      const floor = anchoredPosRef.current ?? 0;
      programScroll(el, Math.max(floor, want));
      return;
    }
    programScroll(el, el.scrollHeight);
  }, [messages, programScroll]);

  // 切换会话（首条消息换了）时强制回到底部，否则会停在上一会话的滚动位置
  const firstId = messages[0]?.id ?? "";
  const prevFirstRef = useRef(firstId);
  useEffect(() => {
    if (firstId === prevFirstRef.current) return;
    prevFirstRef.current = firstId;
    stickRef.current = true;
    anchoredRef.current = null;
    anchoredPosRef.current = null;
    setAtBottom(true);
    const el = scrollRef.current;
    // ★ 2026-11-18：这里必须直接落位，不能走 programScroll。
    //   它是「从别的页面回到对话」时唯一会滚的一次 —— 历史从空到满，
    //   落差常常几千像素，交给 280ms 匀速动画就是用户说的"极强的滑动效果"。
    if (el) settleScroll(el, el.scrollHeight);
  }, [firstId, settleScroll]);

  // 内容**自己**长高之后继续贴底（2026-11-18）
  //
  // 上面那条 effect 只在「首条消息换了」那一刻落一次位，可那一刻的 scrollHeight
  // 并不是最终的：自托管字体是 swap 的，先用回退字体排一遍版，字体到位后整段重排。
  // 实测（390×844，线上 164 条的会话）：落位时 scrollHeight=79952、scrollTop=79319
  // 正好贴底；260ms 后 scrollHeight 变成 82405 —— scrollTop 一动不动，
  // 于是视野停在离末尾 1802px 的地方。用户的原话是「强制刷新后停在中间某条
  // 历史对话上」，看到的就是这几屏。
  //
  // 谁来收这个尾：ResizeObserver 盯内容容器（不是滚动容器 —— 后者的盒子尺寸
  // 不随内容变）。只在三种情况下按住不动：
  //   ① 用户自己上滚过（stickRef=false）→ 视野归他，不许拽回来；
  //   ② 还在流式 → 锚定/跟随那套有自己的节奏，这里插手会和它打架；
  //   ③ 空态欢迎页（没有 [data-mid]）→ 它比一屏高，拽到底会把标题顶出视口。
  // `data-streaming` 是 DOM 里"这一条正在流式"的唯一事实来源（见 chat/Bubble.tsx），
  // 用它而不是 React state：Observer 回调可能赶在 effect 之前跑，读 state 会拿到旧值。
  useEffect(() => {
    const el = scrollRef.current;
    const inner = el?.firstElementChild as HTMLElement | null;
    if (!el || !inner) return;
    const ro = new ResizeObserver(() => {
      if (!stickRef.current) return;
      if (!el.querySelector("[data-mid]")) return;
      if (el.querySelector('[data-streaming="true"]')) return;
      settleScroll(el, el.scrollHeight);
      // 贴回去了就把「回到最新」收掉：它只在 onScroll 里更新，而这一下是程序滚的
      // （onScroll 认领之后直接 return），不补这一句就会出现"已经在最底下，
      // 按钮还挂着说回到最新"—— 实测截图里就是这样。
      setAtBottom(true);
    });
    ro.observe(inner);
    return () => ro.disconnect();
  }, [settleScroll]);

  const onScroll = useCallback(() => {
    const el = scrollRef.current;
    if (!el) return;
    // ① 这就是我们上一帧刚设进去的值 —— 认领，直接返回。
    //   ★ 原来判的是「落点离目标 <= 4px」，但平滑追赶途中 scrollTop 离目标
    //     还有几十像素，判定必然失败 → 被当成"用户接管" → cancelAnimationFrame
    //     把正在跑的动画掐掉。手机上 rAF 慢，动画本来就跑不完，于是每次都是
    //     「挪一点 → 被掐 → 攒够再挪一点」，这就是底部那种一抽一抽。
    //     改成比对"我们设过的值"，和动画进行到哪一步无关。
    const applied = appliedTopRef.current;
    if (applied != null && Math.abs(el.scrollTop - applied) <= 2) return;

    // 平滑滚动途中（点「回到最新」）：朝目标靠近的过程不该算成"用户接管"，
    // 否则按钮会在中途闪一下又冒出来
    if (smoothUntilRef.current && performance.now() < smoothUntilRef.current) {
      const goal = progTopRef.current ?? 0;
      if (Math.abs(el.scrollTop - goal) <= 2) {
        smoothUntilRef.current = 0;
        progTopRef.current = null;
      }
      return;
    }

    // ② 落点和我们设的对不上 = 用户真的动了。把还排着的程序滚动撤掉，
    //    否则它会在 16ms 后把人按回原处（上滚 300px 被拽回去就是这么来的）。
    appliedTopRef.current = null;
    progTopRef.current = null;
    if (scrollRafRef.current != null) {
      cancelAnimationFrame(scrollRafRef.current);
      scrollRafRef.current = null;
    }
    const near = el.scrollHeight - el.scrollTop - el.clientHeight < 80;
    stickRef.current = near;
    setAtBottom((prev) => (prev === near ? prev : near));
  }, []);

  const scrollToBottom = useCallback(() => {
    const el = scrollRef.current;
    if (!el) return;
    stickRef.current = true;
    setAtBottom(true);
    const target = Math.max(0, el.scrollHeight - el.clientHeight);
    progTopRef.current = target;
    smoothUntilRef.current = performance.now() + 700;
    el.scrollTo({ top: target, behavior: "smooth" });
  }, []);

  // ---- 对话目录（跳回前面某一问）----
  // 只把「用户提问」当锚点：回答归到它上面那一问，和 DeepSeek 的目录一致。
  const turns = useMemo(
    () =>
      messages
        .filter((m) => m.role === "user")
        .map((m, i) => ({
          mid: m.id,
          n: i + 1,
          text: (m.content || "").replace(/\s+/g, " ").trim() || "（附件提问）",
        })),
    [messages]
  );
  // 刻度位置随内容变化，流式期间每来一批 token 都得重量（组件内防抖 120ms）
  const outlineKey = `${messages.length}:${messages[messages.length - 1]?.content?.length ?? 0}`;

  const jumpToTurn = useCallback((mid: string) => {
    const el = scrollRef.current;
    if (!el) return;
    const node = el.querySelector<HTMLElement>(`[data-mid="${mid}"]`);
    if (!node) return;
    const top = node.getBoundingClientRect().top - el.getBoundingClientRect().top + el.scrollTop;
    const target = Math.max(0, Math.min(top - ANCHOR_GAP, el.scrollHeight - el.clientHeight));
    // ★ 先把「跟随」关掉再滚：回答还在流式时，跟随逻辑每来一个字就会把视野拽回底部,
    //   不关的话用户刚跳上去立刻被拉下来 —— 这正是最容易回归的地方。
    stickRef.current = false;
    anchoredRef.current = null;
    anchorUntilRef.current = 0;
    if (scrollRafRef.current != null) {
      cancelAnimationFrame(scrollRafRef.current);
      scrollRafRef.current = null;
    }
    progTopRef.current = null;
    // 清掉「上一帧是我们设的」那条豁免，让 onScroll 按新位置重算 stick
    appliedTopRef.current = null;
    el.scrollTo({ top: target, behavior: "smooth" });
  }, []);

  const addFiles = (files: FileList | File[]) => {    const arr = Array.from(files);
    if (arr.length === 0) return;
    setPending((prev) => {
      const next = [...prev];
      for (const f of arr) {
        if (next.some((a) => a.name === f.name && a.size === f.size)) continue;
        next.push({
          id: aid(),
          name: f.name,
          type: f.type || "application/octet-stream",
          size: f.size,
          url: URL.createObjectURL(f),
          file: f,
        });
      }
      return next;
    });
  };

  const removeAttachment = (id: string) => {
    setPending((prev) => {
      const t = prev.find((a) => a.id === id);
      if (t) URL.revokeObjectURL(t.url);
      return prev.filter((a) => a.id !== id);
    });
  };

  const pushHistory = (q: string) => {
    if (!q) return;
    setHistory((prev) => {
      const next = [q, ...prev.filter((x) => x !== q)].slice(0, 50);
      try {
        localStorage.setItem("baomi.history", JSON.stringify(next));
      } catch {
        /* 存不下就不持久化，本次会话内仍可用 */
      }
      return next;
    });
  };

  // dir = -1 往上翻（更早/更新的一条），dir = 1 往下翻回草稿
  const recallHistory = (dir: -1 | 1) => {
    if (history.length === 0) return;
    let idx = histIdxRef.current;
    if (dir === -1) {
      if (idx === -1) {
        draftRef.current = input; // 第一次上翻，先把草稿留住
        idx = 0;
      } else if (idx < history.length - 1) {
        idx += 1;
      } else {
        return;
      }
    } else {
      if (idx <= -1) return;
      idx -= 1; // 回到 -1 即草稿
    }
    histIdxRef.current = idx;
    setInput(idx === -1 ? draftRef.current : history[idx]);
    // 回填后把光标放到末尾，否则长文本会停在开头
    requestAnimationFrame(() => {
      const el = inputRef.current;
      if (!el) return;
      el.setSelectionRange(el.value.length, el.value.length);
    });
  };

  const submit = () => {
    const q = input.trim();
    if ((!q && pending.length === 0) || sending) return;
    const atts = pending;
    setInput("");
    setPending([]);
    pushHistory(q);
    histIdxRef.current = -1;
    draftRef.current = "";
    // 自己发的内容一定要看到，重置为贴底跟随
    stickRef.current = true;
    setAtBottom(true);
    // 计划类请求：只传标志位，格式要求由后端在拼好对话历史之后注入。
    // （前端改写 question 文本会让当前轮丢上下文，并把格式块写进历史污染后续轮次。）
    onSend(q, atts, undefined, isPlanRequest(q));
  };

  const handleForward = useCallback((text: string) => {
    setInput(text);
    inputRef.current?.focus();
  }, []);

  // 用 useCallback 固定引用，否则每次渲染都会让 Bubble 的 memo 失效
  const handleCopyFail = useCallback(
    () => onNotice?.("error", "复制失败，请手动选择文本"),
    [onNotice]
  );
  // 赞踩落库：失败不影响界面（本地高亮已经点了），只提示一声让用户知道没存上
  const handleFeedback = useCallback(
    async (msgDbId: number, rating: "up" | "down", comment?: string) => {
      if (!sessionId) return;
      try {
        await api.sendFeedback(sessionId, msgDbId, rating, comment);
        onNotice?.(
          "success",
          rating === "up"
            ? "已记录：这条回答有帮助"
            : comment
              ? "已记录：谢谢你的补充，我会用来看板里复盘"
              : "已记录：这条回答不太行"
        );
      } catch {
        onNotice?.("error", "反馈没能保存，稍后可再点一次");
      }
    },
    [sessionId, onNotice]
  );
  // 从引用角标跳到全文预览：引用块只给文件名，kb 用当前会话绑定的那个
  const openPreviewFile = useCallback((source: string) => setPreviewFile(source), []);

  /**
   * 只有真会走检索的模式才提示"检索词会被怎么理解"。
   * llm 模式不检索、工具路径走工具调用，在它们下面提示换词是纯粹的噪音。
   * auto 目前按"有没有绑库"估：绑了库时后端会强制检索（含闲聊），
   * 没绑库只可能走工具或直接答，不会检索。判断口径见 core/router.py。
   */
  // 检索词校准面板只在「这一轮真的会检索」时出现：
  // 开了开关 + 会话确实绑了库。只判断开关不够 —— 没绑库时检索必然空，
  // 提前让用户校准检索词是空承诺。
  const willRetrieve = capValue.kb && !!boundKb;

  return (
    <section className="book-spine flex h-full min-w-0 flex-1 flex-col">
      {/* 顶栏。
          ★ 2026-11-14 第七批：左右内边距改走 --chat-px，和下面消息区、输入区
            同一条竖线。三处原来各自写 px-5 / px-6 / px-6，手机上标题比正文
            还靠外 1px，看着像两套栅格。 */}
      <div className="chat-px chat-topbar flex items-center gap-2 border-b border-line">
        {onOpenSidebar && (
          <button
            onClick={onOpenSidebar}
            title="打开会话列表"
            aria-label="打开会话列表"
            className="icon-btn hamburger -ml-1 shrink-0"
          >
            <svg viewBox="0 0 24 24" aria-hidden="true">
              <path d="M3 6h18M3 12h18M3 18h18" />
            </svg>
          </button>
        )}
        {/* 标题：图标 + 会话名（2026-11-18）。
            图标与「底栏 · 对话」和功能页页头是同一个图案（NavIcon 的 chat），
            合并外壳之后，从对话点到打卡再回来，左边那一竖列（图标位）
            不会忽有忽无。会话名本身可长可短，所以用 truncate 而不是放大字号 ——
            它替代不了功能页那种 28px 的版块标题，那是"这是哪一页"，
            这里回答的是"这是哪一段对话"。 */}
        <span className="chat-title min-w-0">
          <NavIcon name="chat" className="chat-title-ic" />
          <span className="chat-title-text">{sessionTitle ?? "新对话"}</span>
        </span>
        {boundKb ? (
          <span
            className="kb-chip min-w-0 max-w-[38vw] sm:max-w-[44vw]"
            title={kbNameMap?.[boundKb] ?? boundKb}
          >
            <span className="dot" />
            <span className="kb-chip-name min-w-0 truncate">
              已绑定：{kbNameMap?.[boundKb] ?? boundKb}
            </span>
            {onUnbindKb && (
              <button
                onClick={onUnbindKb}
                title="解绑资料库"
                aria-label="解绑资料库"
                className="kb-unbind ml-0.5 text-faint transition hover:text-red"
              >
                <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.4" strokeLinecap="round" className="h-3 w-3" aria-hidden="true">
                  <path d="M6 6l12 12M18 6L6 18" />
                </svg>
              </button>
            )}
          </span>
        ) : (kbCount ?? 0) > 0 && onToggleKbPanel ? (
          // P3：手上有资料库却没绑到本会话 —— 必须说出来，否则用户以为资料"丢了"
          // （线上复现：传过资料的库还在，模型却说当前会话没绑定）。
          // 一个库都没有时不提示：没东西可绑，提示只会变成噪音。
          <button
            type="button"
            onClick={onToggleKbPanel}
            className="kb-chip kb-chip-unbound min-w-0 max-w-[38vw] sm:max-w-[44vw]"
            title="当前会话未绑定资料库，点此从右侧选择"
            aria-label="当前会话未绑定资料库，点此选择"
          >
            <span className="kb-chip-name min-w-0 truncate">
              未绑定资料库 · 点此选择
            </span>
          </button>
        ) : null}
        <div className="flex-1" />
        {/* ★ 2026-11-18：「今天还能问 N 次」从对话区搬进设置页。
            用户的原话是「不应出现在对话框内，建议移至系统设置中」，
            而且它确实带来一处滑动干扰：额度是个会变的数字，胶囊宽度跟着变，
            顶栏右侧那几个按钮每刷新一次就平移一次。
            现在它住在 设置 → 今日额度（components/settings/QuotaCard.tsx），
            要看就去看，不在聊天时飘在眼前。 */}
        {/* 顶栏「能力」快捷弹层与它的触发按钮已在 2026-10-31 批 B 删除：
            它提供的是「切模式 + 预填示例」，而模式条已下架、能力由两枚开关表达。
            留着它等于教用户点一个已经不存在的概念（还带着"算数"这种已删工具）。 */}
        {onToggleKbPanel && (
          <button
            onClick={onToggleKbPanel}
            title={kbPanelOpen ? "收起资料库" : "展开资料库"}
            aria-label={kbPanelOpen ? "收起资料库" : "展开资料库"}
            aria-expanded={!!kbPanelOpen}
            className="icon-btn"
          >
            <svg viewBox="0 0 24 24" aria-hidden="true">
              {kbPanelOpen ? (
                <>
                  <path d="M9 18V5l12-2v13" />
                  <circle cx="6" cy="18" r="3" />
                  <circle cx="18" cy="16" r="3" />
                </>
              ) : (
                <>
                  <path d="M4 19.5A2.5 2.5 0 0 1 6.5 17H20" />
                  <path d="M6.5 2H20v20H6.5A2.5 2.5 0 0 1 4 19.5v-15A2.5 2.5 0 0 1 6.5 2z" />
                </>
              )}
            </svg>
          </button>
        )}
      </div>

      {/* 消息区 */}
      <div className="relative min-h-0 flex-1">
        {/* overflow-x-hidden 是兜底：一长串不可断的字符（文件名、URL、表格）
            只要把子元素顶宽，移动端整页就能横向拖动、观感像“画幅歪了”。
            宁可在这里裁掉，也不许把文档撑宽。

            [overflow-anchor:none] 关掉浏览器的「滚动锚定」：流式时内容每帧都在长，
            浏览器会自作主张微调 scrollTop 来保持可见位置，和我们自己的平滑滚动互相拉扯，
            也是手机端抖动的来源之一。 */}
        <div
          ref={scrollRef}
          onScroll={onScroll}
          className="chat-scroll h-full overflow-y-auto overflow-x-hidden [overflow-anchor:none]"
        >
          <div className="chat-measure chat-px chat-msgpad mx-auto flex min-h-full flex-col">
          {messages.length === 0 ? (
            // 欢迎页：主路径是「直接问」，首屏摆两块——
            // ① 功能入口（持续陪伴三卡 + 一次性动作小胶囊）② 三句示例
            // （场景快选已撤出主界面：场景化入口统一走模板广场，10-14 晚）
            <div className="welcome">
              {/* 首屏吉祥物：尺寸由 --hero-mark 决定（宽档 / 矮窗档各一档），
                  不再在这里写死 h-[52px] —— 写死了就和 welcome.css 的
                  两个高度档打架，改一处忘一处。 */}
              <MascotLogo
                className="hero-logo mx-auto mb-2"
                mood={messages.some((m) => m.streaming) ? "thinking" : "idle"}
                tiltKey={`${capValue.kb ? 1 : 0}${capValue.web ? 1 : 0}`}
              />
              <div className="eyebrow mb-1.5">苞米地 · 智能体工作台</div>
              <h1 className="hero-title font-serif font-bold leading-snug text-ink">
                {greeting}，我是<span className="hero-name">知穗</span>
              </h1>
              {/* 25 字在 390 宽下会折成两行、第二行只剩一个「你。」——
                  收到 14 字就单行放下了（390 - 48 padding = 342px，14×15=210px）。 */}
              <p className="welcome-sub mt-1.5 max-w-[30rem] text-msg leading-relaxed text-muted">
                一句话就行，我来判断怎么帮你
              </p>

              {/* 原来的「第一次来？三步就能用起来」引导条（OnboardBar）已删除：
                  它和首次进入的上手说明弹窗（GuideModal）讲的是同一件事，
                  新用户先看弹窗、关掉又看到一张三步卡，属于重复告知；
                  而老用户早就不需要它。删掉后 390×844 上首页不再需要滚动，
                  三张主线卡和输入框能同屏。 */}

              {/* 「今天」条：打卡 / 六级 / 委托收成一条，放在日更大卡上面。
                  没数据时组件自己返回 null（不占位）—— 所以从没建过计划的人
                  看到的首屏和改动前完全一致，不会多一条空卡。 */}
              <TodayStrip enabled={!!userId} onData={setTodayHasAny} />

              {/* 「每天提醒」的入口紧跟在今天条下面：今天条只在有事要做时出现，
                  而那正好就是推送有意义的人群（没任务可做的人，提醒内容是空的）。
                  今天条不出现时它也不出现，所以新用户首屏仍然干净。 */}
              {todayHasAny && <PushNudge enabled={!!userId} />}

              {/* ② 主操作区：两组、六项，全部是「真去一个地方」的入口。
                  ★ 2026-11-15 重排（用户要求）：撤掉原来那行四个小胶囊和三张示例卡，
                    主线从 3 项扩到 6 项，补上论坛 / 公开知识库 / 待办。
                  两组各 3 项是**排版前提**：三端都正好 3 列 × 2 行，没有空格子。
                  组二用 .is-soft 降一档（无投影、图标底衬换成中性色）——
                    「知穗替你做」和「你自己去翻」不该一样重。 */}
              {HOME_GROUPS.map((g, gi) => (
                <div
                  key={g.key}
                  className={`welcome-daily w-full ${gi === 0 ? "mt-4" : "mt-3.5 is-soft"}`}
                >
                  <div className="welcome-section-head">
                    <span className="eyebrow">{g.title}</span>
                    <span className="rule" />
                  </div>
                  <div className="mt-2 grid w-full grid-cols-3 gap-2">
                    {g.items.map((e) => (
                      <Link
                        key={e.href}
                        href={e.href}
                        className="entry-card"
                        aria-label={`${e.label}：${e.hint}`}
                      >
                        <span className="ec-icon">
                          <CornIcon name={e.icon} className="h-6 w-6" title={e.label} />
                        </span>
                        {/* 横排：图标在左、文字在右。label 与 hint 必须包成一列，
                            否则三个 span 会并排站成三栏（横排改造时踩过）。
                            ★ 手机（≤639）这一格改成竖排且隐去 hint —— 见 welcome.css 对应档。 */}
                        <span className="ec-text">
                          <span className="ec-label">{e.label}</span>
                          <span className="ec-hint">{e.hint}</span>
                        </span>
                      </Link>
                    ))}
                  </div>
                </div>
              ))}

              {/* ③ 继续上次：把「刚才做到哪儿了」放回首屏。
                  为什么在六格之后 —— 见 ResumeStrip 顶部注释（含 118px 的实测账）。
                  只在有历史对话时渲染，新用户看到的首屏与改动前一致。

                  ★ 有「今天」条时**不渲染**（2026-11-16 线上实测后加的闸）。
                    原因是算错了一次空间：本地测试号没有今天条，欢迎页 529px、
                    可用 537px，看着还有 118px 空白可以填；但真实老用户的欢迎页
                    有「今天」条（54）+ 提醒条（40）= 577px，本来就超出 40px ——
                    再加这 71px 会让它整块被输入区压住 34px（1388 线上实测：
                    visible:false / gapToDock:-34），要滑 52px 才看得见。
                    也就是说"空白"只对没今天条的人存在；对有今天条的人，
                    这块只会让页面多滑一截。填空白就该只填真的空着的地方。 */}
              {!todayHasAny && (
                <ResumeStrip
                  session={resumeSession}
                  onResume={(sid) => onResumeSession?.(sid)}
                />
              )}

              <p className="welcome-foot">问完的每一句，都能翻回原文。</p>
            </div>
          ) : (
            <div className="chat-msgs">
              {messages.map((m, idx) => {
                let userQ: string | undefined;
                if (m.role === "assistant") {
                  for (let i = idx - 1; i >= 0; i--) {
                    if (messages[i].role === "user") {
                      userQ = messages[i].content;
                      break;
                    }
                  }
                }
                return (
                  // 错误边界：一条坏消息渲染抛错时只降级这一条，不白屏整个会话
                  // data-mid：滚动锚定要按 id 找到这条气泡的顶边，没有它只能贴底
                  <div key={m.id} data-mid={m.id} className="min-w-0">
                    <BubbleErrorBoundary>
                      <Bubble
                        m={m}
                        userQuestion={userQ}
                        onForward={handleForward}
                        onCopyFail={handleCopyFail}
                        onFeedback={handleFeedback}
                        onRetry={onRetry}
                        onPreviewFile={boundKb ? openPreviewFile : undefined}
                        onDeleteTurn={onDeleteTurn}
                        onSediment={onSediment}
                        onKbSaved={onKbSaved}
                        onApproveTool={onApproveTool}
                      />
                    </BubbleErrorBoundary>
                  </div>
                );
              })}
              {/* 尾部留白：高度 = 一屏 − 本条回答高度，只在流式且不足一屏时给。
                  没有它，回答不足一屏就没有滚动余量，只能贴在视口最下方 ——
                  用户看到的就是"回答一直在屏幕最下面长出来"。 */}
              <div className="chat-tail" ref={tailRef} aria-hidden="true" />
            </div>
          )}
          </div>
        </div>
        {/* 对话目录：桌面走右侧页边刻度，手机走右下胶囊 + 半屏目录。
            放在滚动容器外面 —— 它要贴住视口，不能跟着内容滚走 */}
        <TurnOutline turns={turns} scrollRef={scrollRef} onJump={jumpToTurn} layoutKey={outlineKey} />
        {!atBottom && (
          <button
            type="button"
            onClick={scrollToBottom}
            className={messages.some((m) => m.streaming) ? "scroll-down is-live" : "scroll-down"}
            aria-label="回到最新消息"
          >
            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.8" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
              <path d="M12 5v14" />
              <path d="M19 12l-7 7-7-7" />
            </svg>
            {/* 还在生成时先说"正在生成"：用户上滚之后就冻结了，不告诉他有新内容
                长在下面，他会以为卡住了 */}
            <span>{messages.some((m) => m.streaming) ? "正在生成" : "回到最新"}</span>
          </button>
        )}
      </div>

      {/* 检索设置：只留「参考几段资料」。
          切片参数是建库时的事，已经移到右侧资料库面板按库单独设置 */}
      {showParams && (
        <div className="chat-measure chat-px mx-auto pb-2">
          <div className="fade-up rounded-xl border border-line-strong bg-panel p-4">
            <div className="flex items-baseline justify-between gap-2">
              <span className="text-sm font-medium text-ink">每次回答参考几段资料？</span>
              <button
                type="button"
                onClick={() => setAdvancedTopK((a) => !a)}
                aria-expanded={advancedTopK}
                className="shrink-0 text-xs text-faint transition hover:text-ink"
              >
                {advancedTopK ? "收起" : "自己填"}
              </button>
            </div>

            <div className="mt-2 grid grid-cols-3 gap-2" role="group" aria-label="参考资料段数">
              {TOP_K_MODES.map((m) => {
                const on = topK === m.value;
                return (
                  <button
                    key={m.value}
                    type="button"
                    onClick={() => onTopKChange(m.value)}
                    aria-pressed={on}
                    className={`flex flex-col items-center gap-px rounded-lg border py-2 transition ${
                      on
                        ? "border-accent bg-accent-soft"
                        : "border-line bg-bg hover:border-line-strong hover:bg-fill-2"
                    }`}
                  >
                    <span className="text-sm font-medium text-ink">{m.value} 段</span>
                    <span className="text-fs-badge text-faint">{m.hint}</span>
                  </button>
                );
              })}
            </div>

            <p className="mt-2 text-xs text-faint">
              参考得多，答得全但更慢；参考得少，答得快，但可能漏掉资料里的细节。
            </p>

            {advancedTopK && (
              <label className="mt-2 flex items-center gap-2 rounded-lg border border-line bg-fill-3 px-2 py-1.5">
                <span className="text-fs-badge text-muted">精确段数</span>
                <input
                  type="number"
                  min={1}
                  max={10}
                  value={topK}
                  onChange={(e) => {
                    const v = Number(e.target.value);
                    if (!Number.isNaN(v)) onTopKChange(v);
                  }}
                  className="underline-input w-16 py-0.5 text-xs"
                />
              </label>
            )}

            <p className="mt-2 border-t border-line pt-2 text-xs text-faint">
              资料怎么分段、切多细，在右侧「资料库」里按每个库单独设置。
            </p>
          </div>
        </div>
      )}

      {/* 底部：能力开关 + 反馈 / 工具集 + 输入框。
          ★ 内边距走 --chat-px / --chat-dock-pb：手机档的底部留白要叠 iOS
            安全区（home 指示条），写死 pb-5 的话输入框会被压在横条上。 */}
      <div className="chat-measure chat-px chat-dock mx-auto">
        {/* ★ gap 只留一档（8px）：四颗胶囊是同一权重的开关，原来桌面档是
            gap-2 组内 8 + sm:gap-3 组间 12，「检索·智能联网」与「反馈·工具集」
            两对之间的节奏不一致，同一行出现两种间距。2026-11-15 第 18 批去掉 sm:gap-3。 */}
        <div className="composer-bar chat-bar-gap flex flex-wrap items-center gap-2">
          {/* 2026-10-31 批 B：四档模式条下架，两枚能力开关常驻。
              原因：模式条把「检索 / 联网 / 走流程」混在一个字段里，用户选「检索」
              其实还想不想联网、允不允许调工具都说不清；后端新契约只有两个开关，
              与其做四档→两开关的翻译，不如直接让用户回答这两个问题。 */}
          <CapToggles value={capValue} onChange={onCapChange ?? (() => {})} />
          {/* 「反馈」和「工具集」编成一组（.composer-acts）：两颗都是"发消息前后
              顺手要做的一件事"，所以并排。工具集 11-07 从独占的那一行挪过来 ——
              之前它右对齐浮在一行空白上，跟下面这排按钮没有关系，看着像个孤儿标签。
              ★ 成组还有第二个原因：窄屏放不下时两颗**一起**折行，
              不会出现"反馈留在第一行、工具集掉到第二行"的散架样子。 */}
          <div className="composer-acts flex items-center gap-2">
            {/* 反馈：紧贴能力开关右侧，不塞回顶栏那排灰图标里。
                理由：想说话的那一刻人正在输入框这儿（刚被答错、刚发现按钮不好用），
                顶栏右上的小图标太不显眼，内测第一批人的意见最容易在这里丢掉。
                内容和设置页共用 FeedbackCard，只是装在弹窗里。 */}
            <button
              type="button"
              onClick={() => setFbOpen(true)}
              title="每条意见开发者都会看"
              aria-label="提交反馈"
              aria-haspopup="dialog"
              className="fb-mode-cta"
            >
              <span className="fb-mode-dot" aria-hidden="true" />
              {/* 只写「反馈」：原来 30px 宽的「内测反馈」在窄屏要缩成另一份文案，
                  现在两个宽度都放得下，就不必再留一份 .fb-mode-text-sm 的影子副本。 */}
              <span className="fb-mode-text">反馈</span>
            </button>
            {/* 工具集：GPA / 番茄钟 / 课程表 / 单词卡 / 倒计时 / 抽签，独立单页且免登录。
                title 里保留全名 —— 胶囊上只写「工具集」（和左边导航同一个名字），
                完整的「校园工具集」留给落地页和那一页自己的标题。
                ★ 图标和文字各包一层 span：360px 上四颗药丸并排放不下，要单独摘掉图标
                  （见 chat.css 的 ≤380 一档）。直接对 svg 写 display:none 不管用 ——
                  CornIcon 的 svg 自带内联 style="display:block"，内联样式优先于样式表，
                  这个坑 10-31 在「只留圆点」那版上踩过一次。 */}
            <a
              href={TOOLS_URL}
              target="_blank"
              rel="noopener noreferrer"
              className="tools-link"
              aria-label="工具集：GPA 计算、番茄钟、课程表（免登录，独立页，新开标签）"
              title="工具集：GPA 计算 · 番茄钟 · 课表……（免登录，独立页）"
            >
              <span className="tools-ico">
                <CornIcon name="tools" className="h-[15px] w-[15px]" />
              </span>
              <span className="tools-txt">工具集</span>
            </a>
          </div>
          <button
            onClick={() => setShowParams((s) => !s)}
            title="检索参数设置"
            aria-label="检索参数设置"
            aria-expanded={showParams}
            className={`gear ml-auto ${showParams ? "text-accent" : ""}`}
          >
            <svg viewBox="0 0 24 24" aria-hidden="true">
              <circle cx="12" cy="12" r="3" />
              <path d="M12 1v6M12 17v6M4.2 4.2l4.3 4.3M15.5 15.5l4.3 4.3M1 12h6M17 12h6M4.2 19.8l4.3-4.3M15.5 8.5l4.3-4.3" />
            </svg>
          </button>
        </div>

        {pending.length > 0 && (
          <div className="attach-strip">
            {pending.map((a) => (
              <div key={a.id} className="attach-item">
                {a.type.startsWith("image/") ? (
                  <img src={a.url} alt={a.name} />
                ) : (
                  <span className="attach-file-badge">
                    <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.7" strokeLinecap="round">
                      <path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z" />
                      <path d="M14 2v6h6" />
                      <path d="M8 13h8M8 17h5" />
                    </svg>
                  </span>
                )}
                <span className="max-w-[150px] truncate">{a.name}</span>
                <button
                  onClick={() => removeAttachment(a.id)}
                  title="移除附件"
                  aria-label={`移除附件：${a.name}`}
                  className="attach-rm"
                >
                  <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2.4" strokeLinecap="round" aria-hidden="true">
                    <path d="M6 6l12 12M18 6L6 18" />
                  </svg>
                </button>
              </div>
            ))}
            <p className="attach-note">
              <svg viewBox="0 0 24 24" aria-hidden="true">
                <circle cx="12" cy="12" r="9" />
                <path d="M12 16v-4M12 8h.01" />
              </svg>
              {pendingOtherCount > 0
                ? `仅图片会参与回答（${pendingImageCount} 张）；其余 ${pendingOtherCount} 个文件暂不支持解析`
                : `${pendingImageCount} 张图片将上传，由视觉模型结合问题一起分析`}
            </p>
          </div>
        )}

        {/* 手填城市的一行输入。定位拿不到时页面层直接把它展开 ——
            不弹「定位失败」，因为那是环境限制（http 下浏览器不给坐标 / 服务端没配 key），
            不是用户做错事，红字只会让人以为应用坏了。给出路比说原因有用。 */}
        {cityEditOpen ? (
          <form
            className="geo-edit"
            onSubmit={(e) => {
              e.preventDefault();
              const el = e.currentTarget.elements.namedItem("city") as HTMLInputElement | null;
              onSaveCity?.((el?.value || "").trim());
            }}
          >
            <label htmlFor="geo-city">你在哪个城市？</label>
            <input
              id="geo-city"
              name="city"
              defaultValue={(geoCity || "").split("·")[0].trim()}
              placeholder="例如 茂名 / 大理 / 北京"
              maxLength={20}
              autoComplete="off"
              autoFocus
            />
            <button type="submit" className="geo-edit-ok">
              用这个
            </button>
            <button
              type="button"
              className="geo-edit-cancel"
              onClick={() => onCityEditOpenChange?.(false)}
            >
              取消
            </button>
          </form>
        ) : (
          geoEnabled &&
          geoCity && (
            /* 角标只说地名（「茂名 · 茂南区」）。原来前面挂着「定位已开启，当前在」——
               定位开着这件事，左边那根定位针已经用金色实心说清楚了，再写一遍就是废话，
               而且把地名挤到窄屏第二行。地名拿不到时整块不出现（针仍是金色，状态没丢）。 */
            <div className="geo-badge" role="status" aria-live="polite">
              <svg viewBox="0 0 24 24" aria-hidden="true">
                <path d="M12 21s7-6.4 7-11a7 7 0 1 0-14 0c0 4.6 7 11 7 11z" />
                <circle cx="12" cy="10" r="2.6" />
              </svg>
              <span>
                {/* geoCity 由上层用 formatPlace() 拼成两级：「茂名 · 茂南区」 */}
                {geoCity}
              </span>
              {/* 屏幕上只剩地名，读屏仍要听得出这是什么 —— 补一句不可见的前缀。
                  必须放在地名 span **之后**：视觉上靠 clip 隐藏、不占位，
                  DOM 顺序上又不影响「第一个 span 就是地名」这条约定。 */}
              <span className="geo-sr">当前定位</span>
              {onCityEditOpenChange && (
                <button
                  type="button"
                  className="geo-badge-edit"
                  onClick={() => onCityEditOpenChange(true)}
                  title="定位不准？自己填一个城市"
                >
                  改
                </button>
              )}
            </div>
          )
        )}

        {/* 检索词校准（B5）：锚点高度 0，面板向上弹出，不推挤输入框 */}
        {willRetrieve && (
          <div className="qe-anchor">
            <QueryEnhance text={input} />
          </div>
        )}

        <div className="input-row">
          <button
            onClick={onToggleGeo}
            disabled={geoPending}
            title={
              geoPending
                ? "正在获取定位…"
                : geoEnabled
                  ? "定位已开启：发送时附带你的位置"
                  : "开启定位：问天气无需手输城市"
            }
            aria-label={geoPending ? "正在获取定位" : geoEnabled ? "关闭定位" : "开启定位"}
            aria-pressed={geoEnabled}
            aria-busy={geoPending}
            className={`geo-btn ${geoEnabled ? "on" : ""} ${geoPending ? "busy" : ""}`}
          >
            {/* 定位针：开启时填充实心，关闭时空心，与「+ 我的文件」同一套线条语言 */}
            <svg viewBox="0 0 24 24" aria-hidden="true">
              <path d="M12 21s7-6.4 7-11a7 7 0 1 0-14 0c0 4.6 7 11 7 11z" />
              <circle cx="12" cy="10" r="2.6" />
            </svg>
          </button>
          <button
            onClick={() => attachRef.current?.click()}
            title="上传附件（图片会由视觉模型分析）"
            aria-label="上传附件，图片会由视觉模型分析"
            className="attach"
          >
            {/* 加号：与「+ 新建对话 / + 我的文件」同一套进料语义，替代原回形针 */}
            <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="2" strokeLinecap="round" aria-hidden="true">
              <path d="M12 5v14M5 12h14" />
            </svg>
          </button>
          <input
            ref={attachRef}
            type="file"
            multiple
            // 后端只有视觉模型会消费附件，非图片格式上传了也不会参与回答，
            // 与其让用户选完才发现没用，不如在选择器层面就只放行图片
            accept="image/*"
            className="hidden"
            onChange={(e) => {
              const fs = e.target.files;
              if (fs && fs.length > 0) addFiles(fs);
              if (attachRef.current) attachRef.current.value = "";
            }}
          />
          <textarea
            ref={inputRef}
            value={input}
            onChange={(e) => setInput(e.target.value)}
            onPaste={(e) => {
              const items = e.clipboardData?.items;
              if (!items) return;
              const files: File[] = [];
              for (const it of Array.from(items)) {
                if (it.kind === "file") {
                  const f = it.getAsFile();
                  if (f) files.push(f);
                }
              }
              if (files.length > 0) {
                e.preventDefault();
                addFiles(files);
              }
            }}
            onKeyDown={(e) => {
              // 输入法组合期间的按键是"选候选词"，一律不拦
              if ((e.nativeEvent as KeyboardEvent).isComposing) return;
              const el = e.currentTarget;
              if (e.key === "Enter" && !e.shiftKey) {
                e.preventDefault();
                submit();
                return;
              }
              if (e.key === "Escape") {
                if (input) {
                  e.preventDefault();
                  histIdxRef.current = -1;
                  setInput("");
                } else if (pending.length > 0) {
                  e.preventDefault();
                  setPending((prev) => {
                    prev.forEach((a) => URL.revokeObjectURL(a.url));
                    return [];
                  });
                }
                return;
              }
              if (e.key === "ArrowUp" && !e.shiftKey) {
                // 光标在开头（或输入框是空的）才取历史，否则交给 textarea 正常移动光标
                if (input === "" || (el.selectionStart === 0 && el.selectionEnd === 0)) {
                  e.preventDefault();
                  recallHistory(-1);
                }
                return;
              }
              if (e.key === "ArrowDown" && !e.shiftKey) {
                if (el.selectionStart === input.length && el.selectionEnd === input.length) {
                  e.preventDefault();
                  recallHistory(1);
                }
              }
            }}
            rows={1}
            placeholder="随便问点什么…"
            aria-label="输入问题"
            className="composer-input max-h-40 flex-1 resize-none bg-transparent text-msg leading-relaxed text-text outline-none placeholder:text-faint"
          />
          {sending || playing ? (
            <button
              onClick={onStop}
              title={
                sending
                  ? "停止生成（截断当前输出，保留已生成内容）"
                  : "立即全部显示（不再逐字播放）"
              }
              aria-label={sending ? "停止生成，截断当前输出" : "立即全部显示"}
              className="send stop"
            >
              <svg viewBox="0 0 24 24" fill="currentColor" className="h-3.5 w-3.5" aria-hidden="true">
                <rect x="6" y="6" width="12" height="12" rx="2" />
              </svg>
            </button>
          ) : (
            <button
              onClick={submit}
              disabled={!input.trim() && pending.length === 0}
              title="发送"
              aria-label="发送"
              className="send"
            >
              <svg viewBox="0 0 24 24" aria-hidden="true">
                <path d="M12 19V5" />
                <path d="M5 12l7-7 7 7" />
              </svg>
            </button>
          )}
        </div>

        {/* 键盘提示从 placeholder 里挪出来：placeholder 要短，才像"随便问点什么" */}
        <div className="input-hint">
          <span className="truncate">{capHint}</span>
          {/* 生成中把快捷键提示换成截断提示：停止键只有生成/播放时才出现，
              不写一句"点右侧按钮截断"，用户很容易把它当成另一个发送键。 */}
          <span className="ml-1 shrink-0 whitespace-nowrap">
            {sending
              ? "生成中 · 点右侧按钮截断输出"
              : playing
                ? "仍在逐字显示 · 点右侧按钮立刻全显"
                : "Enter 发送 · ↑ 上一条 · Esc 清空"}
          </span>
        </div>
      </div>

      {previewFile && boundKb && (
        <FilePreviewModal
          kbId={boundKb}
          name={previewFile}
          onClose={() => setPreviewFile(null)}
        />
      )}

      {/* ★ 2026-11-18（合并外壳）：上手说明与更新公告不再挂在这里。
          对话页进了 (console) 路由组，两者由外壳统一挂载
          （components/console/ConsoleLayout.tsx）—— 两个渲染点会让弹窗
          有机会叠两次，而它们的"已读"标记是同一个 localStorage key，
          将来改成"每次更新都弹"就是真的两条。 */}

      {/* 顶栏「反馈」打开的弹窗：内容与设置页是同一个 FeedbackCard，
          区别只是这里没有外层卡片（chrome=false） */}
      <FeedbackModal open={fbOpen} onClose={closeFeedback} page="/" />
    </section>
  );
}

"use client";

// 用户反馈卡片（设置页用）。形态对齐 DeepSeek Web：**几个分类按钮 + 一段话**，
// 不搞冗长的表单 —— 用户提意见的耐心只有十几秒，字段越多越没人填。
//
// 三个刻意的决定：
//
// 1. **分类按钮的选项来自后端**（`/api/user-feedback/dict`），不写死在前端。
//    前端硬编码一份、后端校验另一份，加一个分类要改两处，
//    而这类不一致的表现是"按钮能点、提交 400"。
//
// 2. **提交后立刻显示"我提过的"**，带处理状态。
//    用户看不到回音就不会提第二次；这也是"反馈有没有人管"的唯一证据。
//
// 3. **不把内容塞进 URL / 不打日志**：反馈可能含个人信息，只走 POST body。
import { useCallback, useEffect, useState } from "react";
import { api } from "@/lib/api";
import type { FeedbackDict, UserFeedbackItem } from "@/lib/types";
import { Seg } from "./console/ui";

const STATUS_CLASS: Record<string, string> = {
  open: "warn",
  doing: "info",
  done: "ok",
  closed: "",
};

function fmtTime(ts: number): string {
  if (!ts) return "";
  const d = new Date(ts * 1000);
  const p = (n: number) => String(n).padStart(2, "0");
  return `${d.getFullYear()}-${p(d.getMonth() + 1)}-${p(d.getDate())} ${p(d.getHours())}:${p(d.getMinutes())}`;
}

export default function FeedbackCard({
  page,
  chrome = true,
}: {
  page: string;
  /** false = 不带外层卡片与标题，供弹窗内嵌用。
   *  弹窗自己已经有标题栏，再套一层「告诉我们哪里不对」就成了标题套标题。 */
  chrome?: boolean;
}) {
  const [dict, setDict] = useState<FeedbackDict | null>(null);
  const [category, setCategory] = useState("bug");
  const [content, setContent] = useState("");
  const [contact, setContact] = useState("");
  const [showContact, setShowContact] = useState(false);
  const [busy, setBusy] = useState(false);
  const [msg, setMsg] = useState<{ kind: "ok" | "err"; text: string } | null>(null);
  const [mine, setMine] = useState<UserFeedbackItem[]>([]);

  const loadMine = useCallback(() => {
    // 取 5 条而不是 3 条：开发者回复可能落在稍早的那一条上，
    // 列表太短会让"他回我了"这件事用户根本看不到，整个回复功能就白做了。
    api
      .myFeedback(5, 0)
      .then((r) => setMine(r.items))
      .catch(() => {
        /* 拉不到历史不影响提交 */
      });
  }, []);

  useEffect(() => {
    // 字典拿不到就退回一个最小可用集合：至少不能让用户连按钮都看不到。
    // （后端 4xx/5xx 时这里会走 catch，而不是把整张卡片留白）
    api
      .feedbackDict()
      .then((d) => setDict(d))
      .catch(() => {
        setDict({
          categories: [
            { value: "bug", label: "出错了" },
            { value: "answer", label: "回答不满意" },
            { value: "feature", label: "功能建议" },
            { value: "other", label: "其他" },
          ],
          statuses: [],
          transitions: {},
          limits: {
            min_content: 5,
            max_content: 2000,
            max_contact: 120,
            max_page: 120,
            min_reply: 1,
            max_reply: 1000,
          },
        });
      });
    loadMine();
  }, [loadMine]);

  const min = dict?.limits.min_content ?? 5;
  const max = dict?.limits.max_content ?? 2000;
  const tooShort = content.trim().length > 0 && content.trim().length < min;

  const submit = useCallback(async () => {
    const text = content.trim();
    if (text.length < min) {
      setMsg({ kind: "err", text: `内容至少 ${min} 个字` });
      return;
    }
    setBusy(true);
    setMsg(null);
    try {
      await api.submitFeedback({
        category,
        content: text,
        contact: contact.trim(),
        page,
      });
      setContent("");
      setContact("");
      setMsg({ kind: "ok", text: "已收到，谢谢你。处理进度和开发者回复会显示在下面。" });
      loadMine();
    } catch (e) {
      setMsg({ kind: "err", text: e instanceof Error ? e.message : "提交失败，请稍后再试" });
    } finally {
      setBusy(false);
    }
  }, [category, contact, content, loadMine, max, min, page]);

  const options = (dict?.categories ?? []).map((c) => ({ value: c.value, label: c.label }));

  const inner = (
    <>
      <div style={{ marginTop: 10 }}>
        <Seg
          ariaLabel="反馈分类"
          options={options.length ? options : [{ value: "bug", label: "出错了" }]}
          value={category}
          onChange={setCategory}
          stretch
        />
      </div>

      <div className="field" style={{ marginTop: 12 }}>
        <span className="f">具体说明</span>
        <textarea
          value={content}
          onChange={(e) => setContent(e.target.value.slice(0, max))}
          rows={4}
          placeholder="尽量说清「你在哪一步、点了什么、期望什么、实际发生了什么」——越具体越好定位。"
          style={{ width: "100%", resize: "vertical" }}
        />
        <p className="hint" style={{ marginTop: 4 }}>
          {content.trim().length} / {max}
          {tooShort ? `（至少 ${min} 个字）` : ""}
        </p>
      </div>

      {showContact ? (
        <div className="field">
          <span className="f">联系方式（可选）</span>
          <input
            value={contact}
            onChange={(e) => setContact(e.target.value.slice(0, dict?.limits.max_contact ?? 120))}
            placeholder="邮箱 / 微信，只有开发者能看到"
          />
        </div>
      ) : (
        <button
          type="button"
          className="btn btn-ghost btn-sm"
          style={{ marginTop: 2 }}
          onClick={() => setShowContact(true)}
        >
          想被回访？留个联系方式
        </button>
      )}

      {msg ? (
        <p
          className="hint"
          style={{ marginTop: 10, color: msg.kind === "err" ? "var(--red-ink)" : "var(--success-ink)" }}
        >
          {msg.text}
        </p>
      ) : null}

      <div className="row" style={{ justifyContent: "flex-end", marginTop: 12 }}>
        <button
          type="button"
          className="btn btn-primary btn-sm"
          disabled={busy || content.trim().length < min}
          onClick={() => void submit()}
        >
          {busy ? "提交中…" : "提交"}
        </button>
      </div>

      {mine.length > 0 ? (
        <>
          <div className="divide" />
          <p className="sec-label" style={{ marginBottom: 6 }}>
            我提过的
          </p>
          {mine.map((it) => (
            <div key={it.id} style={{ padding: "5px 0" }}>
              <div className="run" style={{ gridTemplateColumns: "1fr auto auto" }}>
                <span
                  style={{
                    minWidth: 0,
                    overflow: "hidden",
                    textOverflow: "ellipsis",
                    whiteSpace: "nowrap",
                  }}
                >
                  {it.content}
                </span>
                <span className="meta">{fmtTime(it.created_at)}</span>
                <span className={`ctag ${STATUS_CLASS[it.status] ?? ""}`}>{it.status_label}</span>
              </div>
              {/* 开发者回复：这是用户判断"我提的有没有人管"的唯一凭据，
                  所以给它比"状态标签"更显眼的位置，而不是再塞进一行小字。
                  多条 = 不同管理员先后跟进的，按时间排，每条署上回复人的名字
                  （用户明确要求看得到是谁回的）。 */}
              {(it.replies ?? []).length > 0
                ? (it.replies ?? []).map((r) => (
                    <div className="fb-reply" key={r.id}>
                      <div className="fb-reply-head">
                        {r.admin_name || "管理员"} 回复
                        {r.created_at ? ` · ${fmtTime(r.created_at)}` : ""}
                      </div>
                      <div className="fb-reply-body">{r.content}</div>
                    </div>
                  ))
                : null}
            </div>
          ))}
        </>
      ) : null}
    </>
  );

  // 弹窗里不套卡片：卡片边距 + 标题栏会和弹窗自己的外壳重复
  if (!chrome) return <div className="fb-bare">{inner}</div>;

  return (
    <div className="card card-pad">
      <div className="card-head">
        <span className="card-title">告诉我们哪里不对</span>
      </div>
      {inner}
    </div>
  );
}

"use client";

// 右侧资料库面板：标题 + 导入按钮 + 知识库列表
// 视觉：暖米黄书本风格 · 大圆角 · 柔阴影 · 金色点缀
import { useRef, useState, type RefObject } from "react";
import Link from "next/link";
import type { KbInfo, PublicKbInfo, SearchResult, FavoriteKbInfo } from "@/lib/types";
import {
  CHUNK_PROFILES,
  DEFAULT_PROFILE_ID,
  describeParams,
  getProfile,
  profileParams,
  type ChunkParams,
  type ChunkProfileId,
} from "@/lib/chunkProfiles";
import FilePreviewModal, { shortName } from "./FilePreviewModal";
import CornIcon from "./CornIcon";
import { fmtWhen } from "@/lib/time";

const MAX_UPLOAD_MB = 100;

/** 面板里「处理方式」的选择结果：三档之一，或用户改过数字后的自定义 */
type ReadMode = ChunkProfileId | "custom";

/**
 * 处理方式选择器。
 *
 * 之前这里直接写着「分段 500 字 / 重叠 50 字」——那是 RAG 的实现细节，
 * 用户既不知道 500 字是几段话，也不知道调大调小会怎样。
 * 现在默认只给三个能凭直觉选的档位，原始数字收进「高级设置」。
 */
function ReadModePicker({
  value,
  onPick,
  advanced,
  onToggleAdvanced,
  size,
  overlap,
  onSizeChange,
  onOverlapChange,
}: {
  value: ReadMode;
  onPick: (id: ChunkProfileId) => void;
  advanced: boolean;
  onToggleAdvanced: () => void;
  size: number;
  overlap: number;
  onSizeChange: (v: number) => void;
  onOverlapChange: (v: number) => void;
}) {
  // 高级设置里要显示「当前档位对应的数字」——选了完整就该看到 1000/100，
  // 而不是永远显示全局兜底值；改数字即刻转成自定义档
  const prof = getProfile(value);

  const hint =
    value === "custom"
      ? `自定义：每段约 ${size} 字，相邻两段重叠 ${overlap} 字`
      : `${prof.examples}，${prof.benefit}`;

  return (
    <div className="mt-0.5">
      <div className="flex items-baseline justify-between gap-2">
        <span className="text-fs-xs text-muted">这份资料想怎么读？</span>
        <button
          type="button"
          onClick={onToggleAdvanced}
          aria-expanded={advanced}
          className="shrink-0 text-fs-xs text-faint transition hover:text-ink"
        >
          {advanced ? "收起" : "高级设置"}
        </button>
      </div>

      <div className="mt-1.5 grid grid-cols-3 gap-1.5" role="group" aria-label="资料处理方式">
        {CHUNK_PROFILES.map((p) => {
          const on = value === p.id;
          return (
            <button
              key={p.id}
              type="button"
              onClick={() => onPick(p.id)}
              aria-pressed={on}
              title={`${p.examples}（每段约 ${p.size} 字）`}
              className={`flex flex-col items-center gap-px rounded-lg border py-1.5 transition ${
                on
                  ? "border-accent bg-accent-soft"
                  : "border-line bg-bg hover:border-line-strong hover:bg-fill-2"
              }`}
            >
              <span className="text-fs-xs font-medium text-ink">{p.label}</span>
              <span className="text-fs-badge text-faint">{p.short}</span>
            </button>
          );
        })}
      </div>

      <p className="mt-1.5 text-fs-xs text-faint">{hint}</p>

      {advanced && (
        <div className="mt-2 rounded-lg border border-line bg-fill-3 p-2">
          <div className="grid grid-cols-2 gap-2">
            <label className="flex flex-col">
              <span className="text-fs-badge text-muted">每段字数</span>
              <input
                type="number"
                min={100}
                max={2000}
                value={size}
                onChange={(e) => {
                  const v = Number(e.target.value);
                  if (!Number.isNaN(v)) onSizeChange(v);
                }}
                className="underline-input mt-0.5 py-1 text-fs-xs"
              />
            </label>
            <label className="flex flex-col">
              <span className="text-fs-badge text-muted">重叠字数</span>
              <input
                type="number"
                min={0}
                max={500}
                value={overlap}
                onChange={(e) => {
                  const v = Number(e.target.value);
                  if (!Number.isNaN(v)) onOverlapChange(v);
                }}
                className="underline-input mt-0.5 py-1 text-fs-xs"
              />
            </label>
          </div>
          <p className="mt-1 text-fs-badge text-faint">
            相邻两段共享的字数，防止一句话正好被切在中间。不清楚就保持默认
          </p>
        </div>
      )}
    </div>
  );
}

interface Props {
  kbs: KbInfo[];
  /** 全站公开库（别人的，只读检索源）。不传/为空就不渲染这个分组 */
  publicKbs?: PublicKbInfo[];
  /**
   * 我收藏的公开库。默认收起全站公开库、只把这组摆出来 ——
   * 用户原话："一开始不要在这设置所有全站公开库，不是每个用户都需要全部"。
   */
  favKbs?: FavoriteKbInfo[];
  /** 收藏 / 取消收藏（星标点了要立刻亮，乐观更新在 hook 里做） */
  onToggleFavorite?: (kbId: string, on: boolean) => void;
  boundKb: string | null;
  onUpload: (kbId: string, files: File[], size?: number, overlap?: number) => Promise<void>;
  onSearch: (keyword: string) => Promise<SearchResult[]>;
  /** 联网建库：逐条抓并回调进度，完成后由页面层自动绑定 + 预填问题 */
  onWebImport: (
    kbName: string,
    urls: string[],
    onProgress: (i: number, total: number, title: string) => void,
    params?: ChunkParams
  ) => Promise<string>;
  onDeleteKb: (kbId: string) => void;
  /** 删除库内单个文件（只清它的片段） */
  onDeleteFile?: (kbId: string, name: string) => void;
  /** 按这个库自己的处理方式重新整理整库 */
  onRebuildKb?: (kbId: string) => void;
  /** 该库上次用的处理方式（浏览器本地），用于列表标签与重新整理 */
  kbChunkOf?: (kbId: string) => ChunkParams;
  onBind: (kbId: string | null) => void;
  chunkSize: number;
  chunkOverlap: number;
  onCollapse?: () => void;
  /** 中屏及以下作为浮层抽屉渲染 */
  overlay?: boolean;
  /** 抽屉是否展开（仅 overlay 时有意义） */
  open?: boolean;
  /** 抽屉容器引用，用于打开时接管焦点 */
  containerRef?: RefObject<HTMLElement | null>;
  /** 首屏还在拉资料库列表 */
  loading?: boolean;
  /**
   * 当前会话。给「从对话里收几条」用 —— 有这个才做得到「不先选会话、直接看候选」。
   * 为空时弹层第一步会退化成让用户自己挑一段对话。
   */
  sid?: string | null;
  /**
   * 打开沉淀弹层。
   *
   * 弹层本身搬到了页面层：用户消息下的「存进资料库」也要开它，而且进来时
   * 得带上那条消息的 id 才能自动勾选。面板若能自己开一个，就会出现两个实例、
   * 两套勾选状态 —— 同一件事在两处各记一份，迟早对不上。
   */
  onOpenSediment?: () => void;
}

export default function KnowledgePanel({
  kbs,
  publicKbs,
  favKbs,
  onToggleFavorite,
  boundKb,
  onUpload,
  onSearch,
  onWebImport,
  onDeleteKb,
  onDeleteFile,
  onRebuildKb,
  kbChunkOf,
  onBind,
  chunkSize,
  chunkOverlap,
  onCollapse,
  overlay = false,
  open = false,
  containerRef,
  loading = false,
  sid = null,
  onOpenSediment,
}: Props) {
  const [feed, setFeed] = useState<"upload" | "web" | null>(null);
  const [uploadKb, setUploadKb] = useState("");
  const [keyword, setKeyword] = useState("");
  const [results, setResults] = useState<SearchResult[]>([]);
  const [selected, setSelected] = useState<Set<string>>(new Set());
  const [importKb, setImportKb] = useState("");
  const [busy, setBusy] = useState(false);
  // 联网建库逐条抓取时的进度：「正在抓第 3/10 篇」
  const [importProgress, setImportProgress] = useState<{ i: number; total: number; title: string } | null>(null);
  const [selectedFiles, setSelectedFiles] = useState<File[]>([]);
  const [uploadError, setUploadError] = useState<string | null>(null);
  const [netError, setNetError] = useState<string | null>(null);
  // 删除资料库会连带丢掉它的全部片段，先确认再删
  const [confirmDelId, setConfirmDelId] = useState<string | null>(null);
  // 展开哪个库的文件清单
  const [expandedKb, setExpandedKb] = useState<string | null>(null);
  /** 全站公开库那一组默认收起：铺开会把用户自己的库挤到看不见 */
  const [pubOpen, setPubOpen] = useState(false);
  // 待确认删除的单个文件，格式 `${kb_id}::${name}`
  const [confirmFile, setConfirmFile] = useState<string | null>(null);
  // 正在预览的文件（kb_id + 原始文件名 + 片段数）
  const [preview, setPreview] = useState<{
    kbId: string;
    name: string;
    chunks: number | null;
  } | null>(null);
  const fileRef = useRef<HTMLInputElement>(null);

  // 这份资料的「处理方式」：默认均衡；用户改过数字才转成自定义
  const [readMode, setReadMode] = useState<ReadMode>(DEFAULT_PROFILE_ID);
  const [customSize, setCustomSize] = useState<number | null>(null);
  const [customOverlap, setCustomOverlap] = useState<number | null>(null);
  const [advanced, setAdvanced] = useState(false);
  // 刚建好的库名：给一句「接下来怎么用」。很多用户卡在建完之后不知道下一步
  const [justBuilt, setJustBuilt] = useState<string | null>(null);

  // 当前生效的参数：自定义档用输入框的值，其余按档位查表
  const effSize = customSize ?? chunkSize;
  const effOverlap = customOverlap ?? chunkOverlap;
  const activeParams: ChunkParams =
    readMode === "custom"
      ? { size: effSize, overlap: effOverlap }
      : profileParams(readMode);

  const pickReadMode = (id: ChunkProfileId) => setReadMode(id);
  const changeSize = (v: number) => {
    setCustomSize(v);
    setReadMode("custom");
  };
  const changeOverlap = (v: number) => {
    setCustomOverlap(v);
    setReadMode("custom");
  };

  /** 库里上次用的处理方式；没记录过（老库）就用面板当前这套 */
  const chunkOf = (kbId: string): ChunkParams => kbChunkOf?.(kbId) ?? activeParams;

  const fmtSize = (bytes: number) => {
    if (bytes < 1024 * 1024) return `${(bytes / 1024).toFixed(1)} KB`;
    return `${(bytes / 1024 / 1024).toFixed(1)} MB`;
  };

  const toggle = (href: string) => {
    const next = new Set(selected);
    if (next.has(href)) next.delete(href);
    else next.add(href);
    setSelected(next);
  };

  const doSearch = async () => {
    if (!keyword.trim()) return;
    setBusy(true);
    setNetError(null);
    try {
      const r = await onSearch(keyword.trim());
      setResults(r);
      setSelected(new Set());
    } catch (e) {
      setNetError(e instanceof Error ? e.message : "搜索失败，请稍后重试");
    } finally {
      setBusy(false);
    }
  };

  const doImport = async () => {
    if (!importKb.trim() || selected.size === 0) return;
    setBusy(true);
    setNetError(null);
    try {
      const urls = Array.from(selected);
      await onWebImport(
        importKb.trim(),
        urls,
        (i, total, title) => {
          setImportProgress({ i, total, title });
        },
        activeParams
      );
      setImportProgress(null);
      setJustBuilt(importKb.trim());
      setResults([]);
      setSelected(new Set());
      setImportKb("");
    } catch (e) {
      setNetError(e instanceof Error ? e.message : "导入失败，请稍后重试");
    } finally {
      setBusy(false);
    }
  };

  const onFileChange = (files: FileList | null) => {
    if (!files || files.length === 0) return;
    setUploadError(null);
    const arr = Array.from(files);
    const oversized = arr.find((f) => f.size > MAX_UPLOAD_MB * 1024 * 1024);
    if (oversized) {
      setUploadError(
        `「${oversized.name}」超过 ${MAX_UPLOAD_MB}MB 限制（${fmtSize(oversized.size)}）`
      );
      return;
    }
    setSelectedFiles(arr);
    if (uploadKb.trim()) {
      doUpload(arr);
    }
  };

  const doUpload = async (files?: File[]) => {
    const list = files ?? selectedFiles;
    if (list.length === 0 || !uploadKb.trim()) return;
    setBusy(true);
    setUploadError(null);
    try {
      await onUpload(uploadKb.trim(), list, activeParams.size, activeParams.overlap);
      setSelectedFiles([]);
      setJustBuilt(uploadKb.trim());
      if (fileRef.current) fileRef.current.value = "";
    } catch (e) {
      const msg = e instanceof Error ? e.message : "上传失败";
      setUploadError(msg);
    } finally {
      setBusy(false);
    }
  };

  return (
    <aside
      ref={containerRef}
      tabIndex={-1}
      className={`side-right flex h-full shrink-0 flex-col px-4 py-5 ${open ? "open" : ""}`}
      aria-label="资料库"
      aria-busy={loading}
      inert={!open}
    >
      {/* 头部 */}
      <div className="flex items-center justify-between">
        <h2 className="flex items-baseline gap-2.5">
          <span className="font-serif text-fs-xl font-bold text-ink">资料库</span>
          <span className="h-px w-6 bg-line-strong" />
        </h2>
        <div className="flex items-center gap-1">
          {/* 这块面板管的是「当前对话用哪个库」，改名/删库/看每个库装了什么
              都太挤（190px 宽）。这些事挪到了独立页 /knowledge，
              这里只留一个入口，别让「找资料」和「管资料」在同一个 190px 里抢位置。 */}
          <Link
            href="/knowledge"
            className="kb-manage"
            title="在独立页面里管理所有资料库"
          >
            管理
          </Link>
          {onCollapse && (
            <button
              onClick={onCollapse}
              title="收起资料库"
              aria-label="收起资料库"
              className="icon-btn"
            >
              <svg viewBox="0 0 24 24" aria-hidden="true">
                <path d="m15 18-6-6 6-6" />
              </svg>
            </button>
          )}
        </div>
      </div>

      {/* 两种进料入口：我上传 / 它去搜 —— 主路径「直接问」在左侧对话区。
          ★ 原来是 grid-cols-2。R3 把字号抬到 14px 后，「网上的资料」在 80px 宽的
            格子里折成「网上的资 / 料」，最后一个字孤零零挂在第二行，加上图标
            还对不齐。侧栏只有 190px，两列永远是紧的；改成整行排，
            字号再大一档也不会散架。 */}
      <div className="mt-4 grid grid-cols-1 gap-2">
        <button
          onClick={() => setFeed(feed === "upload" ? null : "upload")}
          className={`feed-btn ${feed === "upload" ? "on" : ""}`}
          aria-expanded={feed === "upload"}
        >
          <span className="inline-flex items-center justify-center gap-1.5">
            <CornIcon name="plus" className="h-3.5 w-3.5" />
            我的文件
          </span>
        </button>
        <button
          onClick={() => setFeed(feed === "web" ? null : "web")}
          className={`feed-btn ${feed === "web" ? "on" : ""}`}
          aria-expanded={feed === "web"}
        >
          <span className="inline-flex items-center justify-center gap-1.5">
            <CornIcon name="plus" className="h-3.5 w-3.5" />
            网上的资料
          </span>
        </button>
        {/* 第三个入料口：从对话里挑几句话。跟上面两个并列，因为用户在这一栏
            的心智就是「往库里加东西」，加在这里不用教他另找地方。
            它不是 toggle —— 点了直接开弹层，所以没有 on 态。
            图标沿用「+」而不是 notes：这里三个都是"加内容"的动作，
            换一个形近的图标反而像另一种东西。 */}
        <button
          onClick={() => onOpenSediment?.()}
          className="feed-btn"
          aria-haspopup="dialog"
        >
          <span className="inline-flex items-center justify-center gap-1.5">
            <CornIcon name="plus" className="h-3.5 w-3.5" />
            对话里的内容
          </span>
        </button>
      </div>

      {/* 已有资料库名候选：导入框 input[list] 关联，避免手打名字和已有库差一点就新建同名库 */}
      <datalist id="kbNameList">
        {kbs.filter((k) => k.name).map((k) => (
          <option key={k.kb_id} value={k.name as string} />
        ))}
      </datalist>

      {/* 进料①：上传文档 */}
      {feed === "upload" && (
        <div className="fade-up mt-3 flex flex-col gap-2.5">
          {/* 上传文档 */}
          <div className="rounded-xl border border-line-strong bg-panel p-4">
            <h3 className="eyebrow">我的文件</h3>
            <div className="mt-2 flex flex-col gap-2">
              <input
                value={uploadKb}
                onChange={(e) => setUploadKb(e.target.value)}
                placeholder="资料库名称，如「高数上册」"
                aria-label="资料库名称"
                list="kbNameList"
                className="underline-input py-1.5 text-sm"
              />

              <ReadModePicker
                value={readMode}
                onPick={pickReadMode}
                advanced={advanced}
                onToggleAdvanced={() => setAdvanced((a) => !a)}
                size={activeParams.size}
                overlap={activeParams.overlap}
                onSizeChange={changeSize}
                onOverlapChange={changeOverlap}
              />

              <input
                ref={fileRef}
                type="file"
                multiple
                accept=".txt,.md,.pdf"
                onChange={(e) => onFileChange(e.target.files)}
                className="hidden"
              />
              <button
                type="button"
                onClick={() => fileRef.current?.click()}
                disabled={busy}
                className="flex flex-col items-center justify-center gap-1.5 rounded-xl border border-dashed border-line-strong bg-bg py-5 text-center transition hover:bg-fill-2 disabled:opacity-50"
              >
                <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round" className="h-7 w-7 text-muted">
                  <path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4" />
                  <polyline points="17 8 12 3 7 8" />
                  <line x1="12" y1="3" x2="12" y2="15" />
                </svg>
                <span className="text-sm font-medium text-ink">
                  {busy ? "上传中…" : "点击选择文件"}
                </span>
                <span className="text-fs-xs text-faint">支持 TXT / Markdown / PDF，可多选</span>
              </button>

              {selectedFiles.length > 0 && (
                <div className="flex flex-col gap-1">
                  {selectedFiles.map((f, i) => (
                    <div key={i} className="flex items-center gap-1.5 rounded-lg border border-line bg-bg px-2 py-1.5 text-xs text-muted">
                      <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round" className="h-3 w-3 shrink-0 text-ink">
                        <path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z" />
                        <path d="M14 2v6h6" />
                      </svg>
                      <span className="truncate flex-1">{f.name}</span>
                      <span className="text-faint">{fmtSize(f.size)}</span>
                    </div>
                  ))}
                  {uploadError && (
                    <p className="rounded-lg border border-line-strong bg-red/5 px-2 py-1 text-fs-xs text-red-ink">
                      {uploadError}
                    </p>
                  )}
                  {!uploadKb.trim() && !uploadError && (
                    <p className="text-fs-xs text-muted">请先填写资料库名称后自动上传</p>
                  )}
                  {uploadKb.trim() && selectedFiles.length > 0 && !busy && (
                    <button
                      onClick={() => doUpload()}
                      className="btn-import mt-1 w-full py-1.5 text-xs"
                    >
                      上传到「{uploadKb}」
                    </button>
                  )}
                </div>
              )}
            </div>
          </div>
        </div>
      )}

        {/* 进料②：联网搜索导入（带逐条进度） */}
        {feed === "web" && (
          <div className="fade-up mt-3 flex flex-col gap-2.5">
            <div className="rounded-xl border border-line-strong bg-panel p-4">
              <h3 className="eyebrow">网上的资料</h3>
            <div className="mt-2 flex gap-2">
              <input
                value={keyword}
                onChange={(e) => setKeyword(e.target.value)}
                onKeyDown={(e) => e.key === "Enter" && doSearch()}
                placeholder="搜索关键词"
                aria-label="联网搜索关键词"
                className="underline-input min-w-0 flex-1 py-1.5 text-sm"
              />
              <button
                className="btn-import px-3 py-1 text-sm"
                onClick={doSearch}
                disabled={busy}
              >
                搜索
              </button>
            </div>

            <div className="mt-2 flex gap-2">
              <input
                value={importKb}
                onChange={(e) => setImportKb(e.target.value)}
                placeholder="导入到哪个资料库？"
                aria-label="导入到资料库名称"
                list="kbNameList"
                className="underline-input min-w-0 flex-1 py-1.5 text-sm"
              />
              <button
                className="btn-import px-3 py-1 text-sm"
                onClick={doImport}
                disabled={busy || selected.size === 0 || !importKb.trim()}
              >
                {importProgress ? `抓取中 ${importProgress.i}/${importProgress.total}` : `导入 ${selected.size} 条`}
              </button>
            </div>

            <ReadModePicker
              value={readMode}
              onPick={pickReadMode}
              advanced={advanced}
              onToggleAdvanced={() => setAdvanced((a) => !a)}
              size={effSize}
              overlap={effOverlap}
              onSizeChange={changeSize}
              onOverlapChange={changeOverlap}
            />

            {/* 逐条抓取进度：等待时间也是一次低成本的二次交互窗口 */}
            {importProgress && (
              <div className="mt-3 rounded-lg border border-line-strong bg-bg p-2.5">
                <div className="import-progress-bar">
                  <span style={{ width: `${(importProgress.i / importProgress.total) * 100}%` }} />
                </div>
                <p className="mt-1.5 text-fs-xs text-muted">
                  正在抓第 {importProgress.i}/{importProgress.total} 篇
                  {importProgress.title ? `：${importProgress.title}` : ""}
                </p>
              </div>
            )}

            {netError && (
              <p className="mt-2 rounded-lg border border-line-strong bg-red/5 px-2 py-1 text-fs-xs text-red-ink">
                {netError}
              </p>
            )}

            {results.length > 0 && (
              <ul className="mt-3 max-h-56 space-y-1 overflow-y-auto rounded-lg border border-line-strong bg-bg p-1.5 pr-1">
                {results.map((r) => (
                  <li
                    key={r.href}
                    className="flex items-start gap-1 rounded-lg px-1.5 py-1.5 text-sm last:border-b-0 hover:bg-fill-2"
                  >
                    <label className="flex min-w-0 flex-1 cursor-pointer items-start gap-2">
                      <input
                        type="checkbox"
                        checked={selected.has(r.href)}
                        onChange={() => toggle(r.href)}
                        className="mt-0.5 rounded accent-accent"
                      />
                      <div className="min-w-0">
                        <div className="truncate font-medium text-text">{r.title}</div>
                        <div className="line-clamp-2 text-xs text-muted">{r.body}</div>
                      </div>
                    </label>
                    <a
                      href={r.href}
                      target="_blank"
                      rel="noopener noreferrer"
                      title="跳转到官方网页"
                      className="icon-btn mt-0.5 h-7 w-7 shrink-0 justify-center rounded-lg border border-line"
                    >
                      <svg viewBox="0 0 24 24">
                        <path d="M18 13v6a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2V8a2 2 0 0 1 2-2h6" />
                        <polyline points="15 3 21 3 21 9" />
                        <line x1="10" y1="14" x2="21" y2="3" />
                      </svg>
                    </a>
                    <a
                      href={`/api/kb/download?url=${encodeURIComponent(r.href)}`}
                      download
                      title="下载到本机"
                      className="icon-btn mt-0.5 h-7 w-7 shrink-0 justify-center rounded-lg border border-line"
                    >
                      <svg viewBox="0 0 24 24">
                        <path d="M21 15v4a2 2 0 0 1-2 2H5a2 2 0 0 1-2-2v-4" />
                        <polyline points="7 10 12 15 17 10" />
                        <line x1="12" y1="15" x2="12" y2="3" />
                      </svg>
                    </a>
                  </li>
                ))}
              </ul>
            )}
          </div>
        </div>
      )}

      {/* 建完库后的下一步：不少用户卡在「建好了，然后呢」 */}
      {justBuilt && (
        <div className="fade-up mt-3 flex items-start gap-2 rounded-xl border border-line bg-accent-soft px-3 py-2.5">
          <span className="mt-0.5 shrink-0 text-accent-ink">
            <CornIcon name="info" className="h-4 w-4" />
          </span>
          <p className="min-w-0 flex-1 text-fs-xs text-ink">
            「{justBuilt}」已就绪，并已设为当前资料库。回到对话框直接问里面的内容就行。
          </p>
          <button
            type="button"
            onClick={() => setJustBuilt(null)}
            aria-label="知道了"
            title="知道了"
            className="shrink-0 text-faint transition hover:text-ink"
          >
            <CornIcon name="close" className="h-3.5 w-3.5" />
          </button>
        </div>
      )}

      {/* 知识库列表 */}
      <div className="mt-3 flex-1 overflow-y-auto pr-1">
        {loading ? (
          <div className="flex flex-col gap-2 px-1 pt-1" aria-hidden="true">
            {[0, 1, 2].map((i) => (
              <div key={i} className="skel-block">
                <span className="skel-line" />
                <span className="skel-line short" />
              </div>
            ))}
          </div>
        ) : kbs.length === 0 ? (
          <div className="px-3 py-8 text-center">
            {/* 玉米线描插画：呼应「苞米地笔记本」的暖金氛围 */}
            <div className="kb-empty-illus" aria-hidden="true">
              <svg viewBox="0 0 80 80">
                {/* 玉米棒 */}
                <path d="M40 14 C29 18 25 30 27 45 C29 56 34 62 40 62 C46 62 51 56 53 45 C55 30 51 18 40 14Z" />
                {/* 颗粒：横向弧线 */}
                <path d="M31 25 C36 23 44 23 49 25" />
                <path d="M29 34 C35 32 45 32 51 34" />
                <path d="M29 43 C35 41 45 41 51 43" />
                <path d="M31 52 C36 50 44 50 49 52" />
                {/* 颗粒：纵向线 */}
                <path d="M40 15 V61" />
                <path d="M34 17 V59" />
                <path d="M46 17 V59" />
                {/* 顶须 */}
                <path d="M40 14 C39 9 36 6 33 5" />
                <path d="M40 14 C41 8 44 5 47 4" />
                <path d="M40 14 C43 10 46 8 50 8" />
                {/* 底部叶片 */}
                <path d="M38 61 C32 64 28 70 28 75 C34 73 38 68 38 61Z" />
                <path d="M42 61 C48 64 52 70 52 75 C46 73 42 68 42 61Z" />
              </svg>
            </div>
            <p className="font-serif text-sm font-medium text-ink">还没有资料库</p>
            <div className="mt-4 space-y-2 text-left">
              <div className="flex items-start gap-2.5">
                <span className="flex h-5 w-5 shrink-0 items-center justify-center rounded-full bg-[var(--accent-tint)] text-fs-badge font-bold text-[var(--text-1)]">1</span>
                <p className="text-xs text-muted">点上方「我的文件」或「网上的资料」开始建库</p>
              </div>
              <div className="flex items-start gap-2.5">
                <span className="flex h-5 w-5 shrink-0 items-center justify-center rounded-full bg-[var(--accent-tint)] text-fs-badge font-bold text-[var(--text-1)]">2</span>
                <p className="text-xs text-muted">勾选资料库左侧的勾选框绑定到当前对话</p>
              </div>
              <div className="flex items-start gap-2.5">
                <span className="flex h-5 w-5 shrink-0 items-center justify-center rounded-full bg-[var(--accent-tint)] text-fs-badge font-bold text-[var(--text-1)]">3</span>
                <p className="text-xs text-muted">回到左侧对话区开始提问</p>
              </div>
            </div>
          </div>
        ) : (
          <div className="flex flex-col">
            {kbs.map((k) => {
              const bound = boundKb === k.kb_id;
              const files = k.files ?? [];
              const expanded = expandedKb === k.kb_id;
              // 这个库用的处理方式（「均衡」/「自定义 800/80」）
              const cp = chunkOf(k.kb_id);
              const cpLabel = describeParams(cp.size, cp.overlap);
              return (
                <div
                  key={k.kb_id}
                  className={`kb-row group ${bound ? "bound" : ""}`}
                >
                  <button
                    title={bound ? "取消绑定" : "绑定到当前对话"}
                    aria-label={bound ? `取消绑定资料库：${k.name || k.kb_id}` : `绑定资料库到当前对话：${k.name || k.kb_id}`}
                    aria-pressed={bound}
                    onClick={() => onBind(bound ? null : k.kb_id)}
                    className={`check ${bound ? "on" : ""}`}
                  >
                    <svg viewBox="0 0 24 24" aria-hidden="true">
                      <path d="M20 6L9 17l-5-5" />
                    </svg>
                  </button>
                  <div className="min-w-0 flex-1">
                    <div className="kb-name">{k.name || k.kb_id}</div>
                    <div className="kb-meta">
                      <span className="tag">{files.length} 文件</span>
                      <span className="tag">{k.chunks} 片段</span>
                      <span className="tag" title={`每段约 ${cp.size} 字，相邻重叠 ${cp.overlap} 字`}>
                        {cpLabel}
                      </span>
                      {k.public && <span className="tag pub">公开</span>}
                      {files.length > 0 && (
                        <button
                          type="button"
                          className="kb-manage"
                          aria-expanded={expanded}
                          onClick={() => setExpandedKb(expanded ? null : k.kb_id)}
                        >
                          {expanded ? "收起" : "管理文件"}
                        </button>
                      )}
                    </div>

                    {expanded && files.length > 0 && (
                      <ul className="kb-files">
                        {files.map((f) => {
                          const key = `${k.kb_id}::${f.name}`;
                          return (
                            <li key={f.name} className="kb-file">
                              <svg viewBox="0 0 24 24" fill="none" stroke="currentColor" strokeWidth="1.6" strokeLinecap="round" strokeLinejoin="round" aria-hidden="true">
                                <path d="M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8z" />
                                <path d="M14 2v6h6" />
                              </svg>
                              <button
                                type="button"
                                className="kb-file-name"
                                title={`预览全文：${shortName(f.name)}`}
                                onClick={() =>
                                  setPreview({ kbId: k.kb_id, name: f.name, chunks: f.chunks })
                                }
                              >
                                {shortName(f.name)}
                              </button>
                              <span className="kb-file-meta">{f.chunks ?? "—"} 片段</span>
                              {f.origin === "web" && <span className="tag web">网上</span>}
                              {f.origin === "upload" && <span className="tag up">上传</span>}
                              {confirmFile === key ? (
                                <span
                                  className="kb-file-confirm"
                                  onKeyDown={(e) => {
                                    if (e.key === "Escape") setConfirmFile(null);
                                  }}
                                >
                                  <button
                                    title="确认删除这个文件"
                                    aria-label={`确认删除文件：${f.name}`}
                                    className="kb-del confirm"
                                    onClick={() => {
                                      onDeleteFile?.(k.kb_id, f.name);
                                      setConfirmFile(null);
                                    }}
                                  >
                                    <svg viewBox="0 0 24 24" aria-hidden="true">
                                      <path d="M20 6L9 17l-5-5" />
                                    </svg>
                                  </button>
                                  <button
                                    autoFocus
                                    title="取消"
                                    aria-label="取消删除"
                                    className="kb-del"
                                    onClick={() => setConfirmFile(null)}
                                  >
                                    <svg viewBox="0 0 24 24" aria-hidden="true">
                                      <path d="M6 6l12 12M18 6L6 18" />
                                    </svg>
                                  </button>
                                </span>
                              ) : (
                                <button
                                  title="从库里删除这个文件"
                                  aria-label={`删除文件：${f.name}`}
                                  className="kb-del"
                                  onClick={() => setConfirmFile(key)}
                                >
                                  <svg viewBox="0 0 24 24" aria-hidden="true">
                                    <path d="M3 6h18M8 6V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2M19 6l-1 14a2 2 0 0 1-2 2H8a2 2 0 0 1-2-2L5 6" />
                                  </svg>
                                </button>
                              )}
                            </li>
                          );
                        })}
                        {onRebuildKb && (
                          <li className="kb-file-foot">
                            {/* 2026-11-13：tooltip 里原来写「会用当前处理方式重新向量化」，
                                「向量化」是内部实现。用户按下这颗键要知道的是
                                "会重算一遍、之前的问题可能对不上"，不是灌向量库。 */}
                            <button
                              type="button"
                              className="kb-rebuild"
                              title={`按「${cpLabel}」把库里全部资料重新切一遍（会重新算一遍，之前问过的回答可能对不上新切法）`}
                              onClick={() => onRebuildKb(k.kb_id)}
                            >
                              按「{cpLabel}」重新整理
                            </button>
                          </li>
                        )}
                      </ul>
                    )}
                  </div>
                  {confirmDelId === k.kb_id ? (
                    <span
                      className="flex shrink-0 items-center gap-1"
                      onKeyDown={(e) => {
                        if (e.key === "Escape") setConfirmDelId(null);
                      }}
                    >
                      <button
                        title="确认删除"
                        aria-label={`确认删除资料库：${k.name || k.kb_id}`}
                        className="kb-del confirm"
                        onClick={() => {
                          onDeleteKb(k.kb_id);
                          setConfirmDelId(null);
                        }}
                      >
                        <svg viewBox="0 0 24 24" aria-hidden="true">
                          <path d="M20 6L9 17l-5-5" />
                        </svg>
                      </button>
                      <button
                        autoFocus
                        title="取消"
                        aria-label="取消删除"
                        className="kb-del"
                        onClick={() => setConfirmDelId(null)}
                      >
                        <svg viewBox="0 0 24 24" aria-hidden="true">
                          <path d="M6 6l12 12M18 6L6 18" />
                        </svg>
                      </button>
                    </span>
                  ) : (
                    <button
                      title="删除资料库"
                      aria-label={`删除资料库：${k.name || k.kb_id}`}
                      className="kb-del"
                      onClick={() => setConfirmDelId(k.kb_id)}
                    >
                      <svg viewBox="0 0 24 24" aria-hidden="true">
                        <path d="M3 6h18M8 6V4a2 2 0 0 1 2-2h4a2 2 0 0 1 2 2v2M19 6l-1 14a2 2 0 0 1-2 2H8a2 2 0 0 1-2-2L5 6" />
                      </svg>
                    </button>
                  )}
                </div>
              );
            })}
          </div>
        )}

        {/* 我的收藏库：用户自己挑的公开库。
            放在全站公开库**之前**，因为这一组才是他日常要挂的；
            全站那一组默认折叠 —— 十几个课程库一铺开，自己的库就被挤到看不见。 */}
        {favKbs && favKbs.length > 0 && (
          <div className="mt-3">
            <p className="kb-pub-head">
              我的收藏库
              <span className="kb-pub-n">{favKbs.length}</span>
            </p>
            <div className="flex flex-col">
              {favKbs.map((k) => {
                const bound = boundKb === k.kb_id;
                return (
                  <div key={k.kb_id} className={`kb-row group ${bound ? "bound" : ""}`}>
                    <button
                      type="button"
                      title={bound ? "取消绑定" : "绑定到当前对话"}
                      aria-label={
                        bound
                          ? `取消绑定收藏库：${k.name}`
                          : `绑定收藏库到当前对话：${k.name}`
                      }
                      aria-pressed={bound}
                      onClick={() => onBind(bound ? null : k.kb_id)}
                      className={`check ${bound ? "on" : ""}`}
                    >
                      <svg viewBox="0 0 24 24" aria-hidden="true">
                        <path d="M20 6L9 17l-5-5" />
                      </svg>
                    </button>
                    <div className="min-w-0 flex-1">
                      <div className="kb-name">{k.name || k.kb_id}</div>
                      <div className="kb-meta">
                        {/* 来源与作者：官方库由后端拼成「官方课程库」，同学的是「某某 的库」 */}
                        <span className="kb-src">来源{k.source}</span>
                        <span className="tag">{k.chunks} 片段</span>
                        {k.at > 0 && <span className="tag">{fmtWhen(k.at)}</span>}
                      </div>
                    </div>
                    <button
                      type="button"
                      className="kb-fav on"
                      aria-pressed
                      title="取消收藏"
                      aria-label={`取消收藏：${k.name}`}
                      onClick={() => onToggleFavorite?.(k.kb_id, false)}
                    >
                      <CornIcon name="star" className="h-3.5 w-3.5" />
                      {(k.favs ?? 0) > 0 && <span className="lib-fav-n">{k.favs}</span>}
                    </button>
                  </div>
                );
              })}
            </div>
          </div>
        )}

        {/* 全站公开库：别人的库，只读检索源。没有文件清单、没有删除，
            与上面的私有库分组并列而不是混在一起——归属不同，能做的事也不同。

            ★ 默认收起（2026-11-13 用户要求）：站里已经有 9 门官方课程 + 同学分享，
              全铺开会把右栏顶满，用户自己那几个库要滚半天才看得见。
              收起后只留一行「共 N 个」，想挑就去广场；挑中了才会进"我的收藏库"。 */}
        {publicKbs && publicKbs.length > 0 && (
          <div className="mt-3">
            <button
              type="button"
              className="kb-pub-head kb-pub-toggle"
              aria-expanded={pubOpen}
              onClick={() => setPubOpen((v) => !v)}
            >
              全站公开库
              <span className="kb-pub-n">{publicKbs.length}</span>
              <CornIcon name="arrow" className="kb-pub-chev" />
            </button>
            {pubOpen && (
              <>
                <div className="flex flex-col">
                  {publicKbs.map((k) => {
                    const bound = boundKb === k.kb_id;
                    return (
                      <div key={k.kb_id} className={`kb-row group ${bound ? "bound" : ""}`}>
                        <button
                          type="button"
                          title={bound ? "取消绑定" : "绑定到当前对话"}
                          aria-label={
                            bound
                              ? `取消绑定公开知识库：${k.name || k.kb_id}`
                              : `绑定公开知识库到当前对话：${k.name || k.kb_id}`
                          }
                          aria-pressed={bound}
                          onClick={() => onBind(bound ? null : k.kb_id)}
                          className={`check ${bound ? "on" : ""}`}
                        >
                          <svg viewBox="0 0 24 24" aria-hidden="true">
                            <path d="M20 6L9 17l-5-5" />
                          </svg>
                        </button>
                        <div className="min-w-0 flex-1">
                          <div className="kb-name">{k.name || k.kb_id}</div>
                          <div className="kb-meta">
                            <span className="tag">{k.chunks} 片段</span>
                            <span className="tag pub">公开</span>
                          </div>
                        </div>
                        <button
                          type="button"
                          className={"kb-fav" + (k.favorited ? " on" : "")}
                          aria-pressed={!!k.favorited}
                          title={k.favorited ? "取消收藏" : "收藏，之后在「我的收藏库」里找得到"}
                          aria-label={`${k.favorited ? "取消收藏" : "收藏"}：${k.name || k.kb_id}`}
                          onClick={() => onToggleFavorite?.(k.kb_id, !k.favorited)}
                        >
                          <CornIcon name="star" className="h-3.5 w-3.5" />
                          {(k.favs ?? 0) > 0 && <span className="lib-fav-n">{k.favs}</span>}
                        </button>
                      </div>
                    );
                  })}
                </div>
                <p className="mt-1.5 px-1 text-fs-xs text-faint">
                  别人的公开库：能挂进对话检索，但看不到文件清单，也不能修改。
                </p>
              </>
            )}
          </div>
        )}
      </div>

      {preview && (
        <FilePreviewModal
          kbId={preview.kbId}
          name={preview.name}
          chunks={preview.chunks}
          onClose={() => setPreview(null)}
        />
      )}
    </aside>
  );
}

