source:
"use client";

/**
 * 语音输入。两条路，一条是流式（边说边出字），一条是一句话识别（说完才有字）。
 *
 * ## 为什么两条都留着
 *
 * 流式要腾讯云的 APPID，一句话识别只要 SecretId/SecretKey。少配一个东西就
 * 让整个语音功能消失，是最差的设计；所以流式是**增强**，它挂掉（没配 APPID、
 * 握手失败、浏览器不支持 WS）就悄悄退回一句话识别 —— 用户感觉到的差别只是
 * "字不是边说边出来"，功能本身还在。
 *
 * 降级发生在**会话中途**也能用：录制期间一直在累积 PCM（60 秒约 3.8MB），
 * 所以 WebSocket 建不起来时，同一段音频可以直接走一次性上传，用户不用重说。
 *
 * ## 为什么不用 MediaRecorder
 *
 * MediaRecorder 在 Chrome 上输出 `audio/webm;codecs=opus`，腾讯云不认这个容器
 * （一句话识别要 wav/pcm/mp3/m4a/aac；流式要 pcm/opus/speex…）。
 * 两条路都要 PCM，所以统一用 Web Audio 采，不碰 MediaRecorder。
 *
 * ## 流式的音频格式是**裸 PCM**
 *
 * `voice_format=1` 意味着每包都是纯 16bit 采样，没有 WAV 头。WAV 头只对
 * "整段文件"有意义，流式下每 200ms 一包，塞头反而要上游按容器去解析。
 */

import { useCallback, useEffect, useRef, useState } from "react";

import { api } from "@/lib/api";

const TARGET_RATE = 16000;
const MAX_SECONDS = 60;
/** 每包 200ms。16k × 2 字节 × 0.2s = 6400 字节，正是腾讯云建议的节奏 */
const CHUNK_BYTES = 6400;
const CHUNK_SAMPLES = CHUNK_BYTES / 2;
/** 说完了等上游吐完尾包的上限。超过就用手上已有的文本收尾 */
const FINISH_TIMEOUT_MS = 8000;

export type VoicePhase = "idle" | "recording" | "finishing" | "transcribing";

/** 后端 `api/capture.py` 定义的帧，一一对应。前端不碰腾讯云的 `slice_type`。 */
export type StreamFrame =
  | { type: "ready" }
  | { type: "partial"; text: string }
  | { type: "segment"; text: string }
  | { type: "done"; text: string }
  | { type: "error"; message: string; retryable?: boolean };

type Callbacks = {
  /** 一次性模式的整段结果 */
  onText: (text: string) => void;
  onError: (message: string) => void;
  /** 流式模式的每一帧。只有 `streaming=true` 时才会被调用 */
  onFrame?: (frame: StreamFrame) => void;
  /** 走不走流式，由 `/api/capture/capabilities` 的 `stream` 决定 */
  streaming?: boolean;
};

type Session = {
  ctx: AudioContext;
  stream: MediaStream;
  source: MediaStreamAudioSourceNode;
  proc: ScriptProcessorNode;
  /** 一次性模式要整段；流式也留着，用于 WS 失败时就地降级 */
  chunks: Float32Array[];
  rate: number;
  timer: number;
  ws: WebSocket | null;
  wsOpen: boolean;
  /** 攒包用：凑满 CHUNK_SAMPLES 就发一包 */
  acc: Int16Array;
  accLen: number;
  resampler: StreamResampler | null;
  finishTimer: number;
};

/**
 * 峰值归一化：把整段录音的最大振幅拉到 `target`，最多放大 `maxGain` 倍。
 *
 * ## 为什么需要
 *
 * 识别引擎吃的是 16bit PCM。手机麦克风在正常握持距离下峰值常常只有 0.05-0.15，
 * 也就是只用掉了 16 位里的 12 位左右 —— 声母（s/sh/x/j/q/zh/ch）的能量本来就只有
 * 韵母的几分之一，再被量化掉一截，转写就会成片地"听成别的字"。
 * 把峰值顶到 0.85 等于免费多出 3-4 bit 的有效精度。
 *
 * ## 为什么只有一次性模式用
 *
 * 归一化要"知道整段的最大值"，只有录完才算得出来。流式下的对应物是采集时的
 * AGC（`autoGainControl: true`）—— 那是同一件事的实时版本，已经开了。
 * 在流式里再叠一层自适应增益就是双重放大，字间会忽大忽小，反而更难认。
 *
 * ## 为什么有下限
 *
 * 峰值低于 `MIN_PEAK` 说明大概率是"点了麦克风没说话"，此时放大只是把底噪
 * 喂给识别引擎，反而更容易凭空识别出一句话。宁可原样上传，让它返回空。
 */
const MIN_PEAK = 0.02;

export function normalizePeak(
  samples: Float32Array,
  target = 0.85,
  maxGain = 8
): Float32Array {
  let peak = 0;
  for (let i = 0; i < samples.length; i += 1) {
    const v = samples[i] < 0 ? -samples[i] : samples[i];
    if (v > peak) peak = v;
  }
  if (peak < MIN_PEAK) return samples;

  const gain = Math.min(target / peak, maxGain);
  // 已经够响就不动：放大一个本来就正常的录音只会让齿音更刺耳
  if (gain <= 1.02) return samples;

  const out = new Float32Array(samples.length);
  for (let i = 0; i < samples.length; i += 1) out[i] = samples[i] * gain;
  return out;
}

/** Float32 [-1,1] → 16bit PCM 的 WAV。手写 44 字节头，不引第三方库。 */
export function encodeWav(samples: Float32Array, rate: number): Blob {
  const buffer = new ArrayBuffer(44 + samples.length * 2);
  const view = new DataView(buffer);
  const ascii = (offset: number, text: string) => {
    for (let i = 0; i < text.length; i += 1) view.setUint8(offset + i, text.charCodeAt(i));
  };

  ascii(0, "RIFF");
  view.setUint32(4, 36 + samples.length * 2, true);
  ascii(8, "WAVE");
  ascii(12, "fmt ");
  view.setUint32(16, 16, true); // PCM 头长度
  view.setUint16(20, 1, true); // 1 = PCM
  view.setUint16(22, 1, true); // 单声道
  view.setUint32(24, rate, true);
  view.setUint32(28, rate * 2, true); // 每秒字节数
  view.setUint16(32, 2, true); // 每帧字节数
  view.setUint16(34, 16, true); // 位深
  ascii(36, "data");
  view.setUint32(40, samples.length * 2, true);

  let offset = 44;
  for (let i = 0; i < samples.length; i += 1, offset += 2) {
    // 先夹到 [-1,1]：不夹的话爆音会被截成随机值（负数溢出听起来像"咔"）
    const s = Math.max(-1, Math.min(1, samples[i]));
    view.setInt16(offset, s < 0 ? s * 0x8000 : s * 0x7fff, true);
  }
  return new Blob([buffer], { type: "audio/wav" });
}

/** Float32 [-1,1] → Int16 采样。流式用，没有容器头。 */
function toInt16(samples: Float32Array): Int16Array {
  const out = new Int16Array(samples.length);
  for (let i = 0; i < samples.length; i += 1) {
    const s = Math.max(-1, Math.min(1, samples[i]));
    out[i] = s < 0 ? s * 0x8000 : s * 0x7fff;
  }
  return out;
}

/** 重采样到 16k。用 OfflineAudioContext 而不是手写线性插值：
 *  浏览器自带的抗混叠比手写的好，而且这是浏览器原生能力，不增加体积。
 *  **只用于一次性模式** —— 流式不能等整段录完。 */
async function resample(samples: Float32Array, from: number): Promise<Float32Array> {
  if (from === TARGET_RATE) return samples;
  const frames = Math.max(1, Math.round((samples.length * TARGET_RATE) / from));
  const ctx = new OfflineAudioContext(1, frames, TARGET_RATE);
  const buffer = ctx.createBuffer(1, samples.length, from);
  // 拷贝一份再塞进 AudioBuffer：`getChannelData` 拿到的是 Float32Array<ArrayBufferLike>，
  // 直接传给 copyToChannel 在 TS 5.7 之后过不了（可 SharedArrayBuffer 的泛型）
  const channel = new Float32Array(samples.length);
  channel.set(samples);
  buffer.copyToChannel(channel, 0);
  const node = ctx.createBufferSource();
  node.buffer = buffer;
  node.connect(ctx.destination);
  node.start();
  const rendered = await ctx.startRendering();
  return rendered.getChannelData(0);
}

/**
 * 实时重采样。只在 **浏览器不认 16k 采样率** 时才用（Safari 会忽略这个参数）。
 *
 * ## 为什么这个必须存在
 *
 * 流式直接发 PCM，没有"事后重采样"这一步。如果拿到的是 48k 的帧却当成 16k
 * 发出去，腾讯云按 16k 解会得到 3 倍速的音频 —— 人耳听是叽里呱啦，识别结果
 * 是一两个字或者全空。这个错**不会报错**，只会"识别不出来"。
 *
 * ## 为什么每帧独立插值、不跨帧保持相位
 *
 * 跨帧保相位要维护尾巴和小数偏移，代码复杂度翻几倍；而不保的代价是每帧
 * 接缝处最多 1/3 个输入样本的相位跳变（48k 下约 7 微秒），远小于一个音素的
 * 长度，对识别没有任何影响。用 `acc` 累积小数余量，保证长期采样率比例准确。
 */
class StreamResampler {
  private ratio: number;
  private acc = 0;

  constructor(from: number, to: number) {
    this.ratio = from / to;
  }

  push(frame: Float32Array): Float32Array {
    const want = frame.length / this.ratio + this.acc;
    const n = Math.floor(want);
    this.acc = want - n;
    const out = new Float32Array(n);
    for (let i = 0; i < n; i += 1) {
      const src = i * this.ratio;
      const j = Math.floor(src);
      const frac = src - j;
      const a = frame[j] ?? 0;
      const b = frame[j + 1] ?? a;
      out[i] = a * (1 - frac) + b * frac;
    }
    return out;
  }
}

function joined(chunks: Float32Array[]): Float32Array {
  const total = chunks.reduce((n, c) => n + c.length, 0);
  const out = new Float32Array(total);
  let at = 0;
  for (const c of chunks) {
    out.set(c, at);
    at += c.length;
  }
  return out;
}

/**
 * 流式端点的地址。
 *
 * ## 为什么不能写相对路径
 *
 * 生产环境 `/api/*` 全走 Next.js 的 rewrites 到后端 8000，但 **rewrites
 * 不支持 WebSocket 升级**（Next 官方限制），所以 nginx 必须把
 * `/api/capture/ws` 单独 proxy_pass 到 8000 并带上 Upgrade 头。
 * 浏览器这边看到的仍然是同域同路径，所以生产就是相对路径。
 *
 * ## 开发环境为什么是 8000
 *
 * 本机前端在 3100、后端在 8000，Next dev 同样代理不了 WS。
 * 这里按端口判断而不是按环境变量：手写一个 `NEXT_PUBLIC_ASR_WS` 意味着
 * 每个新拉代码的人都要先知道要去配它，而没配的症状是"语音静默失效"。
 */
export function streamUrl(): string {
  const override = process.env.NEXT_PUBLIC_ASR_WS;
  if (override) return override;
  if (typeof window === "undefined") return "";
  const proto = window.location.protocol === "https:" ? "wss:" : "ws:";
  const dev = process.env.NODE_ENV === "development";
  if (dev && window.location.port !== "8000") {
    return `ws://${window.location.hostname}:8000/api/capture/ws`;
  }
  return `${proto}//${window.location.host}/api/capture/ws`;
}

export function useVoiceInput({ onText, onError, onFrame, streaming = false }: Callbacks) {
  const [phase, setPhase] = useState<VoicePhase>("idle");
  const [seconds, setSeconds] = useState(0);
  /**
   * 实时音量 0-1，给波形用。
   *
   * 只做"能看出在说话"这一件事：手机收音的绝对电平差异很大（同一个字，
   * 离 10cm 和 30cm 能差 4 倍），所以这里用的是**相对当前录音**的 RMS 放大，
   * 不是音量表。用户看它只判断"麦克风有没有收到声音"，不做别的。
   */
  const [level, setLevel] = useState(0);
  const session = useRef<Session | null>(null);
  // 回调存 ref：调用方通常写成内联函数，直接进依赖数组会让 start/stop 每帧重建，
  // 而 stop 被重建时正在录音的 session 还是老的 —— 表现为"点了停止没反应"。
  const cbs = useRef({ onText, onError, onFrame });
  cbs.current = { onText, onError, onFrame };
  /** 实际走的哪条路。调用方据此决定界面画"边说边出字"还是"转写中" */
  const [activeStream, setActiveStream] = useState(false);

  /** 只关采集资源，**不关 WebSocket** —— 流式模式下还要靠它收尾包。 */
  const stopAudio = useCallback((cur: Session) => {
    window.clearInterval(cur.timer);
    cur.proc.onaudioprocess = null;
    try {
      cur.source.disconnect();
      cur.proc.disconnect();
    } catch {
      // 已经断开的节点再 disconnect 会抛，这不影响后续
    }
    cur.stream.getTracks().forEach((t) => t.stop());
    void cur.ctx.close();
    setLevel(0); // 不清的话，波形停在最后一帧的高度上，看起来像"还在录"
  }, []);

  const teardown = useCallback(() => {
    const cur = session.current;
    if (!cur) return null;
    session.current = null;
    window.clearTimeout(cur.finishTimer);
    stopAudio(cur);
    if (cur.ws) {
      // onclose/onmessage 之后要能区分"我主动关的"和"对面掉了"，
      // 先把回调摘掉再关，避免自己触发自己的错误提示
      cur.ws.onmessage = null;
      cur.ws.onclose = null;
      cur.ws.onerror = null;
      try {
        cur.ws.close();
      } catch {
        // 连接可能已经没了
      }
    }
    return cur;
  }, [stopAudio]);

  /** 流式：把写满了的包发出去。不满的留着，下次接着凑。 */
  const flush = useCallback((cur: Session, force = false) => {
    if (!cur.ws || !cur.wsOpen) return;
    if (cur.accLen === 0) return;
    // 不 force 时只发整包：上游按 200ms 节奏吃数据，发半包会让 VAD 判不准
    if (!force && cur.accLen < CHUNK_SAMPLES) return;
    const payload = cur.acc.slice(0, cur.accLen);
    try {
      cur.ws.send(payload.buffer);
    } catch {
      // 连接已断。不再重连：这一轮用户已经在说，重连会丢中间的字，
      // 收尾时走一次性上传更完整。
      cur.wsOpen = false;
    }
    cur.accLen = 0;
  }, []);

  const stop = useCallback(async () => {
    const cur = session.current;
    if (!cur) return;

    if (cur.ws && cur.wsOpen) {
      // ---------- 流式收尾 ----------
      stopAudio(cur);
      // 剩下的半包也要发：最后 100ms 常常正是最后一个字
      flush(cur, true);
      setSeconds(0);
      setPhase("finishing");

      let settled = false;
      const finish = (text: string | null) => {
        if (settled) return;
        settled = true;
        window.clearTimeout(cur.finishTimer);
        teardown();
        setPhase("idle");
        if (text) cbs.current.onText(text);
      };

      // 上游没吐完（网络卡住）也要收尾，不能把用户晾在"正在整理"
      cur.finishTimer = window.setTimeout(() => {
        finish(null);
        cbs.current.onError("没听到结尾，再说一遍");
      }, FINISH_TIMEOUT_MS);

      try {
        cur.ws.send(JSON.stringify({ type: "end" }));
      } catch {
        finish(null);
        cbs.current.onError("网络断了，再说一遍");
      }
      return;
    }

    // ---------- 一次性收尾（含流式失败后的降级）----------
    const audio = teardown();
    if (!audio) return;
    setSeconds(0);

    const pcm = joined(audio.chunks);
    // 0.3 秒以下基本是误触（或点了立刻点停），直接当"没说话"
    if (pcm.length < audio.rate * 0.3) {
      setPhase("idle");
      cbs.current.onError("没录到声音，再说一遍");
      return;
    }

    setPhase("transcribing");
    try {
      // 先归一化再重采样：重采样是线性运算，顺序不影响结果，
      // 但先做能在原始采样率上判断"这段到底有没有人说话"（重采样后峰值会变）。
      const wav = encodeWav(await resample(normalizePeak(pcm), audio.rate), TARGET_RATE);
      const { text } = await api.capture.transcribe(wav);
      cbs.current.onText(text);
    } catch (err) {
      cbs.current.onError((err as Error)?.message || "语音没转成，先打字吧");
    } finally {
      setPhase("idle");
    }
  }, [stopAudio, teardown]);

  const start = useCallback(async () => {
    if (session.current || typeof navigator === "undefined") return;
    if (!navigator.mediaDevices?.getUserMedia) {
      cbs.current.onError("这个浏览器不支持录音，先打字吧");
      return;
    }

    let stream: MediaStream;
    try {
      stream = await navigator.mediaDevices.getUserMedia({
        // ★ 采集约束直接决定识别率，改之前先读完这段：
        //
        // noiseSuppression: **必须关**。它是为通话设计的降噪（WebRTC APM 那套），
        //   在手机上会优先削掉 2-4kHz 的弱能量段，而中文声母 s/sh/x/j/q/zh/ch
        //   正好在这个频段。开着它录出来的声音"人耳听着干净"，识别引擎却少了
        //   区分字头的信息 —— 表现为成片同音错字，且录音回放听起来完全正常。
        // echoCancellation: **关**。浏览器端 AEC 会对近场信号做非线性处理，
        //   同样伤辅音；我们也没有远端回声要消。
        // autoGainControl: **开**。补上麦克风增益。流式模式下它是唯一的电平
        //   保证（归一化要整段录完才能算，流式等不了）。
        audio: {
          channelCount: 1,
          echoCancellation: false,
          noiseSuppression: false,
          autoGainControl: true,
        },
      });
    } catch (err) {
      // 权限拒绝和"没有麦克风"在浏览器里是同一个 catch，但用户要做的事不同
      const name = (err as DOMException)?.name;
      cbs.current.onError(
        name === "NotAllowedError"
          ? "浏览器没给麦克风权限，在地址栏允许后再试"
          : "没找到麦克风，先打字吧"
      );
      return;
    }

    // 直接按 16k 建 context：省掉一次 48k→16k 的重采样，少一处理论上的失真。
    // Safari 对自定义采样率支持不全 —— 那种情况下 `ctx.sampleRate` 会是 48000/44100，
    // 下面按它建 StreamResampler，否则发出去的 PCM 会被上游当成 3 倍速。
    let ctx: AudioContext;
    try {
      ctx = new AudioContext({ sampleRate: TARGET_RATE });
    } catch {
      ctx = new AudioContext();
    }
    // iOS 上新建的 context 可能是 suspended（尤其从静音开关/后台切回来），
    // 不 resume 的话 ScriptProcessor 不会回调，录完是一段全零 —— 表现为"没录到声音"。
    if (ctx.state === "suspended") {
      try {
        await ctx.resume();
      } catch {
        // 恢复不了也让流程继续：录不到会走"没录到声音"的分支，比卡在"录音中"强
      }
    }

    const cur: Session = {
      ctx,
      stream,
      source: ctx.createMediaStreamSource(stream),
      proc: null as unknown as ScriptProcessorNode,
      chunks: [],
      rate: ctx.sampleRate,
      timer: 0,
      ws: null,
      wsOpen: false,
      acc: new Int16Array(CHUNK_SAMPLES),
      accLen: 0,
      resampler: ctx.sampleRate === TARGET_RATE ? null : new StreamResampler(ctx.sampleRate, TARGET_RATE),
      finishTimer: 0,
    };

    // 1024 而不是 4096：4096 在 16k 下是 256ms 一帧，波形只有 4 帧/秒，看着像卡住。
    // 1024 是 64ms（约 15 帧/秒），够顺，又不至于让回调占满主线程。
    cur.proc = ctx.createScriptProcessor(1024, 1, 1);
    let lastLevelAt = 0;
    cur.proc.onaudioprocess = (event) => {
      // 必须拷一份：inputBuffer 的底层数组会被下一帧复用，
      // 直接 push 引用的话，录完只剩最后一帧的声音（听起来像"只有半个字"）
      const frame = event.inputBuffer.getChannelData(0);
      const owned = new Float32Array(frame);
      // 留着给降级用：WS 半路挂掉时，这段音频还能走一次性上传
      cur.chunks.push(owned);

      if (cur.wsOpen) {
        const pcm = toInt16(cur.resampler ? cur.resampler.push(owned) : owned);
        let at = 0;
        while (at < pcm.length) {
          const take = Math.min(CHUNK_SAMPLES - cur.accLen, pcm.length - at);
          cur.acc.set(pcm.subarray(at, at + take), cur.accLen);
          cur.accLen += take;
          at += take;
          if (cur.accLen >= CHUNK_SAMPLES) flush(cur);
        }
      }

      // 波形电平：70ms 节流。每帧 setState 会让整个抽屉每秒重渲染十几次，
      // 比波形本身更耗电。
      const now = Date.now();
      if (now - lastLevelAt >= 70) {
        lastLevelAt = now;
        let sum = 0;
        for (let i = 0; i < frame.length; i += 1) sum += frame[i] * frame[i];
        // ×6 是经验值：正常说话 RMS 在 0.02-0.08，乘完落在 0.12-0.5 ——
        // 不会一直贴着 0，也不会一开口就顶满。
        setLevel(Math.min(1, Math.sqrt(sum / frame.length) * 6));
      }
    };
    cur.source.connect(cur.proc);
    // 连到 destination 才触发 onaudioprocess。直连会把这路声音放出来（回声），
    // 所以中间挂一个 0 增益的节点。
    const mute = ctx.createGain();
    mute.gain.value = 0;
    cur.proc.connect(mute);
    mute.connect(ctx.destination);

    cur.timer = window.setInterval(() => {
      setSeconds((prev) => prev + 1);
    }, 1000);

    session.current = cur;
    setSeconds(0);
    setPhase("recording");

    // ---------- 流式连接放在采集起来之后 ----------
    // 反过来（先连再开麦）会让"连不上"卡在权限弹窗之前，用户看到的是一段静默
    // 的空白期，而那时候他还不知道要不要允许麦克风。
    if (!streaming) {
      setActiveStream(false);
      return;
    }
    setActiveStream(true);

    let ws: WebSocket;
    try {
      ws = new WebSocket(streamUrl());
    } catch {
      setActiveStream(false);
      return; // 建不起来就静默降级，收尾时走一次性上传
    }
    ws.binaryType = "arraybuffer";
    cur.ws = ws;

    ws.onopen = () => {
      // 真正能发音频要等 `ready`（那是上游握手成功的信号）。这里不能直接置
      // wsOpen=true：签名不对时连接也会 onopen，然后立刻被上游关掉。
    };
    ws.onmessage = (event) => {
      let frame: StreamFrame;
      try {
        frame = JSON.parse(String(event.data)) as StreamFrame;
      } catch {
        return;
      }
      if (frame.type === "ready") {
        cur.wsOpen = true;
        cbs.current.onFrame?.(frame);
        return;
      }
      cbs.current.onFrame?.(frame);
      if (frame.type === "done") {
        // 上游说全结束了：收尾（这里可能是自动结束的那条路，也可能是 stop 等的那条）
        window.clearTimeout(cur.finishTimer);
        const text = frame.text;
        teardown();
        setPhase("idle");
        if (text) cbs.current.onText(text);
        return;
      }
      if (frame.type === "error") {
        window.clearTimeout(cur.finishTimer);
        const wasOpen = cur.wsOpen;
        cur.wsOpen = false;
        cbs.current.onError(frame.message);
        if (!wasOpen) {
          // 握手就没成功 —— 立刻退回一次性识别，让用户不用重说
          setActiveStream(false);
          teardown();
          setPhase("idle");
        }
      }
    };
    ws.onclose = () => {
      if (cur.wsOpen) {
        cur.wsOpen = false;
        cbs.current.onError("语音连接断了，再说一遍");
        teardown();
        setPhase("idle");
      }
    };
    ws.onerror = () => {
      // onerror 之后必然有 onclose，错误提示交给 onclose 统一出，避免弹两次
    };
  }, [flush, streaming, teardown]);

  const cancel = useCallback(() => {
    teardown();
    setSeconds(0);
    setPhase("idle");
  }, [teardown]);

  // 卸载时一定要停：不停的话麦克风指示灯会一直亮着，用户以为被偷听
  useEffect(() => () => void teardown(), [teardown]);

  // 60 秒是上游单次上限，到点自动停 —— 不自动停的话上游会在 60 秒处
  // 强制断句，后面的字全丢，用户白说了一分钟。
  // 放在 effect 里而不是 setInterval 的更新函数里：更新函数在 StrictMode 下
  // 会被调用两次，等于 stop 跑两遍。
  useEffect(() => {
    if (phase === "recording" && seconds >= MAX_SECONDS) void stop();
  }, [phase, seconds, stop]);

  return { phase, seconds, level, start, stop, cancel, streaming: activeStream };
}

"use client";

// 「提醒」在设置页只剩这一张小卡（2026-11-18）。
//
// ## 来龙去脉
//
//   · 11-11：整组提醒设置（权限、设备清单、邮件兜底、课程日历、免打扰）搬进了
//     「待办 → 设置」，设置页只留一行灰字指路 —— 理由是"两个地方都能开关同一件事，
//     迟早出现'在这关了那边还显示开着'"。
//   · 11-18：用户看不懂那行灰字。原话是「这个用户不知道是什么意思」，指着
//     「提醒权限、已开启提醒的设备，都在「待办 → 设置」里」。
//     这是指路文案的经典失败：句子在描述一个地址，而用户要的是一个开关。
//
// ## 现在的分工
//
//   这里：**这台设备响不响** —— 一个开关 + 一行状态 + 一步进详细设置。
//         这是唯一一件用户会在设置页临时想起来的事（"我这台怎么不响"）。
//   详细设置（/reminders?tab=settings）：设备清单、邮件兜底、课程日历、
//         每日回顾、免打扰 —— 一年改一次，不值得占设置页的版面。
//
// ## 为什么"两个地方能开关"这次可以接受
//
//   两边都不是本地状态：开关读的是 `GET /api/push/status` + `findMyDevice()`，
//   写的是浏览器的 `pushManager.subscribe/unsubscribe`（服务端那份跟着变）。
//   所以不存在"这边关了那边还显示开着" —— 除非页面停留着没刷新，
//   而那是所有远端状态的共同前提，不是这一处的问题。
//
// ## 三个不能含糊的地方（和待办页那张卡同源）
//
//   ① 开关管的是**本机**，不是账号。`subscribed` 是账号级的，直接拿它渲染
//      「已开启」，在从没开过的电脑上就是假话。
//   ② 别的设备只能关不能开（碰不到那台浏览器），所以清单不给这里，只在页脚报个数。
//   ③ 关掉 ≠ 删数据。文案必须这么说，否则用户以为待办没了。
import { useCallback, useEffect, useState } from "react";
import Link from "next/link";
import { api } from "@/lib/api";
import {
  pushSupport,
  notificationPermission,
  enablePush,
  disablePush,
  findMyDevice,
} from "@/lib/push";
import type { PushDevice } from "@/lib/types";
import { Switch } from "@/components/console/ui";

type View =
  | "loading"
  | "error"
  | "insecure"
  | "unsupported"
  | "ios"
  | "denied"
  | "off"
  | "other"
  | "on";

export default function ReminderQuick() {
  const [view, setView] = useState<View>("loading");
  const [alive, setAlive] = useState<PushDevice[]>([]);
  const [busy, setBusy] = useState(false);
  const [note, setNote] = useState("");

  const refresh = useCallback(async () => {
    const sup = pushSupport();
    if (sup === "insecure") return setView("insecure");
    if (sup === "ios-needs-install") return setView("ios");
    if (sup !== "ready") return setView("unsupported");
    if (notificationPermission() === "denied") return setView("denied");

    const s = await api.push.status();
    // `status` 返回 null 是**请求失败**，不是"浏览器不支持"。
    // 混成 unsupported 会对着一个其实能收通知的浏览器说"你收不到"。
    if (!s) return setView("error");
    if (!s.supported) return setView("unsupported");

    const devices = s.device_list || [];
    const my = await findMyDevice(devices);
    setAlive(devices.filter((d) => !d.disabled));
    if (my) setView("on");
    else if (devices.some((d) => !d.disabled)) setView("other");
    else setView("off");
  }, []);

  useEffect(() => {
    void refresh();
  }, [refresh]);

  const toggle = useCallback(
    async (next: boolean) => {
      if (busy) return;
      setBusy(true);
      setNote("");
      if (next) {
        const res = await enablePush();
        if (res.ok) {
          await refresh();
        } else if (res.reason === "denied") {
          setView("denied");
        } else {
          if (res.detail) console.warn("[push] 订阅失败：", res.detail);
          setNote("连不上通知服务，这台暂时收不到");
        }
      } else {
        // 本机退订时浏览器那边也要撤，否则服务端删了行、浏览器还留着悬空订阅
        await disablePush();
        await refresh();
        setNote("已关掉这台。待办和提醒都还在。");
      }
      setBusy(false);
    },
    [busy, refresh],
  );

  const toggleable = view === "on" || view === "off" || view === "other";
  const otherCount = alive.length;

  // 一行说完"这台响不响"。比待办页那张卡短一档：这里不是主场地，
  // 长句会把它变成一段正文，而用户只是路过看了一眼。
  const hint = (() => {
    switch (view) {
      case "loading":
        return "正在看这台设备的通知权限…";
      case "error":
        return "没读到通知状态，刷新试试。";
      case "insecure":
        return "当前是 http 地址，浏览器不给通知权限。";
      case "ios":
        return "iPhone 要先「添加到主屏」，从主屏打开才有通知。";
      case "unsupported":
        return "这个浏览器收不到通知（安卓的网页推送走 Google 服务）。";
      case "denied":
        return "通知被拒过，要在地址栏的锁里改成「允许」。";
      case "on":
        return "开着。到点会通知这台设备。";
      case "other":
        return `这台还没开，提醒发往另外 ${otherCount} 台。`;
      default:
        return "打开后，到点会通知这台设备。";
    }
  })();

  return (
    <section className="card card-pad">
      <div className="card-head">
        <span className="card-title">这台设备的提醒</span>
        <Switch
          checked={view === "on"}
          label="这台设备的提醒"
          disabled={busy || !toggleable}
          onChange={(next) => void toggle(next)}
        />
      </div>

      <p className="hint" style={{ marginTop: 6 }}>
        {hint}
      </p>
      {note ? (
        <p className="hint" style={{ marginTop: 4 }}>
          {note}
        </p>
      ) : null}

      {/* 整行可点：左边报个数（"我有几台在收"），右边一步进详细设置。
          以前这一行是一句 12 字的灰字，用户读完了还不知道能不能点。 */}
      <Link href="/reminders?tab=settings" className="rem-quick-foot">
        <span className="meta">
          {otherCount > 0 ? `${otherCount} 台设备已开启提醒` : "还没有设备开启提醒"}
        </span>
        <span className="rem-quick-more">
          详细设置
          <span aria-hidden="true">›</span>
        </span>
      </Link>
    </section>
  );
}

/**
 * 去掉「没有来源可指」的引用编号。
 *
 * 为什么需要：模型会照着上下文里的历史回答（老会话里全是 `[1]` / `依据：[1][2]`）
 * 继续写编号，即使这一轮压根没检索、没联网。用户看到的是一排**点了没反应**的
 * 小方块 —— 它长得像引用，实际上什么都不是，末尾那句「依据：[1][2]」更是无中生有。
 *
 * 规则（只删指不到的，不动真引用）：
 *   [Wn] → webIds 里有 n 才留，否则删
 *   [n]  → refIds 里有 n 才留，否则删（`[文案](url)` 这类 markdown 链接不碰）
 *   整行只剩「依据：」这类前缀时，连行一起删 —— 没有依据却写"依据"是事实错误
 *
 * ★ 只在**回答结束之后**调用（streaming 期间不能调）：联网来源是收尾时才下发的，
 *   流式途中 webIds 还是空的，这时清理会把本轮所有真角标一起删掉，等来源到了
 *   再"长回来"，用户看到的是角标在闪。
 */
export interface CiteLookup {
  /** 本条回答里真实存在的资料库来源编号 */
  refIds: Set<number>;
  /** 本条回答里真实存在的联网来源编号（W 后面的数字） */
  webIds: Set<number>;
}

const WEB_TOKEN = /\[W(\d{1,3})\]/gi;
/** 排除 `[1](url)`：那是 markdown 链接的文案，不是引用 */
const REF_TOKEN = /\[(\d{1,3})\](?!\()/g;
/** 删干净之后只剩前缀的行：依据 / 参考资料 / 参考来源 / 引用来源 / Sources */
const BARE_TAIL =
  /^\s*(?:\*\*)?\s*(依据|参考资料|参考来源|引用来源|来源|sources?)\s*[:：]\s*(?:\*\*)?\s*[\[\]\d\s,，、;；&]*$/i;

export function stripPhantomCitations(text: string, { refIds, webIds }: CiteLookup): string {
  if (!text) return text;
  let out = text;

  // 1) 联网编号：指不到就删。连同前面一个空格一起删，避免留下「结论 」这种尾空格。
  if (webIds.size === 0) {
    out = out.replace(/\s?\[W\d{1,3}\]/gi, "");
  } else {
    out = out.replace(/\s?\[W(\d{1,3})\]/gi, (all, d: string) =>
      webIds.has(Number(d)) ? all : ""
    );
  }

  // 2) 资料库编号：同上。没有资料库来源时整类清掉。
  if (refIds.size === 0) {
    out = out.replace(/\s?\[(\d{1,3})\](?!\()/g, "");
  } else {
    out = out.replace(/\s?\[(\d{1,3})\](?!\()/g, (all, d: string) =>
      refIds.has(Number(d)) ? all : ""
    );
  }

  if (out === text) return text;

  // 3) 逐行收尾：只剩光杆前缀的行直接删；顺手去掉行尾空格和多余空行。
  const lines = out.split("\n");
  const kept: string[] = [];
  for (const line of lines) {
    if (BARE_TAIL.test(line)) continue;
    kept.push(line.replace(/[ \t]+$/, ""));
  }
  out = kept.join("\n").replace(/\n{3,}/g, "\n\n");
  return out.replace(/\s+$/, "");
}

"use client";

// 知识库域：库列表、名称映射、上传建库 / 联网建库进度 / 删库删文件 / 重建 / 搜索预览
import { useCallback, useEffect, useMemo, useState } from "react";
import { api } from "@/lib/api";
import type { KbInfo, PublicKbInfo, SearchResult, FavoriteKbInfo } from "@/lib/types";
import { describeParams, type ChunkParams } from "@/lib/chunkProfiles";
import { forgetKbChunk, loadKbChunks, saveKbChunks, type KbChunkMap } from "@/lib/kbChunkPrefs";
import type { ShowToast } from "./useToast";

export function useKnowledge(showToast: ShowToast, chunkSize: number, chunkOverlap: number) {
  const [kbs, setKbs] = useState<KbInfo[]>([]);
  // 全站公开库（别人的）：挂进对话当检索源用。不是核心功能，
  // 拉取失败静默降级成空列表——不能因为它挡住自己的库列表。
  const [publicKbs, setPublicKbs] = useState<PublicKbInfo[]>([]);
  /**
   * 我收藏的公开库。
   *
   * 为什么单开一份而不是从 publicKbs 里筛：广场是"全站有什么"，收藏是
   * "我选了哪些"。用户明确要求一开始不把全站公开库都铺在资料库里 ——
   * 面板上默认只看收藏，想看全部再去广场挑。所以收藏必须独立成组。
   */
  const [favKbs, setFavKbs] = useState<FavoriteKbInfo[]>([]);
  // 首屏库列表还没回来：右栏渲染骨架
  const [loading, setLoading] = useState(true);
  // 每个库各自的处理方式（浏览器本地）。用 effect 读，避免 SSR 期访问 localStorage
  const [kbChunks, setKbChunks] = useState<KbChunkMap>({});

  useEffect(() => {
    setKbChunks(loadKbChunks());
  }, []);

  /** 记住某个库这次用的参数，供列表标签和「重新处理」复用 */
  const rememberChunk = useCallback((kbId: string, params: ChunkParams) => {
    setKbChunks((prev) => {
      const old = prev[kbId];
      if (old && old.size === params.size && old.overlap === params.overlap) return prev;
      const next = { ...prev, [kbId]: params };
      saveKbChunks(next);
      return next;
    });
  }, []);

  /** 这个库该用哪套参数：记过就用记录的，没记过（老库/首次）用全局兜底值 */
  const chunkParamsOf = useCallback(
    (kbId: string | null | undefined): ChunkParams =>
      (kbId ? kbChunks[kbId] : undefined) ?? { size: chunkSize, overlap: chunkOverlap },
    [kbChunks, chunkSize, chunkOverlap]
  );

  const refreshKbs = useCallback(async () => {
    try {
      const { kbs: list } = await api.listKbs();
      setKbs(list);
    } catch (e) {
      console.error(e);
      // 同文件里 deleteKb / rebuildKb / deleteKbFile 失败都会 toast，只有这里静默：
      // 删完库再刷新失败的话，右栏还挂着已经删掉的库，用户会以为没删掉、再点一次。
      showToast("error", "资料库列表刷新失败，请稍后重试");
    }
    // 公开库顺带刷一份：自己的库变了，别人公开的库也可能增减。
    // 失败不 toast——它是辅助列表，空着只是少几个可挂载的库。
    api
      .listPublicKbs()
      .then((r) => setPublicKbs(r.kbs))
      .catch(() => {});
    // 收藏同理：库被收回 / 删掉后收藏也会消失，跟着一起刷新才是真相
    api
      .listFavoriteKbs()
      .then((r) => setFavKbs(r.kbs))
      .catch(() => {});
  }, [showToast]);

  // 初始化：拉知识库列表（与 sessions/defaults 的请求并发）
  useEffect(() => {
    let alive = true;
    (async () => {
      const [k, pub, fav] = await Promise.all([
        api.listKbs().catch(() => null),
        api.listPublicKbs().catch(() => null),
        api.listFavoriteKbs().catch(() => null),
      ]);
      if (!alive) return;
      if (k) setKbs(k.kbs);
      if (pub) setPublicKbs(pub.kbs);
      if (fav) setFavKbs(fav.kbs);
      setLoading(false);
    })();
    return () => {
      alive = false;
    };
  }, []);

  /**
   * 收藏 / 取消收藏。乐观更新列表，失败再回滚 ——
   * 星标是"点一下就该亮"的东西，等一个来回的网络会让人以为没点上、再点一次。
   */
  const toggleFavorite = useCallback(
    async (kbId: string, on: boolean) => {
      const before = favKbs;
      if (!on) {
        setFavKbs((list) => list.filter((x) => x.kb_id !== kbId));
      }
      try {
        if (on) {
          await api.addFavorite(kbId);
        } else {
          await api.removeFavorite(kbId);
        }
        // 加收藏要把来源、作者、日期一起拿到手，本地拼不出来 → 重拉
        const r = await api.listFavoriteKbs();
        setFavKbs(r.kbs);
      } catch (e) {
        setFavKbs(before);
        showToast("error", e instanceof Error ? e.message : "操作失败，请稍后重试");
      }
    },
    [favKbs, showToast]
  );

  // kb_id → 中文显示名映射（侧栏/顶栏展示用）
  const kbNameMap = useMemo(() => {
    const m: Record<string, string> = {};
    for (const k of kbs) m[k.kb_id] = k.name || k.kb_id;
    return m;
  }, [kbs]);

  // 上传文档建库：先把中文名解析为安全 kb_id，再上传。
  // size/overlap 由面板按「处理方式」档位传入；没传则用全局兜底值。
  // 成功时返回落到哪个库，交给编排层决定要不要顺手绑定（失败返回 null，错误已 toast）。
  const uploadFiles = async (
    kbName: string,
    files: File[],
    size?: number,
    overlap?: number
  ): Promise<string | null> => {
    const params: ChunkParams = {
      size: size ?? chunkSize,
      overlap: overlap ?? chunkOverlap,
    };
    // 本次是否新建了库：上传失败要把它删掉，否则列表里会多一个名字相同、里面空空的库
    let createdId: string | null = null;
    try {
      // 名字对上已有库则复用，避免手打差一点就新建同名库
      const norm = kbName.trim().toLowerCase();
      const existing = kbs.find((k) => (k.name || "").trim().toLowerCase() === norm);
      let kb_id: string;
      if (existing) {
        kb_id = existing.kb_id;
      } else {
        kb_id = (await api.createKb(kbName)).kb_id;
        createdId = kb_id;
      }
      const r = await api.uploadFiles(kb_id, files, params.size, params.overlap);
      // 建库/追加成功才记档位：失败回滚的库不该留下记录
      rememberChunk(kb_id, params);
      showToast("success", `已导入 ${r.chunks} 个片段到「${kbName}」`);
      return kb_id;
    } catch (e) {
      // 回滚空壳库（复用已有库时不删，那里面可能有别的文件）
      if (createdId) {
        await api.deleteKb(createdId).catch(() => {});
        createdId = null;
      }
      const msg = e instanceof Error ? e.message : "上传失败，请稍后重试";
      showToast("error", msg);
      return null;
    } finally {
      refreshKbs();
    }
  };

  // 删除库内单个文件：只清它的片段，不动其他文件
  const deleteKbFile = async (kbId: string, name: string) => {
    try {
      const r = await api.deleteKbFile(kbId, name);
      showToast("success", r.removed > 0 ? `已删除「${name}」的 ${r.removed} 个片段` : `已移除「${name}」`);
      refreshKbs();
    } catch (e) {
      showToast("error", e instanceof Error ? e.message : "删除文件失败，请稍后重试");
    }
  };

  // 按这个库自己的处理方式重新切整库（要重新 embedding，所以面板上点了要确认）
  const rebuildKb = async (kbId: string) => {
    const { size, overlap } = chunkParamsOf(kbId);
    try {
      const r = await api.rebuildKb(kbId, size, overlap);
      showToast("success", `已按「${describeParams(size, overlap)}」重新整理，共 ${r.chunks} 个片段`);
      refreshKbs();
    } catch (e) {
      showToast("error", e instanceof Error ? e.message : "重新整理失败，请稍后重试");
    }
  };

  const searchPreview = async (keyword: string): Promise<SearchResult[]> => {
    const r = await api.searchPreview(keyword);
    return r.results;
  };

  const deleteKb = async (kbId: string) => {
    try {
      await api.deleteKb(kbId);
      // 库没了，本地记的档位也一并清掉（否则重建同名库会继承旧设置）
      forgetKbChunk(kbId);
      setKbChunks((prev) => {
        if (!(kbId in prev)) return prev;
        const next = { ...prev };
        delete next[kbId];
        return next;
      });
      showToast("info", "资料库已删除");
      refreshKbs();
    } catch (e) {
      showToast("error", "删除失败，请稍后重试");
    }
  };

  return {
    kbs,
    publicKbs,
    favKbs,
    toggleFavorite,
    kbNameMap,
    loading,
    refreshKbs,
    uploadFiles,
    deleteKbFile,
    rebuildKb,
    searchPreview,
    deleteKb,
    /** 供面板回填每个库的处理方式标签 */
    kbChunks,
    rememberChunk,
    chunkParamsOf,
  };
}

